-- MIR 2017: 235 preguntas (231 con respuesta + 4 anuladas). Idempotente: no inserta si ya existe (año=2017, numero).
-- No incluye BEGIN/COMMIT: lo decide quien lo invoca. Las imágenes van aparte en public/imagenes-mir/2016/.
INSERT INTO preguntas ("año",numero,especialidad,tema,pregunta,opcion_a,opcion_b,opcion_c,opcion_d,correcta,explicacion,explicacion_calidad,imagen_path,origen,anulada,motivo_anulacion,requiere_revision,motivo_revision)
SELECT 2017,r.numero,r.especialidad,r.tema,r.pregunta,r.opcion_a,r.opcion_b,r.opcion_c,r.opcion_d,r.correcta,r.explicacion,r.explicacion_calidad,r.imagen_path,'oficial',r.anulada,r.motivo_anulacion,r.requiere_revision,r.motivo_revision
FROM jsonb_to_recordset($J$[{"numero": 1, "especialidad": "Cardiología", "tema": "ECG", "pregunta": "Un hombre de 82 años, con antecedentes de miocardiopatía dilatada, acude a urgencias por síncopes recurrentes en la última semana. Se realiza un electrocardiograma que muestra:", "opcion_a": "Bloqueo de rama derecha con hemibloqueo posterior.", "opcion_b": "Bloqueo de rama derecha con hemibloqueo anterior.", "opcion_c": "Bloqueo completo de rama izquierda.", "opcion_d": "Bloqueo de rama derecha.", "correcta": "B", "explicacion": "La respuesta correcta es B) Bloqueo de rama derecha con hemibloqueo anterior: en V1 y V2 el QRS es ancho con una onda R alta y empastada, y en I y V6 aparece una S ancha, que es el patrón del bloqueo de rama derecha. Además, el eje está desviado a la izquierda, con QRS positivo en I y aVL y complejos rS profundos en II, III y aVF, lo que indica un hemibloqueo anterior izquierdo. Es un bloqueo bifascicular, que en un paciente con miocardiopatía y síncopes obliga a descartar un bloqueo auriculoventricular paroxístico. Descartamos A, porque en el hemibloqueo posterior el eje se desvía a la derecha, con QRS negativo en I y positivo en II, III y aVF, al revés de lo que se ve. Descartamos C, porque en el bloqueo de rama izquierda V1 muestra un QRS predominantemente negativo y I y V6 una R ancha y mellada. Descartamos D, porque un bloqueo de rama derecha aislado no explica la desviación del eje a la izquierda.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_1.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 2, "especialidad": "Cardiología", "tema": null, "pregunta": "Hombre de 40 años con hipertensión arterial, en tratamiento con enalapril, amlodipino e hidroclorotiazida a dosis plenas. En consulta tiene cifras de presión arterial por encima de 150/100 mmHg y el resultado de la Monitorización Ambulatoria de la Presión Arterial (MAPA) de 24 horas se muestra en la imagen. La franja sombreada de la derecha indica el periodo de sueño. Asegura cumplir bien el tratamiento, hace ejercicio a diario y come con poca sal. No toma medicamentos que puedan subir la presión arterial. ¿Cuál es la actitud más correcta en este momento?", "opcion_a": "Mantener su tratamiento actual sin cambios y repetir la MAPA en 6 meses.", "opcion_b": "Asociar un antialdosterónico, suspender la hidroclorotiazida y revisar en consulta en 6 meses.", "opcion_c": "Asociar olmesartán y repetir la MAPA en 6 meses.", "opcion_d": "Plantear estudio para descartar causas de hipertensión secundaria y asociar un cuarto fármaco.", "correcta": "D", "explicacion": "La respuesta correcta es D) Plantear estudio para descartar causas de hipertensión secundaria y asociar un cuarto fármaco: el paciente sigue con presión arterial por encima de 150/100 a pesar de estar recibiendo tres fármacos antihipertensivos a dosis máximas, lo que indica hipertensión resistente y justifica la búsqueda de causas secundarias y la intensificación del tratamiento. Descartamos A, porque la presión no está controlada y no se justifica esperar 6 meses sin intervenir. Descartamos B, porque aunque un antialdosterónico podría ser útil, no se debe suspender la hidroclorotiazida ni omitir la evaluación de causas secundarias antes de añadir un cuarto fármaco. Descartamos C, porque añadir otro bloqueador del sistema renina‑angiotensina (olmesartán) cuando ya está el paciente con enalapril no es apropiado y tampoco sustituye la necesidad de investigar una hipertensión secundaria.", "explicacion_calidad": "orientativa", "imagen_path": "/imagenes-mir/2016/imagen_2.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 3, "especialidad": "Cirugía", "tema": "Complicaciones postquirúrgicas", "pregunta": "Mujer de 44 años intervenida de neoplasia de colon mediante laparotomía en línea media sin incidencias remarcables. Al cabo de unas horas de postoperatorio, presenta de forma progresiva mal estado general, intranquilidad y disconfort. En el momento de su exploración tiene buen estado de conciencia, está afebril pero sudorosa, taquicárdica (132 l/min), con hipotensión arterial (82/52 mmHg), frecuencia respiratoria de 24 por min y una saturación arterial de oxígeno del 97%. La auscultación respiratoria es normal y está rítmica. La palpación abdominal es algo dolorosa y los drenajes quirúrgicos tienen débito escaso. Revisa una radiografía de tórax realizada para comprobación de una vía central sin apreciar patología cardiopulmonar relevante. En la analítica urgente objetiva un leve descenso de la hemoglobina respecto al preoperatorio. En este contexto Vd. realiza una ecografía ecoFAST focalizada en hipocondrio derecho (imagen 1) y ventana cardiaca subxifoidea (imagen 2). ¿Cuál es su mejor opción terapéutica?", "opcion_a": "Aviso urgente a cirugía para revaloración de la paciente por probable sangrado intraabdominal como complicación de la intervención quirúrgica.", "opcion_b": "Oxígeno a alto débito, sueroterapia intensiva, iniciar noradrenalina endovenosa y antibioterapia por sospecha de sepsis.", "opcion_c": "Pericardiocentesis ecoguiada y en función del resultado, revisar posteriormente la causa del posible derrame pericárdico.", "opcion_d": "Considerar fibrinolisis dada la alta probabilidad clínica de tromboembolismo pulmonar agudo grave.", "correcta": "C", "explicacion": "La respuesta correcta es C) Pericardiocentesis ecoguiada y en función del resultado, revisar posteriormente la causa del posible derrame pericárdico: la paciente está en shock (hipotensión, taquicardia, sudoración) en el postoperatorio inmediato, con auscultación pulmonar y radiografía de tórax normales. La ventana subxifoidea (imagen 2) muestra un derrame pericárdico que rodea al corazón, y en el hipocondrio derecho (imagen 1) se ven las venas suprahepáticas dilatadas, signo de congestión venosa sistémica, sin líquido libre evidente. Es un taponamiento cardiaco y el tratamiento es la pericardiocentesis ecoguiada. Descartamos A, porque la ecografía no muestra líquido libre intraabdominal y los drenajes apenas tienen débito, así que no hay datos de hemoperitoneo que expliquen el shock. Descartamos B, porque está afebril a las pocas horas de la cirugía y la causa del shock es obstructiva, no séptica; la sueroterapia y los vasopresores no resuelven la compresión cardiaca. Descartamos D, porque la saturación de oxígeno es normal y el hallazgo ecográfico es un derrame pericárdico, por lo que la fibrinolisis no está indicada.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_3.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 4, "especialidad": "Cardiología", "tema": "Valvulopatías", "pregunta": "Mujer de 69 años que acude a consulta externa de cardiología refiriendo disnea limitante de moderados-pequeños esfuerzos instaurada en los últimos meses. El electrocardiograma muestra fibrilación auricular con respuesta ventricular controlada. A la exploración destaca un soplo diastólico. Realizamos un ecocardiograma transtorácico. ¿Cuál cree que es el diagnóstico más probable de esta paciente?", "opcion_a": "Endocarditis bacteriana.", "opcion_b": "Estenosis mitral.", "opcion_c": "Miocardiopatía hipertrófica.", "opcion_d": "Insuficiencia aórtica.", "correcta": "B", "explicacion": "La respuesta correcta es B) Estenosis mitral: la disnea progresiva, la fibrilación auricular y el soplo diastólico orientan a estenosis mitral, y el ecocardiograma lo confirma. En el plano paraesternal se ve una aurícula izquierda muy dilatada con una válvula mitral engrosada, y en el plano apical el Doppler color muestra un flujo turbulento, en mosaico, a través de la válvula mitral, por su orificio estrecho. Descartamos A, porque no hay fiebre ni datos de infección, y la ecografía no muestra vegetaciones. Descartamos C, porque la miocardiopatía hipertrófica produce un soplo sistólico y el ecocardiograma mostraría un ventrículo izquierdo con paredes muy engrosadas. Descartamos D, porque, aunque la insuficiencia aórtica también produce un soplo diastólico, el flujo anómalo del ecocardiograma está en la válvula mitral y no hay regurgitación aórtica.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_4.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 5, "especialidad": "Digestivo", "tema": "Patología esofágica", "pregunta": "Carlos tiene 31 años y es la tercera vez que acude este año a urgencias por presentar episodios de impactación esofágica tras la ingesta de carne que han precisado de su extracción por endoscopia oral. Como antecedentes cabe reseñar que presenta asma bronquial y es alérgico a los frutos secos. Señale la respuesta verdadera en base a los hallazgos esofágicos encontrados en una nueva endoscopia oral:", "opcion_a": "La imagen corresponde a la tráquea, el endoscopista ha entrado a la vía respiratoria.", "opcion_b": "La sospecha diagnóstica debería confirmarse con histología tomando biopsias de esófago distal y proximal.", "opcion_c": "Si el paciente refiere dolor torácico la imagen es diagnóstica de espasmo esofágico difuso.", "opcion_d": "La imagen corresponde a una acalasia.", "correcta": "B", "explicacion": "La respuesta correcta es B) La sospecha diagnóstica debería confirmarse con histología tomando biopsias de esófago distal y proximal: un adulto joven con asma, alergia alimentaria e impactaciones esofágicas de repetición tiene como primera sospecha una esofagitis eosinofílica. En la imagen el esófago muestra anillos concéntricos (aspecto traqueal o traquealización), hallazgo endoscópico típico de esta enfermedad. El diagnóstico exige confirmar la infiltración eosinofílica del epitelio en biopsias de esófago proximal y distal, ya que la afectación es parcheada. Descartamos A, porque la imagen es la luz esofágica con anillos que recuerdan a la tráquea, no la vía aérea. Descartamos C, porque el espasmo esofágico difuso se diagnostica con manometría y no tiene una imagen endoscópica característica. Descartamos D, porque en la acalasia se ve un esófago dilatado con restos alimentarios y un cardias cerrado, no anillos concéntricos.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_5.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 6, "especialidad": "Digestivo", "tema": "Patología biliopancreática", "pregunta": "Mujer de 84 años con antecedente de colecistectomía que presenta dolor abdominal e ictericia. Se realizó una colangiopancreatografía retrógrada endoscópica (CPRE). ¿Cúal es el diagnóstico correcto?", "opcion_a": "Síndrome de Mirizzi.", "opcion_b": "Neoplasia de páncreas.", "opcion_c": "Coledocolitiasis.", "opcion_d": "Estenosis postquirúrgica del colédoco.", "correcta": "C", "explicacion": "La respuesta correcta es C) Coledocolitiasis: la CPRE muestra una vía biliar dilatada con un defecto de repleción redondeado en el colédoco, que corresponde a un cálculo. En una paciente colecistectomizada con dolor abdominal e ictericia, es una coledocolitiasis residual o de novo. Descartamos A, porque el síndrome de Mirizzi es la compresión de la vía biliar por un cálculo impactado en el cístico o en el cuello de la vesícula, y la paciente no tiene vesícula. Descartamos B, porque una neoplasia de páncreas produciría una estenosis de bordes irregulares en el colédoco distal, no un defecto de repleción redondeado. Descartamos D, porque la estenosis postquirúrgica se vería como un estrechamiento del conducto y no como un defecto de repleción en su interior.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_6.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 7, "especialidad": "Digestivo", "tema": "Patología biliopancreática", "pregunta": "Mujer de 42 años que acude a urgencias por dolor abdominal y fiebre. Se realiza una TC que no aporta datos sobre la posible causa del dolor, no obstante ante los hallazgos objetivados en la imagen se remite a consulta. ¿Cuál de las siguientes exploraciones considera indicada para completar el estudio?", "opcion_a": "Gammagrafía con meta-iodobencilguanidina.", "opcion_b": "Determinación de 5 hidroxiindolacético en orina de 24h.", "opcion_c": "Punción aspiración con aguja fina con control ecográfico.", "opcion_d": "Resonancia magnética.", "correcta": "D", "explicacion": "La respuesta correcta es D) Resonancia magnética: la TC se hizo por otro motivo y no explica el dolor, pero ha mostrado de forma incidental una lesión que obliga a completar el estudio. El paso siguiente es caracterizarla con una técnica de imagen no invasiva y sin radiación, y la resonancia magnética permite definir su composición y su naturaleza mejor que la TC. Descartamos A, porque la gammagrafía con metaiodobencilguanidina solo está indicada cuando el estudio hormonal sugiere un feocromocitoma o un paraganglioma. Descartamos B, porque el ácido 5-hidroxiindolacético en orina se usa ante la sospecha clínica de un tumor carcinoide con síndrome carcinoide, que la paciente no tiene. Descartamos C, porque la punción no es el primer paso para estudiar una lesión hallada por casualidad, y, si fuera suprarrenal, no debe puncionarse sin haber descartado antes un feocromocitoma.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_7.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 8, "especialidad": "Endocrinología", "tema": "Patología tiroidea", "pregunta": "Mujer de 47 años que refiere desde hace dos semanas un cuadro de febrícula, astenia, palpitaciones y dolor cervical con la deglución con sensación de aumento de partes blandas. En la analítica destaca una VSG de 87 mm/h y una TSH sérica de 0,01 UI/L. Se indica realización de una gammagrafía tiroidea. ¿Cuál de las siguientes imágenes es compatible con el diagnóstico de la paciente?", "opcion_a": "1.", "opcion_b": "2.", "opcion_c": "3.", "opcion_d": "4.", "correcta": "A", "explicacion": "La respuesta correcta es A) 1: el cuadro de dolor cervical que aumenta con la deglución, febrícula, palpitaciones, VSG muy elevada y TSH suprimida tras un proceso reciente corresponde a una tiroiditis subaguda granulomatosa (de De Quervain). La destrucción folicular libera hormona preformada y el tiroides inflamado no capta el trazador, por lo que la gammagrafía muestra una captación ausente o casi nula, que es lo que se ve en la imagen 1: no se identifica la glándula y solo se aprecian las glándulas salivales y la actividad de fondo. Descartamos B, porque la imagen 2 muestra un único nódulo hipercaptante con supresión del resto de la glándula, propio de un adenoma tóxico. Descartamos C, porque la imagen 3 muestra una captación heterogénea y parcheada, propia de un bocio multinodular. Descartamos D, porque la imagen 4 muestra una captación difusa y aumentada de ambos lóbulos, propia de la enfermedad de Graves.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_8.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 9, "especialidad": "Ginecología", "tema": "Patología obstétrica y complicaciones del embarazo — sangrado en gestante, prematuridad, crecimiento fetal", "pregunta": "Mujer de 28 años de edad que ha estado en tratamiento por un síndrome de ovario poliquístico, acude a la consulta para el control del embarazo refiriendo una amenorrea de 10 semanas. En la ecografía se objetiva un feto único, vivo, con una longitud cefalo-caudal (CRL) de 57 mm, que corresponde a 12 semanas. Señale la opción correcta:", "opcion_a": "Debemos asumir que la edad gestacional real son 12 semanas, reasignar una nueva FUR (Fecha de última regla) o FPP (Fecha probable de parto) y planificar el resto de los controles del embarazo en base a esta edad gestacional.", "opcion_b": "Seguiremos considerando que la edad gestacional real son 10 semanas, ya que coincide con la FUR de la paciente. Planificaremos el resto de los controles en función de esta edad gestacional, aunque dejaremos constancia de esta discordancia en la historia clínica.", "opcion_c": "Ante esta discordancia, solicitaremos una analítica de sangre para cuantificar la hormona 8-HCG y decidir en función de sus niveles cuál es la edad gestacional real para poder planificar el resto de los controles del embarazo.", "opcion_d": "Solicitaremos un nuevo control ecográfico en 2 semanas para ver la evolución y diagnosticar con más certeza la edad gestacional correcta.", "correcta": "A", "explicacion": "La respuesta correcta es A) Debemos asumir que la edad gestacional real son 12 semanas, reasignar una nueva FUR (Fecha de última regla) o FPP (Fecha probable de parto) y planificar el resto de los controles del embarazo en base a esta edad gestacional: la medida ecográfica de la longitud cefalo‑caudal es el método más preciso para determinar la edad gestacional en el primer trimestre y supera la información basada en la fecha de la última regla, por lo que se ajusta la FUR y la FPP a 12 semanas. Descartamos B, porque no se debe mantener la edad gestacional basada únicamente en la FUR cuando la ecografía muestra una discrepancia clara. Descartamos C, porque la cuantificación de β‑hCG no es el método de referencia para precisar la edad gestacional frente a una ecografía en este momento. Descartamos D, porque esperar dos semanas para repetir la ecografía retrasaría la correcta planificación del seguimiento obstétrico.", "explicacion_calidad": "orientativa", "imagen_path": "/imagenes-mir/2016/imagen_9.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 10, "especialidad": "Hematología", "tema": "Hemoglobinopatías y anemias hemolíticas", "pregunta": "Una mujer de 40 años acude al servicio de urgencias por síndrome anémico. En la exploración física se observa palidez mucocutánea con tinte ictérico en conjuntivas. En los análisis de sangre periférica destacan los siguientes datos: leucocitos 7.380/µL, hemoglobina 7,6 g/dL, VCM 97 fl, plaquetas 78.000/µL, LDH 1.092 U/L, bilirrubina total 3,4 mg/dL y bilirrubina indirecta 2,9 mg/dL. Ante los hallazgos del frotis de sangre periférica, indique el diagnóstico de sospecha correcto:", "opcion_a": "Anemia hemolítica autoinmune.", "opcion_b": "Mielofibrosis.", "opcion_c": "Anemia hemolítica microangiopática.", "opcion_d": "Anemia drepanocítica.", "correcta": "C", "explicacion": "La respuesta correcta es C) Anemia hemolítica microangiopática: el frotis muestra abundantes esquistocitos, hematíes fragmentados en forma de casco o triangulares, que indican una rotura mecánica de los hematíes en la microcirculación. Junto con la anemia, la elevación de LDH y de bilirrubina indirecta (hemólisis) y la trombocitopenia, el cuadro es una anemia hemolítica microangiopática, como la que se ve en la púrpura trombótica trombocitopénica. Descartamos A, porque en la anemia hemolítica autoinmune el hallazgo típico del frotis son los esferocitos y no los esquistocitos. Descartamos B, porque en la mielofibrosis se ven dacriocitos (hematíes en lágrima) y un cuadro leucoeritroblástico, no esquistocitos con hemólisis intensa. Descartamos D, porque en la anemia drepanocítica el frotis muestra hematíes falciformes, que no aparecen en la imagen.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_10.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 11, "especialidad": "Hematología", "tema": "Síndromes linfoproliferativos y leucemias", "pregunta": "Hombre de 68 años que consulta por astenia. Refiere dolores óseos como única sintomatología acompañante. Su función renal era normal 6 meses antes. Se realiza analítica general que muestra: creatinina 2,0 mg/dL, urea 86 mg/dL, proteínas plasmáticas 90 g/L, VSG 120 mm/h, ratio albúmina/creatinina urinaria 4 (normal), ratio proteína/creatinina urinaria 80 (N<22). Se adjunta la imagen del sedimento de orina y de la tira reactiva de orina. ¿Qué sospecha que pueda tener el paciente y qué prueba haría en primer lugar?", "opcion_a": "Una amiloidosis y haría un biopsia de grasa subcutánea.", "opcion_b": "Un mieloma múltiple y pediría un proteinograma y proteína de Bence Jones en orina.", "opcion_c": "Una enfermedad glomerular y solicitaría una biopsia renal urgente.", "opcion_d": "Una necrosis tubular aguda y solicitaría una ecografía renal.", "correcta": "B", "explicacion": "La respuesta correcta es B) Un mieloma múltiple y pediría un proteinograma y proteína de Bence Jones en orina: un varón mayor con dolores óseos, VSG muy elevada, hiperproteinemia y deterioro renal reciente orienta a mieloma múltiple. El dato clave es la discordancia en la orina: el cociente proteína/creatinina está muy elevado, mientras que el cociente albúmina/creatinina es normal y la tira reactiva, que detecta sobre todo albúmina, apenas marca proteínas. Por tanto, la proteína que se pierde no es albúmina, sino cadenas ligeras (proteinuria de Bence Jones). En el sedimento se ve un cilindro ancho, compatible con el riñón de mieloma por cilindros de cadenas ligeras. La primera prueba es el proteinograma con la proteína de Bence Jones en orina. Descartamos A, porque la amiloidosis renal produce sobre todo proteinuria de albúmina, en rango nefrótico, y aquí la albuminuria es normal. Descartamos C, porque una enfermedad glomerular elevaría el cociente albúmina/creatinina. Descartamos D, porque la necrosis tubular aguda no explica los dolores óseos, la hiperproteinemia ni la VSG tan elevada.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_11.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 12, "especialidad": "Neurología", "tema": "Neuro-oncología", "pregunta": "Mujer de 70 años con antecedentes de hipertensión arterial, neumopatía obstructiva crónica y miocardiopatía hipertrófica septal. Ingresa en la UCI por un shock séptico de origen respiratorio. Tras estabilización mediante soporte vasoactivo y 14 días de antibioterapia sigue una buena evolución clínica y analítica. Bruscamente pre-senta una crisis convulsiva generalizada que obliga a intubación orotraqueal por disminución del nivel de conciencia. Una TC urgente con contraste muestra una lesión cavitada parietal izquierda. Se realiza RM. ¿Cuál es el diagnóstico de presunción?", "opcion_a": "Absceso cerebral.", "opcion_b": "Tumor primario del sistema nervioso central.", "opcion_c": "Metástasis de tumor sólido.", "opcion_d": "Toxoplasmosis cerebral.", "correcta": "A", "explicacion": "La respuesta correcta es A) Absceso cerebral: la aparición de una lesión cavitada en la TC con contraste en una paciente que ha sufrido un shock séptico y está bajo tratamiento antibiótico sugiere una colección purulenta intracraneal, típica de un absceso; la evolución clínica con crisis convulsiva respalda la irritación focal provocada por dicha lesión. Descartamos B, porque un tumor primario suele presentarse como masa sólida con realce y no como cavidad en este contexto infeccioso. Descartamos C, porque no hay antecedente de neoplasia sólida y la cavitación es más característica de procesos infecciosos. Descartamos D, porque la toxoplasmosis cerebral se asocia a inmunosupresión profunda, ausente en la historia.", "explicacion_calidad": "orientativa", "imagen_path": "/imagenes-mir/2016/imagen_12.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 13, "especialidad": "Cardiología", "tema": "Valvulopatías", "pregunta": "¿Cuál es el diagnóstico de sospecha de la siguiente imagen ecocardiográfica?", "opcion_a": "Disección aórtica.", "opcion_b": "Estenosis aórtica.", "opcion_c": "Endocarditis aórtica.", "opcion_d": "Mixoma valvular aórtico.", "correcta": "C", "explicacion": "La respuesta correcta es C) Endocarditis aórtica: el ecocardiograma muestra una masa ecogénica e irregular adherida a la válvula aórtica, que se mueve con ella, compatible con una vegetación, que es la lesión característica de la endocarditis infecciosa. Descartamos A, porque la disección aórtica se reconoce por un colgajo intimal en la luz de la aorta que separa una luz verdadera y una falsa, no por una masa sobre la válvula. Descartamos B, porque en la estenosis aórtica la válvula está engrosada y calcificada, con apertura reducida, pero sin una masa móvil adherida. Descartamos D, porque los mixomas asientan casi siempre en la aurícula izquierda, unidos al tabique interauricular, y son excepcionales en la válvula aórtica.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_13.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 14, "especialidad": "Nefrología", "tema": "Trastornos hidroelectrolíticos", "pregunta": "Hombre de 83 años que acude a urgencias por astenia, malestar general y diarrea. Antecedentes de HTA, diabético con enfermedad renal crónica (EFG 32 mL/min) e insuficiencia cardiaca (FE 30%). En tratamiento con digoxina, nebivolol, furosemida, alopurinol, espironolactona, enalapril, atorvastatina y sitagliptina. En la exploración destacan signos de deshidratación de mucosas. PA 90/44 mm/Hg, FC 67 lpm. Análisis: Hb 10,8 g/dL, glucosa 156 mg/dL, urea 125 mg/dL, creatinina 3,25 mg/dL, K 7,5 mEq/L, Na 138 mEq/L, pH 7,31, bicarbonato 16 mmol/L. Se realiza el siguiente ECG. ¿Cuál es la primera medida a instaurar en este paciente?", "opcion_a": "Administrar gluconato cálcico al 10% iv.", "opcion_b": "Corregir la acidosis metabólica con bicarbonato iv.", "opcion_c": "Retirada de fármacos y añadir resinas de intercambio iónico.", "opcion_d": "Hemodiálisis.", "correcta": "A", "explicacion": "La respuesta correcta es A) Administrar gluconato cálcico al 10% iv: el paciente presenta hiperpotasemia grave (K 7,5 mEq/L) y alteraciones en el ECG que indican riesgo de arritmias, por lo que la estabilización de la membrana cardiaca con calcio es la medida inmediata. Además, la corrección de la causa subyacente puede seguir después de asegurar la seguridad eléctrica. Descartamos B, porque la corrección de la acidosis con bicarbonato no es la prioridad inmediata frente al riesgo arrítmico de la hiperpotasemia. Descartamos C, porque retirar fármacos y usar resinas no actúa con la rapidez necesaria para prevenir arritmias. Descartamos D, porque la hemodiálisis es una medida definitiva pero no la primera intervención cuando se dispone de una terapia rápida como el calcio intravenoso.", "explicacion_calidad": "orientativa", "imagen_path": "/imagenes-mir/2016/imagen_14.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 15, "especialidad": "Nefrología", "tema": null, "pregunta": "Hombre de 71 años que consulta por febrícula y astenia de 3 semanas de evolución, que no ha cedido a pesar de tratamiento antibiótico durante 7 días. En la tira de orina se aprecia microhematuria. Aporta un hemograma con Hb de 10,1 g/dL, VCM de 91,6 fL. Primeramente le realizan una ecografía abdominal, pero al radiólogo le plantea dudas y decide realizarle una TC. Señale la respuesta que le parece correcta:", "opcion_a": "La imagen es compatible con tuberculosis renal.", "opcion_b": "Debería haberse esperado 3 semanas más con tratamiento antibiótico antes de hacer una prueba de imagen.", "opcion_c": "Hay una lesión excrecente renal que sugiere un hipernefroma.", "opcion_d": "Existe indicación de colocación de un catéter doble J izquierdo.", "correcta": "C", "explicacion": "La respuesta correcta es C) Hay una lesión excrecente renal que sugiere un hipernefroma: la TC muestra una masa sólida en el riñón derecho, que deforma y sobrepasa su contorno. En un varón mayor con fiebre prolongada que no cede con antibióticos, anemia y microhematuria, una masa renal sólida es, mientras no se demuestre lo contrario, un carcinoma de células renales o hipernefroma, que puede debutar con fiebre como síndrome paraneoplásico. Descartamos A, porque la tuberculosis renal produce calcificaciones, deformidad y estenosis de los cálices con un riñón destruido, no una masa sólida que hace relieve. Descartamos B, porque la fiebre persistente pese a los antibióticos, con anemia y hematuria, justifica hacer ya la prueba de imagen. Descartamos D, porque el riñón izquierdo no muestra dilatación de la vía urinaria, por lo que no hay indicación de un catéter doble J.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_15.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 16, "especialidad": "Respiratorio", "tema": "Infecciones respiratorias", "pregunta": "Mujer de 45 años de edad, fumadora de 20 cig/día. Acude a urgencias por cuadro clínico de 10 días de evolución de tos mucopurulenta, dolor en hemitórax derecho, astenia y sudoración nocturna. Auscultación pulmonar con murmullo vesicular disminuido a nivel del tercio superior del pulmón derecho con roncus abundantes por ambos campos. Analítica: Hb 10 g/dL, plaquetas 629.000/µL y leucocitos 16.000/µL con 83% neutrófilos. Se realiza una RX tórax. ¿Cuál es la actitud más correcta?", "opcion_a": "Punción transtorácica aspirativa guiada por TC.", "opcion_b": "Broncoscopia con lavado broncoalveolar.", "opcion_c": "Antibioterapia empírica con cobertura para anaerobios.", "opcion_d": "Drenaje percutáneo.", "correcta": "C", "explicacion": "La respuesta correcta es C) Antibioterapia empírica con cobertura para anaerobios: la clínica de tos mucopurulenta, dolor torácico, astenia, sudoración nocturna, leucocitosis con neutrofilia y la sospecha de neumonía con posible absceso pulmonar indican iniciar tratamiento antibiótico que cubra los anaerobios, los principales causantes de este tipo de infección; la terapia empírica es la medida inicial antes de considerar procedimientos invasivos. Además, los procedimientos invasivos como punción o drenaje se reservan para casos de fracaso del tratamiento o cuando la colección es accesible y de gran tamaño. Descartamos A, porque la punción transtorácica se reserva para drenaje de abscesos ya confirmados y de gran tamaño cuando la terapia médica falla. Descartamos B, porque la broncoscopia con lavado broncoalveolar no es necesaria como primera medida en una neumonía sospechada sin evidencia de obstrucción o patología neoplásica. Descartamos D, porque el drenaje percutáneo se indica solo cuando el absceso es grande, está maduro o la evolución clínica es desfavorable tras el tratamiento antibiótico.", "explicacion_calidad": "orientativa", "imagen_path": "/imagenes-mir/2016/imagen_16.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 17, "especialidad": "Respiratorio", "tema": null, "pregunta": "Joven de 22 años sin antecedentes de interés que acude a urgencias por dolor torácico y abdominal inespecífico. Presión arterial de 90/50 mmHg, frecuencia cardiaca 120 latidos por minuto y saturación basal 94%. Auscultación respiratoria con hipofonesis generalizada bilateral. ¿Cuál es el diagnóstico y tratamiento inicial según la imagen?", "opcion_a": "Atelectasia. Fisioterapia respiratoria.", "opcion_b": "Neumotórax. Drenaje torácico.", "opcion_c": "Atelectasia. Broncoscopia.", "opcion_d": "Neumotórax. Videotoracoscopia.", "correcta": "B", "explicacion": "La respuesta correcta es B) Neumotórax. Drenaje torácico: la radiografía muestra un hemitórax derecho hiperclaro, sin trama pulmonar, con el pulmón colapsado y el mediastino desplazado hacia el lado contrario. Es un neumotórax extenso que, con hipotensión y taquicardia, se comporta como un neumotórax a tensión, y el tratamiento inicial es la descompresión y la colocación de un drenaje torácico. Descartamos A, porque la atelectasia se ve como una opacidad con pérdida de volumen que desplaza el mediastino hacia el mismo lado, al contrario de lo que muestra la imagen, y la fisioterapia no trata un neumotórax. Descartamos C, porque no hay atelectasia y la broncoscopia no tiene papel en el neumotórax. Descartamos D, porque la videotoracoscopia se reserva para el tratamiento definitivo, ante recidivas o fuga aérea persistente, y no es la medida inicial en un paciente inestable.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_17.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 18, "especialidad": "Respiratorio", "tema": null, "pregunta": "Mujer de 74 años con HTA, nefrectomía izquierda por tuberculosis renal en 2004 y trastorno de depresión mayor con mutismo tratado con terapia electroconvulsiva. Última sesión hace dos semanas. Es traída a la urgencia por síncope. En la exploración PA 142/90 mmHg, FC 105 lpm, saturación de oxígeno 89%, taquipnea a 30 rpm con tiraje. ECG sin signos de isquemia aguda. Rx tórax con aumento de diámetro de la arteria pulmonar. Analítica con urea 89 mg/dL, creatinina 2,1 mg/dL, BNP 945 pg/mL, troponina 34 ng/mL (normal <0,5), dímero-D 3.200 ng/dL. Se realiza la siguiente prueba. Ante los hallazgos, ¿cuál es la actuación más correcta?", "opcion_a": "Confirmar el diagnóstico con una angioTC tórax.", "opcion_b": "Anticoagular con heparina y monitorización estrecha de constantes vitales.", "opcion_c": "Administrar diuréticos de asa endovenosos, nitritos y antiagregantes.", "opcion_d": "Administrar fibrinolíticos ante la gravedad del cuadro.", "correcta": "B", "explicacion": "La respuesta correcta es B) Anticoagular con heparina y monitorización estrecha de constantes vitales: síncope, hipoxemia, taquipnea, arteria pulmonar dilatada, dímero-D elevado y elevación de BNP y troponina orientan a una tromboembolia pulmonar con repercusión sobre el ventrículo derecho. Como la paciente tiene una insuficiencia renal, se hizo una gammagrafía pulmonar de perfusión (SPECT-TC) en lugar de una angioTC, y muestra varios defectos de perfusión segmentarios en ambos pulmones, lo que confirma el diagnóstico. Está hemodinámicamente estable (PA 142/90 mmHg), así que se trata de una tromboembolia de riesgo intermedio-alto: se anticoagula con heparina y se vigila estrechamente por si se deteriora. Descartamos A, porque la gammagrafía ya confirma el diagnóstico y la angioTC añadiría contraste en una paciente con la función renal alterada. Descartamos C, porque diuréticos, nitratos y antiagregantes son el tratamiento de la insuficiencia cardiaca o del síndrome coronario, no de la tromboembolia pulmonar. Descartamos D, porque la fibrinolisis sistémica se reserva para la tromboembolia de alto riesgo, con hipotensión o shock, que la paciente no tiene.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_18.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 19, "especialidad": "Neurología", "tema": "Enfermedad cerebrovascular", "pregunta": "Hombre de 77 años de edad encontrado en su domicilio con hemiplejia derecha y afasia global. Última vez visto asintomático 20 horas antes. Se realiza TC craneal que se muestra. Señale la respuesta CORRECTA:", "opcion_a": "La imagen no permite determinar el tiempo de isquemia; podrían haber transcurrido sólo unos minutos desde la aparición del déficit.", "opcion_b": "No cumple criterios para la administración de tratamiento fibrinolítico.", "opcion_c": "El ingreso en una unidad de ictus no está indicado en este paciente.", "opcion_d": "Ante el tamaño del infarto se debe plantear una craniectomía descompresiva, antes de que aparezca edema cerebral.", "correcta": "B", "explicacion": "La respuesta correcta es B) No cumple criterios para la administración de tratamiento fibrinolítico: el paciente fue visto asintomático hace 20 horas, por lo que supera el límite temporal para la trombólisis y la TC probablemente muestra un infarto ya establecido. Descartamos A, porque el tiempo transcurrido desde el inicio del déficit es de al menos 20 horas, lo que excluye que haya sido de minutos. Descartamos C, porque la admisión en una unidad de ictus está indicada en cualquier paciente con accidente cerebrovascular agudo para manejo especializado. Descartamos D, porque la craniectomía descompresiva solo se plantea cuando hay edema cerebral masivo y no simplemente por el tamaño del infarto en esta fase temprana.", "explicacion_calidad": "orientativa", "imagen_path": "/imagenes-mir/2016/imagen_19.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 20, "especialidad": "Dermatología", "tema": "Oncología cutánea", "pregunta": "Niño de 3 años cuyos padres refieren que presenta lesión en cara interna de antebrazo derecho, detectada a los tres meses del nacimiento que en ocasiones se enrojece y le produce picor. ¿Cuál es el diagnóstico más probable y qué actitud llevaría a cabo?", "opcion_a": "Mastocitoma, observación ya que probablemente involucione.", "opcion_b": "Nevus sebáceo, extirpación.", "opcion_c": "Angiofibroma, exploración de superficie corporal completa y estudio genético.", "opcion_d": "Nevus melanocítico congénito, seguimiento y control fotográfico.", "correcta": "A", "explicacion": "La respuesta correcta es A) Mastocitoma, observación ya que probablemente involucione: una lesión única, aparecida en los primeros meses de vida, que se enrojece y pica de forma intermitente (al rozarla se libera histamina, el signo de Darier) es típica de un mastocitoma cutáneo solitario. Es benigno y tiende a involucionar en la infancia, por lo que basta con observarlo. Descartamos B, porque el nevus sebáceo es una placa amarillenta y verrugosa, habitualmente en el cuero cabelludo, que no se enrojece ni pica. Descartamos C, porque los angiofibromas son pápulas faciales múltiples asociadas a la esclerosis tuberosa, no una lesión única en el antebrazo. Descartamos D, porque el nevus melanocítico congénito es una lesión pigmentada presente desde el nacimiento, que no se enrojece ni pica.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_20.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 21, "especialidad": "Respiratorio", "tema": "Enfermedad pulmonar intersticial y ocupacional", "pregunta": "Una empleada bancaria de 38 años a la que se ha hecho la revisión periódica de empresa nos es remitida para valorar la radiografía de tórax. La paciente fuma 20 cigarrillos/día desde los 21 años. Refiere que durante los últimos meses, está algo más cansada de lo habitual. Los análisis básicos de laboratorio son normales a excepción de una Hb de 11,4 g/dL. Un electrocardiograma y una espirometría forzada son normales. ¿Cuál cree que es la orientación diagnóstica más plausible?", "opcion_a": "Enfermedad de Hodgkin.", "opcion_b": "Infección fúngica tipo histoplasmosis.", "opcion_c": "Sarcoidosis.", "opcion_d": "Carcinoma broncogénico.", "correcta": "C", "explicacion": "La respuesta correcta es C) Sarcoidosis: la radiografía muestra unos hilios pulmonares aumentados de tamaño y lobulados en ambos lados, compatibles con adenopatías hiliares bilaterales y simétricas, sin lesiones en el parénquima. En una mujer joven, con pocos síntomas y una espirometría normal, este patrón es típico de la sarcoidosis en estadio I. Descartamos A, porque en la enfermedad de Hodgkin las adenopatías suelen ser mediastínicas anteriores y asimétricas, y rara vez hiliares bilaterales aisladas. Descartamos B, porque la histoplasmosis requiere haber estado en una zona endémica, y la paciente no tiene ese antecedente. Descartamos D, porque el carcinoma broncogénico suele dar una masa o una adenopatía hiliar unilateral, no adenopatías hiliares bilaterales y simétricas.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_21.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 22, "especialidad": "Traumatología", "tema": null, "pregunta": "Mujer de 68 años en tratamiento crónico por polimialgia reumática. Acude a la consulta por dolor inguinal derecho irradiado a la cara anteromedial del tercio proximal del muslo, de inicio insidioso y sin traumatismo causal. Se trata de un dolor continuo pero que va en aumento. Empeora con la bipedestación. Se hace RX simple en la que se observan leves cambios degenerativos simétricos en ambas caderas, sin pérdida de la interlínea articular en la cadera dolorosa. Se realiza una RM. ¿Qué diagnóstico considera más probable?", "opcion_a": "Osteomielitis aguda.", "opcion_b": "Artrosis de cadera.", "opcion_c": "Necrosis avascular de la cabeza femoral.", "opcion_d": "Osteosarcoma.", "correcta": "C", "explicacion": "La respuesta correcta es C) Necrosis avascular de la cabeza femoral: la paciente lleva tratamiento crónico con corticoides por la polimialgia reumática, que es un factor de riesgo de osteonecrosis, y presenta un dolor inguinal progresivo, sin traumatismo, que empeora con la carga. La radiografía es normal en las fases iniciales y la resonancia magnética, la prueba más sensible, muestra la alteración de la señal de la cabeza femoral propia de la necrosis. Descartamos A, porque no hay fiebre ni datos de infección que hagan pensar en una osteomielitis aguda. Descartamos B, porque la artrosis de cadera produciría un pinzamiento de la interlínea articular en la radiografía, que aquí está conservada. Descartamos D, porque el osteosarcoma es muy raro a esta edad y daría una lesión ósea agresiva visible.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_22.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 23, "especialidad": "Traumatología", "tema": "Fracturas y traumatismos agudos", "pregunta": "¿Cuál es la respuesta correcta ante un joven con un antecedente traumático hace 3 días al que se le practica esta radiografía de rodilla?", "opcion_a": "Rótula bipartita.", "opcion_b": "Fractura de rótula.", "opcion_c": "Osteocondritis disecante.", "opcion_d": "Núcleo de osificación secundario no fusionado.", "correcta": "B", "explicacion": "La respuesta correcta es B) Fractura de rótula: el antecedente traumático reciente y la presencia de una lesión ósea visible en la radiografía son compatibles con una fractura aguda de la rótula. Descartamos A, porque la rótula bipartita es una variante anatómica congénita que no se asocia a un trauma reciente. Descartamos C, porque la osteocondritis disecante se manifiesta de forma crónica y no como una lesión aguda tras un golpe. Descartamos D, porque un núcleo de osificación secundario no fusionado es una estructura normal en la edad juvenil y no representa una fractura.", "explicacion_calidad": "orientativa", "imagen_path": "/imagenes-mir/2016/imagen_23.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 24, "especialidad": "Urgencias", "tema": "Urgencias en el paciente crítico/UCI", "pregunta": "Hombre de 75 años que acude a urgencias por dolor abdominal y fiebre de 24h de evolución. A la exploración física encontramos un paciente febril, obnubilado, inestable hemodinámicamente y con vientre en tabla. Se solicita TC abdominal que revela neumoperitoneo y contenido abundante en cavidad peritoneal. Se decide traslado urgente a quirófano. Iniciamos resucitación con fluidos y ante la necesidad de infusión de vasoactivos, el residente procede a canalización de catéter venoso central. Al observar el color de la sangre muestra dudas y solicita realización de gasometría. Resultados: pH 7,30; pO2 95 mmHg; pCO2 44 mmHg; HCO3 18 mmol/L; SO2 95%. Señale la respuesta FALSA:", "opcion_a": "La imagen mostrada se ha obtenido a través de ultrasonidos.", "opcion_b": "Una de las posibles complicaciones de esta técnica es la punción de la arteria carótida común.", "opcion_c": "Si nos atenemos a los valores gasométricos, la técnica ha sido exitosa.", "opcion_d": "Con esta técnica se ha demostrado disminuir la tasa de complicaciones.", "correcta": "C", "explicacion": "La respuesta correcta es C) Si nos atenemos a los valores gasométricos, la técnica ha sido exitosa: la gasometría de la muestra tiene una pO2 de 95 mmHg y una saturación del 95%, valores de sangre arterial y no venosa, en la que la pO2 rondaría los 40 mmHg y la saturación el 70-75%. El catéter se ha colocado en una arteria, probablemente la carótida, así que la técnica no ha sido exitosa y la afirmación es falsa. Descartamos A, porque la imagen es una ecografía de los vasos del cuello, la técnica con la que se guía la canalización venosa central. Descartamos B, porque la punción de la arteria carótida común es una complicación conocida de la canalización de la vena yugular interna, ya que discurren juntas. Descartamos D, porque es cierto que la canalización guiada por ecografía ha demostrado reducir los intentos fallidos y las complicaciones.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_24.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 25, "especialidad": "Bioestadística", "tema": "Ensayos clínicos y fases de investigación", "pregunta": "De acuerdo a los resultados del ensayo clínico incluidos en la imagen vinculada a la pregunta, ¿cuál de las siguientes conclusiones es cierta?", "opcion_a": "Mirgliptin reduce significativamente la tasa anual de eventos cardiovasculares en comparación con metformina, con una hazard ratio por debajo de 1 y una p significativa de 0,01.", "opcion_b": "El estudio no es concluyente, porque el límite inferior del intervalo de confianza al 95% del hazard ratio no puede descartar que la diferencia a favor de mirgliptin sea menor del 30% en términos relativos.", "opcion_c": "Se demuestra la no inferioridad de mirgliptin porque el valor de p de superioridad no es significativo.", "opcion_d": "Mirgliptin es no inferior a metformina de acuerdo a las condiciones prefijadas en el protocolo del estudio.", "correcta": "D", "explicacion": "La respuesta correcta es D) Mirgliptin es no inferior a metformina de acuerdo a las condiciones prefijadas en el protocolo del estudio: el límite de no inferioridad se fijó en un hazard ratio de 1,30, y el intervalo de confianza del 95% del hazard ratio obtenido (0,97, con un intervalo de 0,69 a 1,26) queda por debajo de ese límite, con una p de no inferioridad de 0,01. Por tanto, se demuestra la no inferioridad según lo prefijado. Descartamos A, porque la superioridad no es significativa (p de superioridad 0,68 y un intervalo de confianza que incluye el 1); la p de 0,01 corresponde al análisis de no inferioridad. Descartamos B, porque el objetivo principal era la no inferioridad, que queda demostrada; que no se pueda confirmar ni descartar un beneficio mayor no hace que el estudio deje de ser concluyente para su objetivo. Descartamos C, porque la no inferioridad no se demuestra con una p de superioridad no significativa, sino comprobando que el límite superior del intervalo de confianza no supera el margen prefijado.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_25.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 26, "especialidad": "Dermatología", "tema": "Dermatosis eritemato-descamativas", "pregunta": "Hombre de 26 años que presenta desde hace 7 años brotes de placas eritemato-escamosas en el cuero cabelludo, codos, región sacra, periumbilical y rodillas. Ha seguido diferentes tratamientos (acitretino, metotrexate, ciclosporina, fototerapia) que han sido tan solo parcialmente eficaces o le han causado efectos adversos. ¿Cuál de los siguientes fármacos tiene indicación aprobada para nuestro paciente?", "opcion_a": "Abatacept.", "opcion_b": "Ustekinumab.", "opcion_c": "Leflunomida.", "opcion_d": "Tocilizumab.", "correcta": "B", "explicacion": "La respuesta correcta es B) Ustekinumab: es un anticuerpo monoclonal que bloquea interleucinas clave en la psoriasis y está aprobado para formas extensas y refractarias a terapias convencionales, como en este paciente con brotes crónicos y resistentes. Descartamos A, porque abatacept modula la coestimulación de linfocitos T y su indicación está limitada a artritis reumatoide, no a psoriasis. Descartamos C, porque la leflunomida se emplea principalmente en artritis reumatoide y no cuenta con autorización para psoriasis. Descartamos D, porque el tocilizumab inhibe una interleucina proinflamatoria y su uso está aprobado en artritis reumatoide, sin indicación en psoriasis.", "explicacion_calidad": "orientativa", "imagen_path": "/imagenes-mir/2016/imagen_26.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 27, "especialidad": "Dermatología", "tema": "Oncología cutánea", "pregunta": "Hombre de 54 años diagnosticado de melanoma diseminado en tratamiento con vemurafenib. Seis semanas después de iniciar el tratamiento refiere la aparición de una lesión cutánea de rápido crecimiento (ver imagen). ¿Cuál es el diagnóstico más probable?", "opcion_a": "Botón de Oriente.", "opcion_b": "Metástasis en tránsito de melanoma.", "opcion_c": "Queratoacantoma.", "opcion_d": "Carcinoma basocelular.", "correcta": "C", "explicacion": "La respuesta correcta es C) Queratoacantoma: los inhibidores de BRAF como el vemurafenib producen con frecuencia, en las primeras semanas de tratamiento, queratoacantomas y carcinomas epidermoides cutáneos, por activación paradójica de la vía MAPK en los queratinocitos. La imagen muestra un nódulo cupuliforme de crecimiento rápido con un cráter central queratósico, la morfología típica del queratoacantoma. Descartamos A, porque el botón de Oriente es una leishmaniasis cutánea, transmitida por la picadura del flebotomo, y se presenta como una pápula que se ulcera y evoluciona lentamente, sin relación con el fármaco. Descartamos B, porque las metástasis en tránsito de melanoma suelen ser nódulos múltiples, a menudo pigmentados, entre el tumor primario y su territorio ganglionar, sin el cráter queratósico central. Descartamos D, porque el carcinoma basocelular crece lentamente, tiene un borde perlado con telangiectasias y no se asocia al tratamiento con vemurafenib.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_27.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 28, "especialidad": "Oftalmología", "tema": "Uveítis y patología del segmento posterior inflamatoria", "pregunta": "Hombre de 40 años que consulta por visión borrosa, dolor y ojo rojo derecho de 3 días de evolución. La exploración biomicroscópica se muestra en la imagen. La presión intraocular en ese ojo es 10 mmHg. El fondo de ojo no muestra alteraciones. ¿Cuál es la primera opción diagnóstica?", "opcion_a": "Coriorretinitis.", "opcion_b": "Queratitis herpetiforme.", "opcion_c": "Uveítis anterior.", "opcion_d": "Crisis glaucomatociclítica.", "correcta": "C", "explicacion": "La respuesta correcta es C) Uveítis anterior: la biomicroscopía muestra hiperemia periquerática (inyección ciliar) y un nivel blanquecino de células inflamatorias depositadas en la parte inferior de la cámara anterior, es decir, un hipopion. Junto con el dolor, la visión borrosa, la presión intraocular normal o baja y un fondo de ojo normal, es una uveítis anterior aguda intensa. Descartamos A, porque la coriorretinitis afecta al segmento posterior y daría lesiones en el fondo de ojo, que es normal. Descartamos B, porque la queratitis herpética muestra una úlcera corneal dendrítica que se tiñe con fluoresceína, no un hipopion. Descartamos D, porque la crisis glaucomatociclítica cursa con una presión intraocular muy elevada y poca inflamación, al contrario que en este caso, con presión de 10 mmHg.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_28.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 29, "especialidad": "Oftalmología", "tema": "Neurooftalmología — campimetría, vía óptica, pares craneales", "pregunta": "Mujer de 35 años con historia de cefalea de dos semanas de evolución, hipotiroidismo y un índice de masa corporal de 30 que presenta la siguiente imagen de fondo de ojo. ¿Cuál de los siguientes es el hallazgo MENOS probable que nos podremos encontrar?", "opcion_a": "Agudeza visual disminuida (0,1) en ambos ojos.", "opcion_b": "Campimetría con aumento de mancha ciega y defectos nasales.", "opcion_c": "Resonancia Magnética cerebral sin alteraciones significativas.", "opcion_d": "Composición de líquido cefalorraquídeo dentro de los límites de la normalidad.", "correcta": "A", "explicacion": "La respuesta correcta es A) Agudeza visual disminuida (0,1) en ambos ojos: la imagen muestra un papiledema, con el disco óptico sobreelevado y los bordes borrosos. En una mujer joven y obesa con cefalea, sugiere una hipertensión intracraneal idiopática (pseudotumor cerebri). En esta enfermedad la agudeza visual suele conservarse hasta fases avanzadas, así que una agudeza de 0,1 en ambos ojos es el hallazgo menos probable. Descartamos B, porque el aumento de la mancha ciega y los defectos nasales del campo visual son las alteraciones campimétricas típicas del papiledema. Descartamos C, porque en la hipertensión intracraneal idiopática la resonancia no muestra lesiones ocupantes de espacio ni hidrocefalia, que es precisamente un requisito del diagnóstico. Descartamos D, porque el líquido cefalorraquídeo tiene una presión de apertura elevada pero una composición normal.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_29.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 30, "especialidad": "Urgencias", "tema": "Urgencias en el paciente crítico/UCI", "pregunta": "Es tu primera guardia como médico de emergencias en una UVI móvil y asistes a un hombre de unos 50 años que acaba de desplomarse al suelo bruscamente. Cuando le exploras el paciente está inconsciente y no respira. Has comprobado que tampoco tiene pulso por lo que comienzas a realizar compresiones torácicas y ventilaciones a un ritmo 30:2. Uno de tus compañeros del equipo sanitario ha colocado las palas del monitor-desfibrilador y en la pantalla del monitor aparece la imagen que se muestra. ¿Qué actuación es la prioritaria en este caso?", "opcion_a": "Seguir con el masaje cardiaco y aislar la vía aérea mediante intubación orotraqueal.", "opcion_b": "Conseguir un acceso venoso para administrar adrenalina.", "opcion_c": "Cargar el desfibrilador y aplicar una descarga para continuar inmediatamente con el masaje cardiaco.", "opcion_d": "Avisar al centro coordinador de emergencias para que os envíen ayuda.", "correcta": "C", "explicacion": "La respuesta correcta es C) Cargar el desfibrilador y aplicar una descarga para continuar inmediatamente con el masaje cardiaco: el monitor muestra una taquicardia regular de complejos anchos en un paciente inconsciente, sin respiración ni pulso, es decir, una taquicardia ventricular sin pulso. Es un ritmo desfibrilable, y la prioridad es la desfibrilación precoz, reanudando las compresiones inmediatamente después de la descarga. Descartamos A, porque la intubación no es prioritaria y no debe retrasar la desfibrilación ni interrumpir las compresiones. Descartamos B, porque en los ritmos desfibrilables la adrenalina se administra después de la tercera descarga, no antes de la primera. Descartamos D, porque el equipo de soporte vital avanzado ya está en el lugar, y retrasar la descarga para pedir ayuda empeora la supervivencia.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_30.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 31, "especialidad": "Cardiología", "tema": "Arritmias", "pregunta": "El paciente con el ECG 1º, recibe un fármaco. Se muestra la secuencia electrocardiográfica postratamiento (2º y 3º). ¿Cuál es el fármaco administrado?", "opcion_a": "Verapamilo.", "opcion_b": "Atenolol.", "opcion_c": "Adenosina.", "opcion_d": "Digoxina.", "correcta": "C", "explicacion": "La respuesta correcta es C) Adenosina: el fármaco produce una interrupción súbita del circuito de reentrada supraventricular, generando un bloqueo AV transitorio que se refleja en el ECG con desaparición momentánea de la taquicardia y posterior retorno al ritmo sinusal, hallazgos típicos de la adenosina. Descartamos A, porque el verapamilo produce bloqueo AV de forma más lenta y con prolongación del intervalo PR que no es tan abrupta. Descartamos B, porque el atenolol disminuye la frecuencia de forma gradual y no genera un bloqueo AV inmediato. Descartamos D, porque la digoxina modifica la conducción AV de manera lenta y no produce la interrupción súbita característica.", "explicacion_calidad": "orientativa", "imagen_path": "/imagenes-mir/2016/imagen_31.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 32, "especialidad": "Neurología", "tema": "Neurología básica/fisiología", "pregunta": "¿Cuál de las siguientes estructuras corresponde a la arteria vertebral?", "opcion_a": "1.", "opcion_b": "2.", "opcion_c": "3.", "opcion_d": "4.", "correcta": "C", "explicacion": "La respuesta correcta es C) 3: la arteria vertebral asciende por los agujeros transversos de las vértebras cervicales, por lo que en un corte axial de TC con contraste aparece como un vaso redondeado de pequeño calibre pegado a la vértebra, a nivel de la apófisis transversa, que es la estructura señalada con el número 3. Descartamos A, porque el número 1 señala la vena yugular interna derecha, el vaso de mayor calibre y situación más lateral del paquete vascular del cuello. Descartamos B, porque el número 2 señala la arteria carótida común izquierda, situada por delante y medial a la vena yugular, lejos del agujero transverso. Descartamos D, porque el número 4 señala una estructura ósea del arco posterior de la vértebra, no un vaso.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_32.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 33, "especialidad": "Hematología", "tema": null, "pregunta": "¿Cuál es el diagnóstico radiológico?", "opcion_a": "Lesiones líticas en palas ilíacas.", "opcion_b": "Abombamiento de línea renopsoas derecha sugestivo de adenopatías.", "opcion_c": "Esplenomegalia.", "opcion_d": "Sacroileítis izquierda.", "correcta": "C", "explicacion": "La respuesta correcta es C) Esplenomegalia: en la radiografía simple de abdomen se ve un aumento de densidad de partes blandas en el hipocondrio izquierdo, que se extiende hacia abajo y desplaza las asas intestinales, compatible con un bazo aumentado de tamaño. Descartamos A, porque las palas ilíacas tienen una densidad ósea normal, sin lesiones líticas. Descartamos B, porque la línea del psoas y la silueta renal derechas no están desplazadas ni abombadas. Descartamos D, porque las articulaciones sacroilíacas tienen un aspecto normal y simétrico, sin esclerosis ni erosiones.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_33.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 34, "especialidad": "Traumatología", "tema": "Traumatismo raquimedular y urgencias graves", "pregunta": "De las siguientes estructuras óseas señale la apófisis odontoides:", "opcion_a": "1.", "opcion_b": "2.", "opcion_c": "3.", "opcion_d": "4.", "correcta": "C", "explicacion": "La respuesta correcta es C) 3: en este corte axial de TC a la altura del atlas, la apófisis odontoides de la segunda vértebra cervical es la estructura ósea redondeada situada en el centro del anillo del atlas, por detrás de su arco anterior, que es la señalada con el número 3. Descartamos A, porque el número 1 señala el hueso occipital en la parte posterior de la fosa craneal. Descartamos B, porque el número 2 señala la masa lateral del atlas. Descartamos D, porque el número 4 señala el arco anterior del atlas, que queda por delante de la odontoides.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_34.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 35, "especialidad": "Hematología", "tema": "Síndromes linfoproliferativos y leucemias", "pregunta": "Mujer de 25 años, sin antecedentes de interés, que presenta una adenopatía cervical indolora de 3 cm de diámetro, de crecimiento lento y de dos meses de evolución. La enferma refiere fiebre y sudoración nocturna. Se le practica biopsia de la adenopatía. ¿Cuál es el diagnóstico más probable?", "opcion_a": "Sarcoidosis.", "opcion_b": "Toxoplasmosis.", "opcion_c": "Tuberculosis.", "opcion_d": "Linfoma.", "correcta": "C", "explicacion": "La respuesta correcta es C) Tuberculosis: una adenopatía cervical de crecimiento lento en una mujer joven con fiebre y sudoración nocturna obliga a pensar en tuberculosis ganglionar y en linfoma, y la biopsia decide. La imagen muestra una zona de necrosis eosinófila amorfa (necrosis caseosa) rodeada de histiocitos epitelioides en empalizada, células gigantes multinucleadas y una corona de linfocitos, es decir, un granuloma necrotizante caseificante, que es la lesión característica de la tuberculosis. Descartamos A, porque la sarcoidosis produce granulomas no necrotizantes, sin necrosis caseosa central. Descartamos B, porque la toxoplasmosis ganglionar muestra hiperplasia folicular con acúmulos de histiocitos epitelioides pequeños y sin necrosis caseosa. Descartamos D, porque, aunque un linfoma puede dar fiebre y sudoración nocturna, la biopsia mostraría una sustitución de la arquitectura ganglionar por células linfoides atípicas o células de Reed-Sternberg, y no granulomas con necrosis caseosa.", "explicacion_calidad": "revisada", "imagen_path": "/imagenes-mir/2016/imagen_35.jpg", "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 36, "especialidad": "Digestivo", "tema": "Hepatopatías y cirrosis", "pregunta": "En relación con la anatomía de la vena porta una de las siguientes afirmaciones es FALSA:", "opcion_a": "Anatómicamente se forma por detrás del cuello del páncreas.", "opcion_b": "Al igual que muchas otras venas del organismo, sus paredes tienen válvulas.", "opcion_c": "En el hilio hepático suele estar detrás de la arteria hepática.", "opcion_d": "Su bifurcación presenta menos variantes anatómicas que los conductos biliares.", "correcta": "B", "explicacion": "La respuesta correcta es B) Al igual que muchas otras venas del organismo, sus paredes tienen válvulas: la vena porta es una vena sin válvulas, ya que su flujo proviene de la confluencia de venas mesentéricas y esplénica y necesita un paso continuo hacia el hígado sin obstrucción. Descartamos A, porque la vena porta se forma por la unión de la vena mesentérica superior y la vena esplénica justo detrás del cuello del páncreas. Descartamos C, porque en el hilio hepático la vena porta se sitúa típicamente detrás de la arteria hepática dentro del triángulo portal. Descartamos D, porque la bifurcación de la vena porta presenta menos variantes anatómicas que los conductos biliares, que son altamente variables.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 37, "especialidad": "ORL", "tema": null, "pregunta": "¿Cuál de las siguientes arterias NO es rama de la arteria carótida externa?", "opcion_a": "Arteria lingual.", "opcion_b": "Arteria facial.", "opcion_c": "Arteria oftálmica.", "opcion_d": "Arteria temporal superficial.", "correcta": "C", "explicacion": "La respuesta correcta es C) Arteria oftálmica: la arteria oftálmica es una rama de la arteria carótida interna y no de la externa, por lo que no pertenece al grupo de ramas de la carótida externa. Descartamos A, porque la arteria lingual es una rama directa de la arteria carótida externa. Descartamos B, porque la arteria facial también se origina de la arteria carótida externa. Descartamos D, porque la arteria temporal superficial es una rama de la arteria carótida externa.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 38, "especialidad": "Cardiología", "tema": "Cardiopatía isquémica", "pregunta": "¿Qué tipo de necrosis es característica del infarto agudo de miocardio?", "opcion_a": "Necrosis licuefactiva.", "opcion_b": "Necrosis coagulativa.", "opcion_c": "Necrosis caseosa.", "opcion_d": "Necrosis fibrinoide.", "correcta": "B", "explicacion": "La respuesta correcta es B) Necrosis coagulativa: en el infarto agudo de miocardio el tejido cardíaco sufre isquemia prolongada que produce una necrosis donde se conserva la arquitectura celular durante varios días, típica de la necrosis coagulativa. Este tipo de necrosis se diferencia de otras por la preservación de la forma de las fibras y la presencia de una zona de inflamación subsecuente. Descartamos A, porque la necrosis licuefactiva se asocia a tejidos con alto contenido de enzimas digestivas como el cerebro. Descartamos C, porque la necrosis caseosa es característica de la tuberculosis y de lesiones granulomatosas. Descartamos D, porque la necrosis fibrinoide se observa en vasculitis y en lesiones inmunes, no en infarto miocárdico.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 39, "especialidad": "Digestivo", "tema": "Patología biliopancreática", "pregunta": "Mujer de 58 años con antecedente de tiroiditis de Riedel. Presenta dolor abdominal, pérdida de peso e ictericia obstructiva. Ante la sospecha radiológica de carcinoma de páncreas, se realiza una duodenopancreatectomía cefálica. En el estudio anatomopatológico no encontramos un carcinoma, sino abundantes células inflamatorias con tendencia a rodear ductos, marcada fibrosis, flebitis obliterante y más de 50 células plasmáticas IgG4+ por campo de gran aumento. ¿Cuál es el diagnóstico?", "opcion_a": "Hamartoma pancreático.", "opcion_b": "Pancreatitis autoinmune.", "opcion_c": "Malacoplaquia.", "opcion_d": "Pancreatitis del surco.", "correcta": "B", "explicacion": "La respuesta correcta es B) Pancreatitis autoinmune: la presencia de abundantes células inflamatorias periductales, fibrosis marcada, flebitis obliterante y más de 50 plasmocitos IgG4+ por campo es típica de la pancreatitis autoinmune tipo 1, una manifestación de la enfermedad relacionada con IgG4. Descartamos A, porque el hamartoma pancreático es una lesión estructural sin infiltrado inflamatorio ni fibrosis característica. Descartamos C, porque la malacoplaquia se caracteriza por cuerpos de Michaelis-Gutmann y macrófagos, no por plasmocitos IgG4. Descartamos D, porque la pancreatitis del surco afecta al surco pancreatoduodenal y no muestra el patrón de IgG4 ni la flebitis obliterante.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 40, "especialidad": "Digestivo", "tema": "Patología esofágica", "pregunta": "El hallazgo histológico que permite un diagnóstico de esófago de Barret en una biopsia es la presencia de:", "opcion_a": "Epitelio plano papilomatoso.", "opcion_b": "Epitelio columnar especializado con células caliciformes.", "opcion_c": "Infiltrado inflamatorio mononuclear.", "opcion_d": "Acantosis glucogénica.", "correcta": "B", "explicacion": "La respuesta correcta es B) Epitelio columnar especializado con células caliciformes: este epitelio sustituye al escamoso en la zona de metaplasia y contiene células caliciformes productoras de moco, característica esencial del esófago de Barrett. Descartamos A, porque el epitelio plano papilomatoso no corresponde a la metaplasia columnar del esófago. Descartamos C, porque el infiltrado inflamatorio mononuclear es inespecífico y no constituye el criterio diagnóstico. Descartamos D, porque la acantosis glucogénica es una alteración cutánea y no se observa en biopsias esofágicas.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 41, "especialidad": "Ginecología", "tema": null, "pregunta": "¿Cuál de estos fármacos está contraindicado en embarazadas por el riesgo de malformaciones congénitas?", "opcion_a": "Gentamicina.", "opcion_b": "Dexametasona.", "opcion_c": "Isotretinoína.", "opcion_d": "Alfa-metildopa.", "correcta": "C", "explicacion": "La respuesta correcta es C) Isotretinoína: es un retinoide oral altamente teratogénico que produce malformaciones del tubo neural, cardíacas y craneofaciales, por lo que está contraindicada en el embarazo. Descartamos A, porque la gentamicina es un aminoglucósido que, aunque tiene riesgos de ototoxicidad fetal, no está clasificado como teratógeno directo. Descartamos B, porque la dexametasona es un glucocorticoide que puede usarse en ciertas situaciones obstétricas y no se asocia a malformaciones congénitas. Descartamos D, porque la alfa‑metildopa es un antihipertensivo de primera línea en embarazo y es seguro para el feto.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 42, "especialidad": "Miscelánea", "tema": null, "pregunta": "¿Cuál es la consecuencia de un alto volumen aparente de distribución de un fármaco?", "opcion_a": "Menor concentración en plasma.", "opcion_b": "Mayor velocidad de eliminación.", "opcion_c": "Mayor efecto farmacológico.", "opcion_d": "Mayor unión a proteínas plasmáticas.", "correcta": "A", "explicacion": "La respuesta correcta es A) Menor concentración en plasma: Un alto volumen aparente de distribución indica que el fármaco se reparte ampliamente en los tejidos, reduciendo la fracción que permanece en la sangre y, por tanto, la concentración plasmática. Descartamos B, porque la velocidad de eliminación está más relacionada con la depuración y la semivida que con el Vd. Descartamos C, porque un mayor Vd no implica un mayor efecto farmacológico, que depende de la concentración en el sitio de acción. Descartamos D, porque la unión a proteínas plasmáticas depende de la afinidad del fármaco y no del volumen de distribución.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 43, "especialidad": "Miscelánea", "tema": "Genética y fisiología básica — conceptos generales no cubiertos por otras especialidades", "pregunta": "Señale la respuesta CORRECTA. En pacientes metabolizadores lentos del CYP2D6 se esperaría encontrar:", "opcion_a": "Una reducción de la eficacia analgésica de codeína.", "opcion_b": "Ineficacia del tratamiento con acenocumarol.", "opcion_c": "Potenciación del efecto sinérgico de codeína con paracetamol.", "opcion_d": "Requerimiento de una dosis superior de amitriptilina.", "correcta": "A", "explicacion": "La respuesta correcta es A) Una reducción de la eficacia analgésica de codeína: la codeína es un profármaco que necesita ser metabolizada por CYP2D6 a morfina para ejercer su efecto analgésico, por lo que en metabolizadores lentos la conversión es insuficiente y el alivio del dolor disminuye. Descartamos B, porque el acenocumarol actúa sobre la vía de la vitamina K y no depende de CYP2D6. Descartamos C, porque la sinergia entre codeína y paracetamol no está relacionada con la velocidad de metabolismo de CYP2D6. Descartamos D, porque los metabolizadores lentos de CYP2D6 requieren dosis menores, no superiores, de amitriptilina para evitar toxicidad.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 44, "especialidad": "Infecciosas", "tema": "Antibioterapia y resistencias — elección de antibiótico según antibiograma, alergias", "pregunta": "Los beta-lactámicos son el grupo más numeroso de antibióticos. Uno de los aspectos NEGATIVOS de este grupo de antibióticos es:", "opcion_a": "La ausencia de derivados que se absorban bien por vía oral.", "opcion_b": "La falta de derivados con actividad antibacteriana sobre pseudomona aeruginosa.", "opcion_c": "La posibilidad de cualquiera de sus derivados, de producir reacciones alérgicas graves.", "opcion_d": "La necesidad de asociar inhibidores de betalactamasas, a cualquier derivado, para evitar las resistencias bacterianas.", "correcta": "C", "explicacion": "La respuesta correcta es C) La posibilidad de cualquiera de sus derivados, de producir reacciones alérgicas graves: los beta‑lactámicos comparten el anillo β‑lactámico y pueden desencadenar hipersensibilidad tipo I que puede manifestarse como anafilaxia, sin que la reacción esté limitada a una subclase concreta. Descartamos A, porque existen derivados de beta‑lactámicos con excelente absorción oral, como amoxicilina y cefalexina. Descartamos B, porque algunos beta‑lactámicos, como piperacilina‑tazobactam y los carbapenémicos, sí son activos contra Pseudomonas aeruginosa. Descartamos D, porque no todos los beta‑lactámicos requieren combinación con inhibidores de betalactamasas; muchos son estables frente a estas enzimas o se usan sin ellos.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 45, "especialidad": "Respiratorio", "tema": null, "pregunta": "Señale cuál de los fármacos enumerados a continuación y empleados en el tratamiento de la hipertensión arterial pulmonar NO es un análogo de la prostaciclina:", "opcion_a": "Iloprost.", "opcion_b": "Riociguat.", "opcion_c": "Treprostinil.", "opcion_d": "Epoprostenol.", "correcta": "B", "explicacion": "La respuesta correcta es B) Riociguat: no es un análogo de la prostaciclina, sino un estimulador soluble de guanilato ciclasa que aumenta la producción de GMPc. Por lo tanto, su mecanismo difiere del de los fármacos prostanoides. Descartamos A, porque el iloprost es un análogo sintético de la prostaciclina que actúa como agonista del receptor IP. Descartamos C, porque el treprostinil también es un análogo de la prostaciclina con actividad vasodilatadora pulmonar. Descartamos D, porque el epoprostenol es la prostaciclina natural utilizada como terapia intravenosa en la hipertensión arterial pulmonar.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 46, "especialidad": "Miscelánea", "tema": "Genética y fisiología básica — conceptos generales no cubiertos por otras especialidades", "pregunta": "El ser humano NO puede:", "opcion_a": "Convertir glucosa en lactato.", "opcion_b": "Transformar hidratos de carbono en ácidos grasos.", "opcion_c": "Transformar ácidos grasos en hidratos de carbono.", "opcion_d": "Convertir piruvato en glucosa.", "correcta": "C", "explicacion": "La respuesta correcta es C) Transformar ácidos grasos en hidratos de carbono: los ácidos grasos se oxidan a acetil‑CoA y, al entrar en el ciclo de Krebs, sus carbonos se liberan como CO₂, por lo que no pueden servir de sustrato para la gluconeogénesis. Descartamos A, porque la glucosa sí puede convertirse en lactato mediante la glucólisis anaeróbica. Descartamos B, porque el exceso de hidratos de carbono se puede transformar en ácidos grasos a través de la lipogénesis de novo. Descartamos D, porque el piruvato puede ser convertido en glucosa mediante la gluconeogénesis en hígado y riñón.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 47, "especialidad": "Endocrinología", "tema": "Obesidad y trastornos metabólicos", "pregunta": "El glucógeno es un polisacárido ramificado de alto peso molecular formado por moléculas de glucosa unidas entre sí por enlaces alfa-1,4 que forman largas cadenas que se ramifican cada 12-18 unidades por enlaces alfa-1,6. En relación al metabolismo del glucógeno, ¿cuál es la respuesta FALSA?", "opcion_a": "En el proceso de glucogenolisis se produce la degradación de glucógeno hasta glucosa-1-fosfato.", "opcion_b": "El glucógeno se puede acumular de forma anormal en las neuronas, como en la enfermedad de Lafora.", "opcion_c": "Las glucogenosis que afectan al hígado se presentan normalmente con hepatomegalia e hiperglucemia como primera sintomatología clínica.", "opcion_d": "La adrenalina regula el metabolismo del glucógeno.", "correcta": "C", "explicacion": "La respuesta correcta es C) Las glucogenosis que afectan al hígado se presentan normalmente con hepatomegalia e hiperglucemia como primera sintomatología clínica: en estas enfermedades la manifestación clínica típica es hipoglucemia, no hiperglucemia, por lo que la afirmación es incorrecta. Descartamos A, porque la glucogenólisis genera glucosa‑1‑fosfato a partir del glucógeno. Descartamos B, porque la enfermedad de Lafora se caracteriza por la acumulación anómala de glucógeno en neuronas. Descartamos D, porque la adrenalina actúa modulando la síntesis y degradación del glucógeno.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 48, "especialidad": "Nefrología", "tema": "Fisiología renal", "pregunta": "¿Cuál de las siguientes afirmaciones es CIERTA referente a la Angiotensina II en la filtración glomerular?", "opcion_a": "Angiotensina II contrae preferentemente las arteriolas eferentes en la mayoría de los estados fisiológicos, elevando la presión hidrostática glomerular.", "opcion_b": "Las arterias aferentes, son especialmente sensibles a la dilatación mediada por Angiotensina II en la mayoría de los estados fisiológicos asociados con la activación del sistema renina-angiotensina.", "opcion_c": "Las concentraciones de Angiotensina II aumentadas disminuyen la presión hidrostática glomerular, aumentando el flujo sanguíneo renal.", "opcion_d": "Angiotensina II, con su acción de constricción arteriolar, contribuye a la disminución de la reabsorción de sodio y agua.", "correcta": "A", "explicacion": "La respuesta correcta es A) Angiotensina II contrae preferentemente las arteriolas eferentes en la mayoría de los estados fisiológicos, elevando la presión hidrostática glomerular: la Ang II actúa con mayor afinidad sobre la arteriola eferente, lo que aumenta la presión dentro del glomérulo y ayuda a mantener la tasa de filtración cuando el flujo renal disminuye; además, esta constricción favorece la reabsorción de sodio y agua. Descartamos B, porque la Angiotensina II no dilata la arteriola aferente sino que la contrae o la mantiene sin cambios. Descartamos C, porque las concentraciones elevadas de Angiotensina II incrementan, no disminuyen, la presión hidrostática glomerular y reducen el flujo sanguíneo renal. Descartamos D, porque la Angiotensina II estimula, no disminuye, la reabsorción de sodio y agua en los túbulos.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 49, "especialidad": "Endocrinología", "tema": "Obesidad y trastornos metabólicos", "pregunta": "Los principales combustibles del cerebro en caso de ayuno prolongado son:", "opcion_a": "Los aminoácidos procedentes del hígado.", "opcion_b": "Los cuerpos cetónicos procedentes del músculo.", "opcion_c": "Los ácidos grasos procedentes del tejido adiposo.", "opcion_d": "Los cuerpos cetónicos procedentes del hígado.", "correcta": "D", "explicacion": "La respuesta correcta es D) Los cuerpos cetónicos procedentes del hígado: durante el ayuno prolongado la disponibilidad de glucosa disminuye y el cerebro, que no puede oxidar ácidos grasos, recurre a los cuerpos cetónicos producidos por el hígado a partir de acetil CoA, los cuales sustituyen gran parte del consumo de glucosa. Descartamos A, porque los aminoácidos no son la fuente principal de energía cerebral en ayuno prolongado. Descartamos B, porque los cuerpos cetónicos no se generan en el músculo sino en el hígado. Descartamos C, porque los ácidos grasos no pueden cruzar la barrera hematoencefálica para ser utilizados directamente por el cerebro.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 50, "especialidad": "Hematología", "tema": "Anemias", "pregunta": "La hepcidina tiene un papel central en la homeostasis del hierro. ¿Cuál de estas afirmaciones es cierta?", "opcion_a": "Su ausencia determina la sobrecarga de hierro.", "opcion_b": "El exceso de la misma permite aumentar la absorción intestinal de hierro.", "opcion_c": "Se produce principalmente en el riñón.", "opcion_d": "Su síntesis no está influida por el hierro ingerido.", "correcta": "A", "explicacion": "La respuesta correcta es A) Su ausencia determina la sobrecarga de hierro: la hepcidina inhibe la exportación de hierro a través de la ferroportina, por lo que su falta elimina este freno y favorece la acumulación sistémica de hierro. Descartamos B, porque el exceso de hepcidina disminuye, no aumenta, la absorción intestinal de hierro. Descartamos C, porque la principal fuente de hepcidina es el hígado, no el riñón. Descartamos D, porque la síntesis de hepcidina está regulada por los niveles de hierro ingerido y por la inflamación.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 51, "especialidad": "Pediatría", "tema": "Genética clínica y asesoramiento genético — herencia, genealogías, discapacidad intelectual de causa genética", "pregunta": "Respecto a los patrones de herencia de las enfermedades de origen genético, ¿cuál de las siguientes afirmaciones es cierta?", "opcion_a": "Una característica de las enfermedades con herencia autosómica dominante es la existencia de portadores asintomáticos.", "opcion_b": "Las enfermedades hereditarias ligadas al cromosoma Y son más frecuentes que las ligadas al cromosoma X.", "opcion_c": "No es posible la transmisión de una enfermedad con mutaciones del ADN mitocondrial desde un varón afectado a su descendencia.", "opcion_d": "La herencia poligénica es una de las formas clásicas de herencia mendeliana.", "correcta": "C", "explicacion": "La respuesta correcta es C) No es posible la transmisión de una enfermedad con mutaciones del ADN mitocondrial desde un varón afectado a su descendencia: el ADN mitocondrial se hereda casi exclusivamente por vía materna, pues los espermatozoides aportan poco o ningún citoplasma mitocondrial al óvulo. Por tanto, un varón portador de una mutación mitocondrial no puede transmitirla a sus hijos, quienes solo recibirán la carga mitocondrial de la madre. Descartamos A, porque en la herencia autosómica dominante los portadores son generalmente sintomáticos y la penetrancia completa o incompleta no implica portadores asintomáticos como regla. Descartamos B, porque las enfermedades ligadas al cromosoma Y son mucho menos frecuentes que las ligadas al cromosoma X, ya que el cromosoma Y contiene pocos genes. Descartamos D, porque la herencia poligénica implica la interacción de varios genes y no corresponde a los patrones mendelianos clásicos de una sola locus.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 52, "especialidad": "Pediatría", "tema": "Genética clínica y asesoramiento genético — herencia, genealogías, discapacidad intelectual de causa genética", "pregunta": "Una pareja con un primer hijo varón (caso índice) afecto de fibrosis quística (mucoviscidosis) acude a la consulta de consejo genético. El diagnóstico molecular indica que el caso índice es homocigoto para la mutación F508del y sus padres portadores heterocigotos. El genetista clínico les informará acerca de la forma de transmisión de la enfermedad. ¿Qué afirmación es la correcta?", "opcion_a": "La probabilidad de que el siguiente descendiente esté afecto es del 25%.", "opcion_b": "La probabilidad de que el siguiente descendiente esté afecto es del 50%.", "opcion_c": "Al haber tenido un hijo afecto, el siguiente descendiente también estará afecto.", "opcion_d": "Al haber tenido un hijo homocigoto F508del, el siguiente descendiente será portador heterocigoto (67%) o de genotipo homocigoto sin la mutación (33%).", "correcta": "A", "explicacion": "La respuesta correcta es A) La probabilidad de que el siguiente descendiente esté afecto es del 25%: ambos progenitores son portadores heterocigotos y la transmisión autosómica recesiva da un 25% de hijos homocigotos afectados, 50% portadores y 25% sin mutación. Descartamos B, porque la herencia recesiva no produce un 50% de afectados. Descartamos C, porque la aparición de un hijo afecto no determina el fenotipo del siguiente. Descartamos D, porque la proporción de portadores es 50% y la de no portadores 50%, no 67% y 33%.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 53, "especialidad": "Neurología", "tema": "Enfermedades neuromusculares y de nervio periférico", "pregunta": "¿Cuál es el mecanismo genético subyacente a la distrofia miotónica tipo 1 o enfermedad de Steinert?", "opcion_a": "La expansión de un trinucleótido en el gen ZNF9.", "opcion_b": "La duplicación de regiones concretas del gen CNBP.", "opcion_c": "La presencia de mutaciones puntuales en el gen DMPK.", "opcion_d": "La expansión de un trinucleótido en el gen DMPK.", "correcta": "D", "explicacion": "La respuesta correcta es D) La expansión de un trinucleótido en el gen DMPK: la enfermedad de Steinert tipo 1 se debe a una expansión de repeticiones CTG en una región no codificante del gen DMPK, lo que genera toxicidad por ARN y alteración del splicing. Descartamos A, porque la expansión no ocurre en el gen ZNF9. Descartamos B, porque no hay duplicaciones en el gen CNBP en esta forma. Descartamos C, porque la patología no se debe a mutaciones puntuales en DMPK.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 54, "especialidad": "Pediatría", "tema": "Genética clínica y asesoramiento genético — herencia, genealogías, discapacidad intelectual de causa genética", "pregunta": "Isabel tiene tres hijos varones y una hija (María), todos ellos sanos. Un hermano y un tío materno de Isabel fallecieron por estar afectos de la enfermedad de Duchenne; una enfermedad recesiva ligada al cromosoma X. Actualmente, María desea quedarse embarazada y quiere conocer el riesgo de transmitir la enfermedad a su descendencia. Con los datos recogidos, ¿cuál es la probabilidad de que María sea portadora de la enfermedad de Duchenne?", "opcion_a": "2/3.", "opcion_b": "1/2.", "opcion_c": "1/4.", "opcion_d": "Menos de 1/4.", "correcta": "D", "explicacion": "La respuesta correcta es D) Menos de 1/4: la madre de Isabel tiene un hijo y un hermano afectos, por lo que es portadora obligada, e Isabel tiene a priori una probabilidad de 1/2 de ser portadora. Esa probabilidad se corrige con un dato muy importante: Isabel ha tenido tres hijos varones sanos. Si fuera portadora, la probabilidad de tres varones sanos sería de 1/8, por lo que el cálculo bayesiano reduce su riesgo de ser portadora a 1/9. María solo puede ser portadora si Isabel lo es y le transmite el cromosoma X afectado (1/2), así que su riesgo es de aproximadamente 1/18, claramente inferior a 1/4. Descartamos A, porque 2/3 es la probabilidad clásica de ser portadora de la madre de un caso aislado, que no es la situación de María. Descartamos B, porque 1/2 es el riesgo previo de Isabel, no el de su hija. Descartamos C, porque 1/4 es el riesgo de María si no se tiene en cuenta que Isabel ha tenido tres hijos varones sanos, información que reduce mucho la probabilidad.", "explicacion_calidad": "revisada", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 55, "especialidad": "Oncología", "tema": "Oncología genética y síndromes hereditarios", "pregunta": "Señale la respuesta correcta en relación a la carcinogénesis:", "opcion_a": "Los oncogenes se comportan de forma dominante.", "opcion_b": "La mutación de genes supresores de tumores origina una activación de su función normal.", "opcion_c": "El gen RB es un oncogen.", "opcion_d": "El gen RAS es un gen supresor de tumores.", "correcta": "A", "explicacion": "La respuesta correcta es A) Los oncogenes se comportan de forma dominante: los oncogenes son versiones mutadas de genes normales que, al activarse, promueven el crecimiento celular sin necesidad de que la segunda alela esté alterada, por lo que su efecto es dominante. Descartamos B, porque la mutación de genes supresores de tumores conlleva pérdida de función y no activación. Descartamos C, porque el gen RB es un gen supresor de tumores, no un oncogén. Descartamos D, porque RAS es un oncogén que estimula la proliferación, no un gen supresor.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 56, "especialidad": "Pediatría", "tema": "Neonatología y patología del recién nacido — cardiopatías congénitas, RCIU/macrosomía, síndromes congénitos", "pregunta": "Respecto a la enfermedad hemolítica del recién nacido, señale la respuesta correcta:", "opcion_a": "Es una reacción mediada por IgE.", "opcion_b": "Está mediada por anticuerpos de la clase IgG de la madre.", "opcion_c": "Está mediada por anticuerpos del recién nacido.", "opcion_d": "Es una reacción mediada por células T CD8+.", "correcta": "B", "explicacion": "La respuesta correcta es B) Está mediada por anticuerpos de la clase IgG de la madre: la enfermedad hemolítica del recién nacido se produce cuando anticuerpos IgG maternos atraviesan la placenta y se unen a antígenos eritrocitarios del feto, provocando su destrucción. Descartamos A, porque la reacción no involucra IgE sino IgG. Descartamos C, porque los anticuerpos responsables provienen de la madre y no del recién nacido. Descartamos D, porque la patogenia no depende de linfocitos T citotóxicos CD8+.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 57, "especialidad": "Hematología", "tema": null, "pregunta": "Los receptores para el antígeno de los linfocitos se denominan clonotípicos porque:", "opcion_a": "Cada linfocito y su descendencia (clona) expresa un único tipo de ellos con una sola especificidad antigénica.", "opcion_b": "Cada linfocito y su descendencia (clona) expresa un único tipo de ellos con varias especificidades antigénicas.", "opcion_c": "Varios linfocitos y sus descendencias (clonas) expresan varios tipos de ellos con varias especificidades antigénicas.", "opcion_d": "Tras clonaje molecular y reordenamiento génico, los linfocitos adquieren especificidad antigénica clonal.", "correcta": "A", "explicacion": "La respuesta correcta es A) Cada linfocito y su descendencia (clona) expresa un único tipo de ellos con una sola especificidad antigénica: los receptores de los linfocitos, ya sean de tipo B o T, se generan mediante recombinación V(D)J y cada célula madre produce un único receptor que se transmite a todas sus progenies, garantizando una especificidad única. Esta característica clonal permite que la respuesta inmune sea dirigida y que la memoria inmunológica conserve la misma especificidad. Descartamos B, porque un linfocito clonado no puede expresar varios tipos de receptores con distintas especificidades. Descartamos C, porque la diversidad de receptores no se distribuye en varios linfocitos con múltiples especificidades simultáneas. Descartamos D, porque la especificidad antigénica no se adquiere tras el clonaje molecular, sino que está determinada durante el proceso de recombinación génica previo al desarrollo del linfocito.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 58, "especialidad": "Respiratorio", "tema": "Asma bronquial", "pregunta": "En el asma bronquial alérgico, una de estas moléculas es la responsable del aumento de síntesis de IgE:", "opcion_a": "Interferón gamma.", "opcion_b": "Interleucina 1.", "opcion_c": "Interleucina 4.", "opcion_d": "Interleucina 5.", "correcta": "C", "explicacion": "La respuesta correcta es C) Interleucina 4: en la respuesta alérgica mediada por linfocitos tipo Th, la IL-4 estimula el cambio de clase de los B a IgE, favoreciendo la sensibilización alérgica y la producción de anticuerpos IgE. Descartamos A, porque el interferón gamma está asociado a respuestas tipo Th1 y no promueve la síntesis de IgE. Descartamos B, porque la interleucina 1 es una citocina proinflamatoria temprana sin efecto directo sobre la clase de anticuerpos IgE. Descartamos D, porque la interleucina 5 está implicada en la eosinofilia y en la atracción de eosinófilos, pero no regula la producción de IgE.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 59, "especialidad": "Dermatología", "tema": "Urticaria, angioedema y reacciones alérgicas cutáneas", "pregunta": "Una urticaria inducida por fármacos puede ser causada por los siguientes mecanismos EXCEPTO:", "opcion_a": "Una respuesta dependiente de IgE.", "opcion_b": "Por inmunocomplejos circulantes.", "opcion_c": "Activación no inmunológica de la vía efectora.", "opcion_d": "Un déficit de capsaicina.", "correcta": "D", "explicacion": "La respuesta correcta es D) Un déficit de capsaicina: la capsaicina no participa en la fisiopatología de la urticaria inducida por fármacos, pues su acción se limita a la activación de los receptores TRPV1 y a la sensación de ardor, sin influir en la liberación de mediadores de la hipersensibilidad. Por lo tanto, un déficit de esta sustancia no puede explicar la aparición de la urticaria. Descartamos A, porque la urticaria inducida por fármacos puede originarse por una reacción dependiente de IgE que induce la degranulación de mastocitos. Descartamos B, porque los inmunocomplejos circulantes pueden activar el complemento y provocar la liberación de histamina, generando urticaria. Descartamos C, porque algunos fármacos pueden desencadenar la liberación directa de mediadores de los mastocitos sin necesidad de un proceso inmunológico, lo que constituye una activación no inmunológica de la vía efectora.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 60, "especialidad": "Infecciosas", "tema": "Vacunas e inmunización — COVID, neumococo, mecanismos inmunológicos", "pregunta": "¿Cuál de estos receptores de las células del sistema inmune se localizan exclusivamente en el citoplasma celular?", "opcion_a": "Nod-like receptors (NLR).", "opcion_b": "Receptor del linfocito T alfa-beta (TcR alfabeta).", "opcion_c": "Toll-like receptors (TLR).", "opcion_d": "Receptor del linfocito T gamma-delta (TcR gamma-delta).", "correcta": "A", "explicacion": "La respuesta correcta es A) Nod-like receptors (NLR): estos receptores pertenecen a la familia de receptores de reconocimiento de patrones intracelular y se localizan exclusivamente en el citoplasma donde detectan componentes microbianos. Su activación desencadena la formación del inflamasoma y la producción de citocinas inflamatorias. Descartamos B, porque el receptor del linfocito T alfa-beta es una molécula de superficie que se asocia a un complejo de señalización y se expresa en la membrana plasmática. Descartamos C, porque los Toll-like receptors pueden estar en la membrana plasmática o en endosomas y no son exclusivamente citoplasmáticos. Descartamos D, porque el receptor del linfocito T gamma-delta también es un receptor de superficie que requiere un complejo de señalización y se localiza en la membrana.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 61, "especialidad": "Infecciosas", "tema": "Sepsis y shock séptico — manejo inicial, antibioterapia empírica", "pregunta": "Hombre de 62 años que acude a urgencias del hospital por presentar fiebre de 38,3°C y escalofríos. Está taquicárdico y taquipnéico. Analítica de sangre: leucocitosis con desviación izquierda. La presión arterial es de 90/60 mmHg. No se escuchan soplos en la auscultación cardíaca y la RX de tórax descarta una neumonía. Como historial de interés refiere infecciones del tracto urinario de repetición. Hace una semana el médico de cabecera le recetó cefuroxima, fármaco que está tomando actualmente. Se le extraen dos hemocultivos y se remite orina para examen del sedimento y cultivo microbiológico. El sedimento es patológico, con intensa piuria, pero nitritos negativos. A las 24 horas se informa desde el laboratorio de microbiología que tanto la orina como los hemocultivos remitidos son positivos y en ellos se observa cocos grampositivos agrupados en cadenas, pendientes de identificación y antibiograma. A la espera del resultado definitivo, ¿qué recomendaría usted?", "opcion_a": "Continuar con cefuroxima a la espera del resultado definitivo, pues el paciente ha llevado múltiples tratamientos y no deberíamos equivocarnos en su tratamiento actual.", "opcion_b": "Cambiar a ertapenem, pensando en la posibilidad de microorganismos multirresistentes.", "opcion_c": "Cambiar a un tratamiento antimicrobiano de amplio espectro que cubra Enterococcus spp.", "opcion_d": "Cambiar a un tratamiento antimicrobiano de amplio espectro que contenga imipenem, pensando en la posibilidad de Staphylococcus aureus, ya que nuestro hospital tiene una elevada incidencia de S. aureus resistente a meticilina (SARM)", "correcta": "C", "explicacion": "La respuesta correcta es C) Cambiar a un tratamiento antimicrobiano de amplio espectro que cubra Enterococcus spp: los cocos grampositivos en cadenas aislados de orina y sangre en un cuadro de sepsis de origen urinario son altamente sugestivos de Enterococcus, que no está cubierto por cefuroxima y requiere un antibiótico activo contra este género; iniciar una terapia que incluya ampicilina o vancomicina más un aminoglucósido garantiza la cobertura adecuada mientras se espera el antibiograma. Descartamos A, porque cefuroxima no cubre Enterococcus y el paciente presenta sepsis grave que necesita un espectro mayor. Descartamos B, porque ertapenem tiene actividad limitada contra Enterococcus y no es la mejor opción para cubrir este patógeno. Descartamos D, porque la sospecha de S. aureus resistente a meticilina no está respaldada por la morfología de los cocci y el uso de imipenem sería excesivo y no dirigido al Enterococcus.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 62, "especialidad": "Infecciosas", "tema": "Infecciones en el paciente inmunodeprimido/trasplantado — oportunistas", "pregunta": "¿Qué respuesta es CIERTA respecto a Candida albicans?", "opcion_a": "Es el principal agente causante de neumonía asociada a ventilación mecánica en las unidades de críticos.", "opcion_b": "Es un hongo filamentoso que requiere medios con sangre de cordero para su aislamiento en el laboratorio de microbiología.", "opcion_c": "Se destruye masivamente en presencia de fluorquinolonas.", "opcion_d": "Las infecciones causadas por este hongo suelen responder bien a los compuestos azólicos.", "correcta": "D", "explicacion": "La respuesta correcta es D) Las infecciones causadas por este hongo suelen responder bien a los compuestos azólicos: Candida albicans es una levadura que se trata habitualmente con fluconazol u otros azoles, los cuales inhiben su síntesis de ergosterol y logran curar la mayoría de las infecciones superficiales y sistémicas. Descartamos A, porque la neumonía asociada a ventilación mecánica está mayormente causada por bacterias como Pseudomonas aeruginosa y Staphylococcus aureus, no por Candida. Descartamos B, porque C. albicans es una levadura que crece en medios de cultivo estándar como agar Sabouraud y no requiere sangre de cordero para su aislamiento. Descartamos C, porque las fluoroquinolonas actúan sobre enzimas bacterianas y no tienen actividad antifúngica contra Candida.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 63, "especialidad": "Infecciosas", "tema": "Tuberculosis y micobacterias — diagnóstico, resistencias, retratamiento", "pregunta": "¿Cuál de estas micobacterias NO pertenece al complejo Mycobacterium tuberculosis?", "opcion_a": "Mycobacterium bovis.", "opcion_b": "Mycobacterium kansasii.", "opcion_c": "Mycobacterium africanum.", "opcion_d": "Bacilo de Calmette-Guerin (BCG).", "correcta": "B", "explicacion": "La respuesta correcta es B) Mycobacterium kansasii: es una micobacteria no tuberculosa que no forma parte del complejo Mycobacterium tuberculosis, el cual incluye a M. tuberculosis, M. bovis, M. africanum y la cepa BCG. A diferencia de los miembros del complejo, M. kansasii se asocia principalmente a enfermedad pulmonar en pacientes con enfermedad pulmonar crónica y no se transmite de forma típica como la tuberculosis. Descartamos A, porque Mycobacterium bovis es una especie del complejo y la base de la vacuna BCG. Descartamos C, porque Mycobacterium africanum es una variante del complejo que causa tuberculosis humana. Descartamos D, porque el bacilo de Calmette-Guerin es una cepa atenuada de Mycobacterium bovis, por lo tanto pertenece al complejo.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 64, "especialidad": "Pediatría", "tema": "Enfermedades exantemáticas e infecciones pediátricas clásicas", "pregunta": "¿Cuál es el agente bacteriano más común de la neumonía adquirida en la comunidad en la infancia?", "opcion_a": "Streptococcus pneumoniae.", "opcion_b": "Hemophilus influenzae B.", "opcion_c": "Mycoplasma pneumoniae.", "opcion_d": "Staphylococcus aureus.", "correcta": "A", "explicacion": "La respuesta correcta es A) Streptococcus pneumoniae: es el patógeno más frecuente en la neumonía adquirida en la comunidad en la infancia y se asocia a una enfermedad típica con consolidación lobar. Además, su sensibilidad a la penicilina lo convierte en el objetivo principal del tratamiento empírico. Descartamos B, porque Haemophilus influenzae tipo b ha disminuido su incidencia tras la vacunación y ya no es la causa principal. Descartamos C, porque Mycoplasma pneumoniae predomina en adolescentes mayores y produce una neumonía atípica. Descartamos D, porque Staphylococcus aureus se asocia más a neumonías post‑influenza o complicaciones, no a la neumonía comunitaria típica.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 65, "especialidad": "Infecciosas", "tema": "Infecciones en el paciente inmunodeprimido/trasplantado — oportunistas", "pregunta": "Los antifúngicos equinocandinas poseen un mecanismo de acción basado en:", "opcion_a": "Inhibición de la síntesis proteica por interacción con la subunidad 30S del ribosoma.", "opcion_b": "Alteración de la topoisomerasa II con afectación de la replicación del ADN.", "opcion_c": "Inhibición de la sintasa de beta-1,3 glucano implicada en la síntesis de la pared celular fúngica.", "opcion_d": "Inhibición de la polimerasa fúngica implicada en la síntesis del ARN del hongo.", "correcta": "C", "explicacion": "La respuesta correcta es C) Inhibición de la sintasa de beta-1,3 glucano implicada en la síntesis de la pared celular fúngica: los equinocandinas bloquean la β‑1,3‑D‑glucano sintasa, enzima esencial para la formación de la pared celular del hongo, provocando pérdida de integridad y muerte celular; este mecanismo es específico y no afecta a procesos metabólicos humanos. Descartamos A, porque esa descripción corresponde a los aminoglucósidos que inhiben la subunidad 30S del ribosoma bacteriano. Descartamos B, porque la alteración de la topoisomerasa II es típica de fluoroquinolonas, no de antifúngicos. Descartamos D, porque la inhibición de la polimerasa del ARN es el modo de acción del flucitosina, no de los equinocandinas.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 66, "especialidad": "Cardiología", "tema": "Arritmias", "pregunta": "En relación con las taquicardias supraventriculares, señale la respuesta CORRECTA:", "opcion_a": "La más frecuente es la taquicardia por reentrada aurículo-ventricular por una vía accesoria.", "opcion_b": "El “signo de la rana” (ondas a visibles en el pulso yugular) es típico de la taquicardia auricular.", "opcion_c": "El masaje del seno carotídeo es útil para revertir un episodio de flutter auricular.", "opcion_d": "El tratamiento de elección de la taquicardia por reentrada intranodal recurrente es la ablación con radiofrecuencia.", "correcta": "D", "explicacion": "La respuesta correcta es D) El tratamiento de elección de la taquicardia por reentrada intranodal recurrente es la ablación con radiofrecuencia: la taquicardia por reentrada intranodal se maneja inicialmente con maniobras vagales y fármacos, pero cuando es recurrente la ablación por radiofrecuencia del nodo AV modificada es la terapia de primera línea por su alta eficacia y bajo riesgo. Descartamos A, porque la taquicardia supraventricular más frecuente es la por reentrada intranodal, no la por vía accesoria. Descartamos B, porque el “signo de la rana” se asocia al flutter auricular, no a la taquicardia auricular. Descartamos C, porque el masaje del seno carotídeo es útil en la taquicardia por reentrada intranodal, no en el flutter auricular.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 67, "especialidad": "Cardiología", "tema": "Insuficiencia cardíaca", "pregunta": "¿Cuál de los siguientes hallazgos NO se encuentra en la miocardiopatía restrictiva?", "opcion_a": "Función sistólica normal o ligeramente reducida.", "opcion_b": "Presiones de llenado izquierda y derecha elevadas.", "opcion_c": "Movimiento sistólico anterior de la válvula mitral.", "opcion_d": "Bajo voltaje y alteraciones de la conducción en el electrocardiograma.", "correcta": "C", "explicacion": "La respuesta correcta es C) Movimiento sistólico anterior de la válvula mitral: este hallazgo es típico de la miocardiopatía hipertrófica obstructiva y no se observa en la miocardiopatía restrictiva, donde la contractilidad sistólica se mantiene normal o ligeramente reducida. Descartamos A, porque la función sistólica suele estar preservada o con ligera disminución en la forma restrictiva. Descartamos B, porque la rigidez ventricular produce elevación de las presiones de llenado tanto izquierda como derecha. Descartamos D, porque el ECG frecuentemente muestra bajo voltaje y alteraciones de la conducción debido a la infiltración o fibrosis miocárdica.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 68, "especialidad": "Cardiología", "tema": "Cardiopatía isquémica", "pregunta": "Mujer de 87 años con antecedentes de hipertensión arterial, ingresada hace 48 horas en la unidad coronaria por infarto agudo de miocardio con elevación de ST de localización anterior. Avisa por disnea. En la exploración destaca soplo sistólico con frémito, irradiado al borde esternal derecho que no estaba presente al ingreso. ¿Qué complicación sospecha usted?", "opcion_a": "Insuficiencia cardiaca por necrosis extensa.", "opcion_b": "Aneurisma anterior.", "opcion_c": "Rotura de la pared libre del ventrículo izquierdo.", "opcion_d": "Rotura en el tabique interventricular.", "correcta": "D", "explicacion": "La respuesta correcta es D) Rotura en el tabique interventricular: la aparición de un soplo sistólico con frémito nuevo y radiación al borde esternal derecho 48 h después de un infarto anterior indica una comunicación anormal entre los ventrículos, típica de la rotura del septo interventricular. Este cuadro se asocia a disnea súbita y a un murmullo holosistólico que no estaba presente al ingreso. Descartamos A, porque la insuficiencia cardiaca por necrosis extensa produciría un soplo más difuso y signos de sobrecarga sin el frémito característico; Descartamos B, porque el aneurisma anterior se manifiesta con un soplo sistólico de regurgitación mitral y no con frémito ni radiación al borde esternal derecho; Descartamos C, porque la rotura de la pared libre del ventrículo izquierdo suele producir un choque rápido, pulso débil y no un soplo sistólico con frémito.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 69, "especialidad": "Cirugía", "tema": null, "pregunta": "Señale la respuesta FALSA en relación al tratamiento quirúrgico de los aneurismas de aorta torácica:", "opcion_a": "La sustitución de la aorta aneurismática por un injerto está indicada cuando el diámetro de la aorta ascendente es mayor de 4,5 cm.", "opcion_b": "En pacientes con diagnóstico de enfermedad de Marfan o válvula aórtica bicúspide, se considerará el tratamiento quirúrgico cuando la aorta tenga entre 4 y 5 cm de diámetro.", "opcion_c": "Se considera necesario intervenir sobre la aorta torácica descendente aneurismática si su diámetro es superior a 6 cm.", "opcion_d": "Se recomienda sustituir la aorta aneurismática cuando, en un periodo de 1 año, se observa un incremento del diámetro del aneurisma de más de 1 cm.", "correcta": "A", "explicacion": "La respuesta correcta es A) La sustitución de la aorta aneurismática por un injerto está indicada cuando el diámetro de la aorta ascendente es mayor de 4,5 cm: esta afirmación es falsa porque la indicación quirúrgica en la aorta ascendente se establece habitualmente a partir de 5,5 cm en pacientes sin factores de riesgo, mientras que el umbral de 4,5 cm corresponde a pacientes con enfermedad de Marfan o válvula bicúspide. Descartamos B, porque en esas patologías la cirugía se plantea cuando el diámetro está entre 4 y 5 cm, lo que coincide con las recomendaciones actuales. Descartamos C, porque la indicación de intervención en la aorta torácica descendente se fija en diámetros superiores a 6 cm. Descartamos D, porque un crecimiento del aneurisma superior a 1 cm en un año es también una indicación establecida para la reparación quirúrgica.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 70, "especialidad": "Cardiología", "tema": "Insuficiencia cardíaca", "pregunta": "En una situación de insuficiencia cardiaca, el corazón presenta distintos mecanismos adaptativos. ¿Cuál de los siguientes NO es correcto?", "opcion_a": "Inhibición del sistema arginina-vasopresina, que genera vasoconstricción y retención hidrosalina.", "opcion_b": "Desarrollo de hipertrofia miocárdica, para normalizar la sobrecarga de la pared ventricular.", "opcion_c": "Activación del sistema nervioso simpático, que aumenta la contractilidad ventricular.", "opcion_d": "Alteraciones en la producción de energía en el miocardio y modificaciones en la matriz extracelular de los miocardiocitos.", "correcta": "A", "explicacion": "La respuesta correcta es A) Inhibición del sistema arginina-vasopresina, que genera vasoconstricción y retención hidrosalina: en la insuficiencia cardíaca el sistema vasopresina se activa, no se inhibe, favoreciendo vasoconstricción y retención de agua, por lo que la afirmación es incorrecta. Descartamos B, porque la hipertrofia miocárdica es una respuesta adaptativa que busca normalizar la tensión mural ante la sobrecarga. Descartamos C, porque la activación simpática incrementa la contractilidad y la frecuencia cardíaca como mecanismo compensatorio. Descartamos D, porque la insuficiencia cardíaca se asocia a disfunción metabólica del miocardio y a remodelación de la matriz extracelular.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 71, "especialidad": "Cardiología", "tema": "Insuficiencia cardíaca", "pregunta": "Hombre de 84 de edad, con insuficiencia cardiaca crónica en grado funcional II secundario a cardiopatía isquémica con disfunción sistólica grave no revascularizable, enfermedad renal crónica estadio 3 (filtrado glomerular 45-50 mL/min) y fibrilación auricular permanente con frecuencia cardiaca >80 latidos por minuto. ¿Cuál de los siguientes fármacos NO aporta beneficio al paciente según la evidencia disponible en la actualidad?", "opcion_a": "Ivabradina.", "opcion_b": "Inhibidores de la enzima convertidora de angiotensina.", "opcion_c": "Anti-aldosterónicos.", "opcion_d": "Beta-bloqueantes.", "correcta": "A", "explicacion": "La respuesta correcta es A) Ivabradina: no aporta beneficio en insuficiencia cardíaca con fracción de eyección reducida porque su mecanismo de reducción de frecuencia cardíaca solo funciona en ritmo sinusal y los ensayos clínicos no demostraron reducción de mortalidad ni de hospitalizaciones en pacientes con fibrilación auricular. Descartamos B, porque los inhibidores de la enzima convertidora de angiotensina mejoran la supervivencia y reducen la progresión de la insuficiencia cardíaca. Descartamos C, porque los anti‑aldosterónicos disminuyen la mortalidad y la morbilidad en pacientes con insuficiencia cardíaca crónica. Descartamos D, porque los beta‑bloqueantes reducen la mortalidad y los eventos cardiovasculares en la insuficiencia cardíaca con disfunción sistólica.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 72, "especialidad": "Cardiología", "tema": null, "pregunta": "Un hombre de 45 años, con antecedentes de un cuadro febril y dolor torácico, acude al hospital con disnea y taquipnea. En la exploración física las cifras de presión arterial están bajas, la presión venosa yugular elevada con un seno x descendente prominente y tiene pulso paradójico. ¿Qué diagnóstico sospecharía?", "opcion_a": "Miocardiopatía dilatada.", "opcion_b": "Derrame pericárdico con taponamiento cardiaco.", "opcion_c": "Pericarditis constrictiva.", "opcion_d": "Cardiopatía isquémica.", "correcta": "B", "explicacion": "La respuesta correcta es B) Derrame pericárdico con taponamiento cardiaco: los hallazgos de hipotensión, ingurgitación venosa yugular con descenso x prominente y pulso paradójico son clásicos de taponamiento, que indica compresión del corazón por líquido pericárdico. Esta compresión limita el llenado diastólico y produce la caída de la presión sistólica durante la inspiración. Descartamos A, porque la miocardiopatía dilatada no genera el descenso x ni el pulso paradójico típicos de taponamiento. Descartamos C, porque la pericarditis constrictiva se asocia a un descenso y prominente, no x, y carece de pulso paradójico. Descartamos D, porque la cardiopatía isquémica no explica la combinación de hipotensión, JVP elevada y pulso paradójico sin evidencia de infarto.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 73, "especialidad": "Cardiología", "tema": "Patología vascular/aórtica", "pregunta": "La presencia en el cateterismo cardiaco derecho de una presión media de la arteria pulmonar > de 25 mm de Hg y una presión enclavada (o capilar) pulmonar > de 15 mm de Hg, es definitorio de:", "opcion_a": "Hipertensión arterial pulmonar idiopática.", "opcion_b": "Hipertensión arterial pulmonar asociada a conectivopatía.", "opcion_c": "Hipertensión pulmonar secundaria a cardiopatía izquierda.", "opcion_d": "Hipertensión pulmonar tromboembólica crónica.", "correcta": "C", "explicacion": "La respuesta correcta es C) Hipertensión pulmonar secundaria a cardiopatía izquierda: la presión media de la arteria pulmonar >25 mmHg indica hipertensión pulmonar y la presión enclavada >15 mmHg refleja elevación de la presión de cuña, señal de disfunción del corazón izquierdo; por tanto el cuadro corresponde a hipertensión pulmonar por enfermedad izquierda. Descartamos A, porque la hipertensión arterial pulmonar idiopática se caracteriza por presión de cuña normal. Descartamos B, porque la asociada a conectivopatía también pertenece al grupo de hipertensión arterial pulmonar con cuña normal. Descartamos D, porque la tromboembólica crónica no eleva la presión de cuña.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 74, "especialidad": "Cirugía", "tema": "Profilaxis y cuidados perioperatorios", "pregunta": "La localización más frecuente de la trombosis venosa profunda es:", "opcion_a": "Plexos venosos de los músculos sóleos.", "opcion_b": "Sector femoral en el muslo.", "opcion_c": "Sector iliaco.", "opcion_d": "Vena cava inferior.", "correcta": "A", "explicacion": "La respuesta correcta es A) Plexos venosos de los músculos sóleos: son la localización más frecuente de la trombosis venosa profunda porque la bomba muscular de la pantorrilla favorece la estasis venosa y la presencia de numerosas válvulas predisponen a la formación de trombos. Además, la posición dependiente y la menor velocidad del flujo en estos vasos favorecen la trombosis. Descartamos B, porque la vena femoral es menos frecuente que los vasos de la pierna. Descartamos C, porque la trombosis iliaca ocurre con menor frecuencia y suele asociarse a factores de riesgo específicos. Descartamos D, porque la trombosis de la vena cava inferior es muy rara y suele estar relacionada con patologías extensas.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 75, "especialidad": "Cirugía", "tema": "Cirugía hepatobiliopancreática y oncológica digestiva", "pregunta": "Respecto a la cirugía de resección del adenocarcinoma de cabeza de páncreas señale cuál es la técnica más empleada:", "opcion_a": "La duodenopancreatectomía cefálica con linfadenectomía regional.", "opcion_b": "La pancreaticoyeyunostomía, que consiste en la derivación del ducto pancreático al intestino.", "opcion_c": "La pancreatectomía corporo-caudal por laparoscopia.", "opcion_d": "La enucleación del tumor sin necesidad de linfadenectomía.", "correcta": "A", "explicacion": "La respuesta correcta es A) La duodenopancreatectomía cefálica con linfadenectomía regional: es la técnica estándar para tumores de cabeza de páncreas. Permite resección completa del tumor y de los ganglios regionales, y está respaldada por la evidencia oncológica. Descartamos B, porque la pancreaticoyeyunostomía no constituye una resección oncológica completa del tumor ni incluye linfadenectomía. Descartamos C, porque la pancreatectomía corporo-caudal no aborda la cabeza pancreática y la laparoscopia no es la práctica habitual para este tumor. Descartamos D, porque la enucleación no garantiza márgenes libres ni la eliminación de ganglios comprometidos.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 76, "especialidad": "Digestivo", "tema": null, "pregunta": "Mujer de 78 años con demencia e institucionalizada es traída por sus cuidadores por dolor abdominal importante con deterioro del estado general y distensión abdominal. Analítica con leucocitosis, hematocrito elevado, insuficiencia renal y acidosis metabólica. El ECG muestra fibrilación auricular. La tomografía abdominal detecta asas de intestino delgado edematizadas, con neumatosis intestinal y portal. El diagnóstico más probable es:", "opcion_a": "Perforación de ulcus gástrico o duodenal.", "opcion_b": "Íleo biliar.", "opcion_c": "Neoplasia obstructiva de sigma con perforación.", "opcion_d": "Isquemia mesentérica.", "correcta": "D", "explicacion": "La respuesta correcta es D) Isquemia mesentérica: la combinación de dolor abdominal intenso, deterioro general, leucocitosis, acidosis metabólica y hallazgos de neumatosis intestinal y gas portal en la tomografía sugiere necrosis de la pared intestinal por falta de perfusión, típica de isquemia mesentérica aguda. Descartamos A, porque la perforación de úlcera gástrica o duodenal produciría aire libre libre y no neumatosis intestinal. Descartamos B, porque el íleo biliar se asocia a obstrucción mecánica sin signos de necrosis ni neumatosis. Descartamos C, porque una neoplasia obstructiva del sigma con perforación presentaría signos de obstrucción distal y perforación localizada, no neumatosis intestinal ni afectación del intestino delgado.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 77, "especialidad": "Digestivo", "tema": "Enfermedades funcionales e infecciosas digestivas", "pregunta": "Mujer de 80 años que acude urgencias con dolor abdominal de inicio en epigastrio e irradiado posteriormente a fosa iliaca izquierda. Se acompaña de fiebre de 37,5°C. Se le realiza una TC abdominal, objetivando inflamación en las paredes del sigma y absceso mesentérico de 2 cm. El tratamiento de elección es:", "opcion_a": "Ingreso en planta con dieta absoluta y tratamiento antibiótico de amplio espectro.", "opcion_b": "Colostomía de descarga.", "opcion_c": "Drenaje mediante cirugía laparoscópica.", "opcion_d": "Cirugía urgente con sigmoidectomía y anastomosis colorrectal.", "correcta": "A", "explicacion": "La respuesta correcta es A) Ingreso en planta con dieta absoluta y tratamiento antibiótico de amplio espectro: la inflamación del sigma con un absceso mesentérico de 2 cm se considera una diverticulitis complicada de bajo riesgo que responde al manejo conservador con reposo intestinal y antibióticos de amplio espectro, evitando la morbilidad de una intervención quirúrgica inmediata; la ausencia de perforación libre ni peritonitis justifica esta estrategia. Descartamos B, porque una colostomía de descarga es excesiva para un absceso pequeño y sin perforación. Descartamos C, porque el drenaje laparoscópico se reserva a abscesos mayores o que no responden al tratamiento médico. Descartamos D, porque la resección urgente con anastomosis está indicada solo en presencia de perforación, peritonitis o absceso grande que no pueda controlarse conservadoramente.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 78, "especialidad": "Oncología", "tema": "Tumores digestivos", "pregunta": "Hombre de 52 años de edad derivado al servicio de digestivo por cuadro de hematoquezia, tenesmo y reducción del diámetro de las heces. Se realizan una serie de pruebas, diagnosticándose un adenocarcinoma de sigma sin metástasis a distancia. El paciente es intervenido quirúrgicamente y remitido a la consulta de oncología médica para valorar tratamiento quimioterápico complementario. ¿Cuál de los siguientes factores es de mal pronóstico tras la resección quirúrgica y habrá que tener en cuenta a la hora de planificar el tratamiento de quimioterapia?", "opcion_a": "La presencia de anemia al diagnóstico.", "opcion_b": "La existencia de antecedentes familiares de cáncer colorrectal.", "opcion_c": "El tamaño de la lesión primaria y la diferenciación histológica.", "opcion_d": "La perforación o adhesión del tumor a órganos adyacentes.", "correcta": "D", "explicacion": "La respuesta correcta es D) La perforación o adhesión del tumor a órganos adyacentes: este hallazgo indica invasión local avanzada y mayor riesgo de diseminación peritoneal. Se asocia a una supervivencia menor y a una mayor probabilidad de recurrencia local o sistémica. Por ello es considerado un factor de mal pronóstico que influye en la decisión de administrar quimioterapia adyuvante. Descartamos A, porque la anemia al diagnóstico es un marcador de presentación clínica pero no constituye un factor pronóstico independiente tras la resección. Descartamos B, porque los antecedentes familiares son un factor de riesgo para la aparición del cáncer pero no afectan al pronóstico después de la cirugía. Descartamos C, porque el tamaño de la lesión y la diferenciación histológica son relevantes, pero su peso pronóstico es inferior al de la perforación o adhesión a órganos adyacentes en este contexto.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 79, "especialidad": "Digestivo", "tema": "Enfermedad inflamatoria intestinal", "pregunta": "En la colitis ulcerosa, ¿qué factor NO incrementa el riesgo de neoplasia colorrectal?", "opcion_a": "El tiempo de evolución.", "opcion_b": "La afectación extensa de la enfermedad.", "opcion_c": "La coexistencia de cirrosis biliar primaria.", "opcion_d": "Los antecedentes familiares de cáncer colorrectal.", "correcta": "C", "explicacion": "La respuesta correcta es C) La coexistencia de cirrosis biliar primaria: esta condición no está relacionada con un aumento del riesgo de cáncer colorrectal en la colitis ulcerosa, a diferencia de la colangitis esclerosante primaria que sí lo es. Descartamos A, porque el tiempo de evolución prolongado incrementa la probabilidad de neoplasia. Descartamos B, porque la afectación extensa de la enfermedad es un factor de riesgo reconocido. Descartamos D, porque los antecedentes familiares de cáncer colorrectal aumentan la susceptibilidad.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 80, "especialidad": "Digestivo", "tema": "Patología esofágica", "pregunta": "Hombre de 56 años, fumador y bebedor, que presenta disfagia principalmente a sólidos, regurgitaciones y dolor retroesternal. Se le realiza endoscopia, encontrando tumoración de 3 cm estenosante en esófago distal. La biopsia es informada como adenocarcinoma. En la TC torácica se observa engrosamiento de 2 cm en esófago torácico sin metástasis a distancia. En la ecografía transesofágica se observa tumoración que invade la muscular, sin observar adenopatías mediastínicas. ¿Cuál es el tratamiento de elección?", "opcion_a": "Quimioradioterapia neoadyuvante y posteriormente esofaguectomía.", "opcion_b": "Radioterapia como tratamiento definitivo.", "opcion_c": "Colocación de prótesis de tipo stent.", "opcion_d": "Esofaguectomía y plastia gástrica con anastomosis cervical.", "correcta": "D", "explicacion": "La respuesta correcta es D) Esofaguectomía y plastia gástrica con anastomosis cervical: la lesión es un adenocarcinoma de esófago distal con invasión muscular pero sin metástasis ni adenopatías, por lo que el tratamiento curativo de elección es la resección quirúrgica con reconstrucción gástrica y anastomosis cervical. Descartamos A, porque la enfermedad está en estadio local sin necesidad de quimioradioterapia neoadyuvante previa; Descartamos B, porque la radioterapia sola no ofrece curación en tumores resecables; Descartamos C, porque el stent es paliativo y no curativo.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 81, "especialidad": "Digestivo", "tema": "Enfermedades funcionales e infecciosas digestivas", "pregunta": "Mujer de 39 años, diagnosticada de diabetes mellitus tipo 1 hace más de 20 años. Desde hace varios meses refiere presentar cuadros de náuseas, con algunos vómitos alimentarios y distensión abdominal. Ha perdido 6 Kg de peso. Gastroscopia: esófago normal, estómago con restos alimentarios y resto de la exploración hasta segunda porción duodenal sin alteraciones. ¿Qué prueba considera que es de mayor utilidad para su diagnóstico?", "opcion_a": "Ecografía de abdomen.", "opcion_b": "Manometría esofágica.", "opcion_c": "TC de abdomen.", "opcion_d": "Estudio isotópico de vaciamiento gástrico.", "correcta": "D", "explicacion": "La respuesta correcta es D) Estudio isotópico de vaciamiento gástrico: permite cuantificar el tiempo de vaciamiento del contenido gástrico y es la prueba de referencia para confirmar gastroparesia, sospechada por náuseas, vómitos alimentarios y pérdida de peso con restos alimentarios en la endoscopia. Descartamos A, porque la ecografía de abdomen solo visualiza estructuras anatómicas y no evalúa la motilidad gástrica. Descartamos B, porque la manometría esofágica estudia la función del esófago y no del estómago. Descartamos C, porque la tomografía computarizada detecta lesiones estructurales pero no mide el vaciamiento gástrico.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 82, "especialidad": "Digestivo", "tema": "Hemorragia digestiva", "pregunta": "Hombre de 35 años de edad sin antecedentes patológicos de interés que acude a urgencias por presentar un cuadro de inestabilidad tras un episodio de deposiciones negras como el alquitrán. En la sala de urgencias se objetiva hipotensión arterial que se recupera con fluidoterapia convencional. Hemoglobina al ingreso 8 g/dL, hematocrito 25 %. En los siguientes días continúa con episodios melénicos y descenso del hematocrito que necesitan la trasfusión de 3 concentrados de hematíes. Se practicó colonoscopia y endoscopia digestiva alta, no encontrando causa alguna de su cuadro hemorrágico. Tras una semana de ingreso hospitalario y la trasfusión de 4 unidades de concentrados de hematies continúa con melenas. El siguiente paso a seguir es:", "opcion_a": "Intervención quirúrgica inmediata.", "opcion_b": "Cápsula endoscópica.", "opcion_c": "Enteroscopia quirúrgica.", "opcion_d": "Continuar con tratamiento conservador y solicitar arteriografía.", "correcta": "B", "explicacion": "La respuesta correcta es B) Cápsula endoscópica: ante la ausencia de hallazgos en la endoscopia alta y colonoscopia y la persistencia de sangrado melénico, la sospecha recae en una lesión del intestino delgado que se visualiza mejor con la cápsula endoscópica, método no invasivo y de alta sensibilidad. Descartamos A, porque no existe una fuente identificada que justifique una cirugía de urgencia. Descartamos C, porque la enteroscopia quirúrgica es más invasiva y se reserva para casos en los que otras técnicas no han localizado la lesión. Descartamos D, porque la arteriografía es menos sensible para sangrados de bajo flujo y se emplea después de que la cápsula haya orientado el sitio de la hemorragia.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 83, "especialidad": "Ginecología", "tema": "Patología obstétrica y complicaciones del embarazo — sangrado en gestante, prematuridad, crecimiento fetal", "pregunta": "Mujer de 30 años de edad, embarazada de 33 semanas, que consulta por prurito de una semana de evolución. Las pruebas hepáticas muestran un leve incremento en los valores de transaminasas (AST 77 UI/L y ALT 84 UI/L), así como de fosfatasa alcalina (155 UI/L) y gammaglutamil-transpeptidasa (125 UI/L), con una cifra de bilirrubina total de 2,3 mg/dL. El hemograma y el estudio de coagulación son normales, la ecografía abdominal no muestra alteraciones hepáticas ni biliares y la serología de virus de hepatitis, así como los autoanticuerpos son negativos. ¿Cuál de las siguientes actitudes es la correcta?", "opcion_a": "Realizar una biopsia hepática para establecer el diagnóstico de la enfermedad hepática.", "opcion_b": "Tratar a la paciente con ácido ursodesoxicólico, ya que probablemente se trata de una colestasis intrahepática benigna del embarazo.", "opcion_c": "Interrumpir el embarazo ya que el diagnóstico más probable es el hígado graso agudo del embarazo.", "opcion_d": "Realizar una resonancia magnética para descartar una colangitis esclerosante primaria.", "correcta": "B", "explicacion": "La respuesta correcta es B) Tratar a la paciente con ácido ursodesoxicólico, ya que probablemente se trata de una colestasis intrahepática benigna del embarazo: la combinación de prurito, elevación moderada de transaminasas, fosfatasa alcalina, GGT y bilirrubina con estudios de imagen y serología normales es típica de la colestasis del embarazo, y el ácido ursodesoxicólico alivia el prurito y reduce el riesgo de complicaciones fetales. Descartamos A, porque la biopsia hepática no es necesaria en un cuadro clínico típico y puede ser riesgosa durante el embarazo. Descartamos C, porque el hígado graso agudo del embarazo se asocia a insuficiencia hepática grave, coagulopatía y alteraciones ecográficas que no se observan. Descartamos D, porque la colangitis esclerosante primaria es poco frecuente, presenta anticuerpos específicos y alteraciones radiológicas que no se encuentran.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 84, "especialidad": "Digestivo", "tema": "Hepatopatías y cirrosis", "pregunta": "Un hombre de 67 años con cirrosis alcohólica en seguimiento por el servicio de hepatología es diagnosticado de un hepatocarcinoma de 3 cm de diámetro localizado en el lóbulo izquierdo, segmento 3. Sometido a estudio para valoración del tratamiento a seguir se demuestra que el paciente no tiene hipertensión portal, presenta una función hepática normal un MELD score de 7 y un Child-Pugh grado A. La alfa-fetoproteína es inferior a 50 ng/mL y no se han objetivado metástasis a distancia. ¿Cuál es el tratamiento más indicado en este paciente?", "opcion_a": "Aplicar inyección de etanol percutánea.", "opcion_b": "Resección hepática.", "opcion_c": "Trasplante hepático.", "opcion_d": "Quimioembolización transarterial.", "correcta": "B", "explicacion": "La respuesta correcta es B) Resección hepática: el paciente presenta un hepatocarcinoma solitario de 3 cm, función hepática preservada (Child‑Pugh A, MELD 7) y ausencia de hipertensión portal, criterios que favorecen la resección quirúrgica como tratamiento curativo de primera línea. Descartamos A, porque la ablación percutánea con etanol se indica en tumores muy pequeños o en pacientes que no pueden someterse a cirugía y no es la mejor opción en un tumor de 3 cm con buen reserve hepático. Descartamos C, porque el trasplante hepático se reserva a pacientes con cirrosis descompensada o tumores fuera de los criterios de Milan, lo que no se cumple en este caso. Descartamos D, porque la quimioembolización transarterial se emplea en enfermedad intermedia o tumores no resecables, y aquí la resección es factible y curativa.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 85, "especialidad": "Digestivo", "tema": "Enfermedad inflamatoria intestinal", "pregunta": "Joven de 24 años que presenta anemia ferropénica crónica de origen no filiado, con ileocolonoscopia y esofagogastroduodenoscopia sin lesiones. Se realiza estudio con cápsula endoscópica observando úlceras aisladas a nivel de yeyuno distal. ¿En cuál de las siguientes enfermedades se encuentran estas lesiones?", "opcion_a": "Enfermedad de Whipple.", "opcion_b": "Neumatosis quística intestinal.", "opcion_c": "Esprúe celíaco refractario.", "opcion_d": "Enteritis eosinofílica.", "correcta": "C", "explicacion": "La respuesta correcta es C) Esprúe celíaco refractario: la presencia de anemia ferropénica crónica, ileocolonoscopia y gastroscopia sin hallazgos y la detección de úlceras aisladas en yeyuno distal son típicos de la forma ulcerativa del esprúe celíaco refractario, que puede presentar lesiones ulcerativas en el intestino delgado pese a una mucosa aparentemente normal en estudios convencionales. Descartamos A, porque la enfermedad de Whipple se caracteriza por infiltración de macrófagos PAS‑positivos y no por úlceras aisladas en el yeyuno. Descartamos B, porque la neumatosis quística intestinal muestra cavidades gaseosas en la pared intestinal y no úlceras. Descartamos D, porque la enteritis eosinofílica se asocia a infiltración eosinofílica y síntomas alérgicos, no a úlceras aisladas en el yeyuno.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 86, "especialidad": "Digestivo", "tema": "Enfermedades funcionales e infecciosas digestivas", "pregunta": "En el síndrome de colon irritable, es cierto que:", "opcion_a": "Los estudios rutinarios de laboratorio (análisis) muestran anomalías específicas de este síndrome.", "opcion_b": "Dentro de los síntomas que nos hacen pensar en un colon irritable se encuentran: dolor abdominal nocturno, dolor progresivo y pérdida de peso.", "opcion_c": "Cursa con diarrea o estreñimiento; si se manifiestan ambos, queda descartada esta entidad.", "opcion_d": "En pacientes con colon irritable con predominio de diarrea, el estudio diagnóstico debe incluir: cultivo de heces, cribado de enfermedad celiaca, colonoscopia con biopsias.", "correcta": "D", "explicacion": "La respuesta correcta es D) En pacientes con colon irritable con predominio de diarrea, el estudio diagnóstico debe incluir: cultivo de heces, cribado de enfermedad celiaca, colonoscopia con biopsias: se trata de una estrategia de exclusión para descartar infecciones, enfermedad celíaca y patologías inflamatorias o neoplásicas que pueden simular la diarrea crónica; los hallazgos de estos estudios permiten confirmar que no hay causa orgánica subyacente y, por tanto, se puede mantener el diagnóstico de síndrome de colon irritable; por ello las guías recomiendan este abordaje antes de aceptar el diagnóstico de forma definitiva. Descartamos A, porque los análisis de laboratorio rutinarios no presentan anomalías específicas del síndrome. Descartamos B, porque el dolor nocturno, progresivo y la pérdida de peso son signos de alarma que sugieren enfermedad orgánica y no forman parte del cuadro típico de colon irritable. Descartamos C, porque la coexistencia de diarrea y estreñimiento corresponde al subtipo mixto del síndrome y no excluye la entidad.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 87, "especialidad": "Digestivo", "tema": "Patología biliopancreática", "pregunta": "¿Qué afirmación sobre el cáncer de páncreas es correcta?", "opcion_a": "Los factores de riesgo implicados en esta neoplasia incluyen tabaquismo, obesidad y pancreatitis aguda.", "opcion_b": "La prueba diagnóstica de imagen más adecuada es la TC helicoidal sin contraste y doble fase.", "opcion_c": "Es necesaria la confirmación diagnóstica anatomopatológica preoperatoria antes de realizar el tratamiento quirúrgico con finalidad curativa.", "opcion_d": "La alteración genética detectada con más frecuencia es la delección del gen p16.", "correcta": "D", "explicacion": "La respuesta correcta es D) La alteración genética detectada con más frecuencia es la delección del gen p16: esta alteración se observa en la mayoría de los tumores pancreáticos y está implicada en la vía de regulación del ciclo celular, lo que favorece la carcinogénesis. Descartamos A, porque la pancreatitis aguda no está incluida entre los factores de riesgo típicos de este cáncer. Descartamos B, porque la prueba de imagen de elección es la tomografía computarizada helicoidal con contraste y fase portal, no sin contraste ni doble fase. Descartamos C, porque el diagnóstico se confirma habitualmente después de la resección, la cirugía curativa no requiere siempre confirmación anatómica previa.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 88, "especialidad": "Endocrinología", "tema": "Hipófisis y eje hipotálamo-hipofisario", "pregunta": "¿Cuál es el tratamiento de elección de un hombre de 38 años diagnosticado de enfermedad de Cushing en relación con un macroadenoma hipofisario de 22 mm de diámetro?", "opcion_a": "Probar inicialmente tratamiento médico y, en caso de no ser efectivo, recurrir a cirugía.", "opcion_b": "Adrenalectomía.", "opcion_c": "Resección quirúrgica selectiva del adenoma.", "opcion_d": "Radioterapia para intentar disminuir el tamaño tumoral.", "correcta": "C", "explicacion": "La respuesta correcta es C) Resección quirúrgica selectiva del adenoma: la enfermedad de Cushing de origen hipofisario se trata de forma preferente con extirpación del adenoma, lo que permite la curación y la normalización hormonal. El tamaño del macroadenoma lo hace accesible a la cirugía transesfenoidal, evitando la necesidad de tratamientos médicos o radioterápicos. Descartamos A, porque el tratamiento médico de primera línea no garantiza la eliminación del tumor ni la curación definitiva. Descartamos B, porque la adrenalectomía es una opción de segunda línea reservada cuando la cirugía pituitaria no es viable. Descartamos D, porque la radioterapia se reserva para casos de recidiva o cuando la resección quirúrgica no es completa.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 89, "especialidad": "Endocrinología", "tema": "Diabetes mellitus", "pregunta": "Una mujer de 55 años, diabética tipo 2 y obesa, en tratamiento con metformina, con Hb A1c de 8%, cuenta historia de infecciones urinarias de repetición. ¿Cuál de las siguientes opciones terapéuticas para asociar a la metformina considera la MENOS adecuada?", "opcion_a": "Inhibidores DPP4.", "opcion_b": "Análogos GLP1.", "opcion_c": "Insulina basal.", "opcion_d": "Inhibidores SGLT2.", "correcta": "D", "explicacion": "La respuesta correcta es D) Inhibidores SGLT2: los inhibidores SGLT2 aumentan la glucosuria, lo que favorece la aparición de infecciones del tracto urinario y genital, riesgo que ya está presente en esta paciente con historial de infecciones urinarias recurrentes. Además, su efecto diurético puede empeorar la deshidratación y no aporta ventajas adicionales frente a otras opciones en este caso. Descartamos A, porque los inhibidores DPP4 tienen bajo riesgo de infecciones urinarias y son bien tolerados. Descartamos B, porque los análogos GLP1 mejoran el control glucémico y favorecen la pérdida de peso sin incrementar el riesgo de infecciones urinarias. Descartamos C, porque la insulina basal permite un control preciso de la glucemia y no está asociada a un mayor riesgo de infecciones del tracto urinario.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 90, "especialidad": "Digestivo", "tema": "Hepatopatías y cirrosis", "pregunta": "¿Cuál de los siguientes fármacos se ha demostrado eficaz en la reducción de la fibrosis en paciente con esteatohepatitis no alcohólica?", "opcion_a": "Pioglitazona.", "opcion_b": "Pentoxifilina.", "opcion_c": "Ácido ursodesoxicólico.", "opcion_d": "Fenofibrato.", "correcta": "A", "explicacion": "La respuesta correcta es A) Pioglitazona: es un agonista de los receptores ppar‑γ que mejora la sensibilidad a la insulina y ha demostrado reducir la actividad inflamatoria y la fibrosis en estudios de nash. Además, los ensayos clínicos han mostrado una disminución significativa de los marcadores de fibrosis hepática en pacientes tratados con este fármaco. Descartamos B, porque la pentoxifilina no ha demostrado eficacia consistente en la fibrosis de la esteatohepatitis. Descartamos C, porque el ácido ursodesoxicólico se utiliza principalmente en colangitis biliar primaria y no tiene evidencia robusta en la reducción de fibrosis en nash. Descartamos D, porque el fenofibrato actúa sobre el metabolismo de los lípidos pero no ha mostrado beneficio claro sobre la fibrosis hepática.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 91, "especialidad": "Endocrinología", "tema": "Hipófisis y eje hipotálamo-hipofisario", "pregunta": "Una mujer de 27 años de edad consulta por presentar amenorrea secundaria de un año de evolución. No refiere antecedentes yatrogénicos. Analíticamente, la concentración de estradiol es inferior a la normalidad y el valor de prolactina es de 12 ng/mL. Indique cuál de las exploraciones que se citan a continuación solicitaría como primera medida para tratar de filiar el origen del trastorno:", "opcion_a": "Resonancia magnética hipotálamohipofisaria.", "opcion_b": "Cariotipo.", "opcion_c": "FSH basal.", "opcion_d": "Estimulación con gonadotropina coriónica.", "correcta": "C", "explicacion": "La respuesta correcta es C) FSH basal: la medida inicial permite determinar si la amenorrea es de origen hipogonadotrópico o hipergonadotrópico, orientando el diagnóstico y los estudios posteriores. Un FSH bajo sugiere insuficiencia hipotalámica o hipofisaria, mientras que un FSH elevado indica falla ovárica primaria. Descartamos A, porque la resonancia magnética se reserva para casos con sospecha de lesión estructural tras hallazgos hormonales anormales. Descartamos B, porque el cariotipo no está indicado en la evaluación inicial de una amenorrea sin indicios de alteraciones cromosómicas. Descartamos D, porque la estimulación con gonadotropina coriónica se utiliza para evaluar la reserva ovárica y no para el diagnóstico etiológico inicial.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 92, "especialidad": "Endocrinología", "tema": "Hipófisis y eje hipotálamo-hipofisario", "pregunta": "Mujer de 34 años que ingresa para estudio de poliuria y polidipsia. En las primeras 24 horas de ingreso se constata una diuresis de 8,2 litros y se obtiene una analítica que muestra una glicemia de 96 mg/dL, natremia de 148 mEq/L y osmolalidad plasmática de 309 mOsm/kg con osmolalidad urinaria de 89 mOsm/kg. ¿Qué prueba diagnóstica debe realizarse a continuación?", "opcion_a": "Test de infusión de suero salino hipertónico para determinación seriada de hormona antidiurética.", "opcion_b": "Test de deshidratación (test de Miller).", "opcion_c": "Administración de desmopresina con control seriado de osmolalidad en orina.", "opcion_d": "Determinación de hormona antidiurética en plasma.", "correcta": "C", "explicacion": "La respuesta correcta es C) Administración de desmopresina con control seriado de osmolalidad en orina: la combinación de poliuria, hipernatremia y orina muy diluida sugiere diabetes insípida y la prueba de desmopresina permite confirmar la enfermedad y diferenciar la forma central de la nefrogénica. Descartamos A, porque la infusión de suero salino hipertónico y la medición seriada de ADH no es la prueba de elección inicial para el diagnóstico de DI. Descartamos B, porque el test de deshidratación (Miller) es más complejo, con mayor riesgo y no es necesario cuando la prueba de desmopresina está disponible. Descartamos D, porque la determinación directa de ADH en plasma es poco fiable y no se utiliza rutinariamente para el diagnóstico de DI.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 93, "especialidad": "Nefrología", "tema": "Enfermedades renales hereditarias", "pregunta": "Joven de 24 años de edad, estudiante de matemáticas, que acude a la consulta para confirmar la sospecha diagnóstica después de realizar una consulta en Google. Desde la infancia tiene episodios de dolor intenso, lancinante, en manos y pies, de duración entre minutos y días. Los relaciona con el ejercicio físico, el estrés o la fiebre, y fue diagnosticado de \"dolores del crecimiento\". Posteriormente nota que no tiene sudoración después de hacer deporte. Además ha observado lesiones cutáneas puntiformes, de color rojo oscuro, en \"la zona del traje de baño\", consideradas inespecíficas. Consigue el diagnóstico después de reunir tres claves (neuropatía dolorosa, hipohidrosis y angioqueratomas). ¿Cuál cree Vd. que es el diagnóstico?", "opcion_a": "Enfermedad de Fabry.", "opcion_b": "Enfermedad de Pompe.", "opcion_c": "Polineuropatía amiloidótica hereditaria.", "opcion_d": "Enfermedad de Gaucher.", "correcta": "A", "explicacion": "La respuesta correcta es A) Enfermedad de Fabry: la combinación de neuropatía dolorosa en manos y pies, hipohidrosis y angiokeratomas es típica de esta enfermedad lisosomal, y el cuadro clínico descrito coincide con ella. Estos hallazgos permiten sospechar firmemente la enfermedad de Fabry. Descartamos B, porque la enfermedad de Pompe se caracteriza por debilidad muscular y cardiomiopatía, no por dolor neuropático ni angiokeratomas. Descartamos C, porque la polineuropatía amiloidótica hereditaria presenta neuropatía sensitiva y cardiaca, pero carece de hipohidrosis y lesiones cutáneas. Descartamos D, porque la enfermedad de Gaucher se manifiesta con hepatoesplenomegalia, anemia y huesos frágiles, sin los hallazgos cutáneos ni la anhidrosis.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 94, "especialidad": "Neurología", "tema": "Enfermedad cerebrovascular", "pregunta": "Un paciente de 73 años presenta en el test de deglución una disfagia neurológica completa, secundaria a un ictus cadioembólico en el territorio de la arteria cerebral media izquierda. Va a precisar apoyo nutricional a largo plazo. De las siguientes modalidades de tratamiento, ¿cuál considera más indicada para este caso?", "opcion_a": "Nutrición enteral por sonda nasogástrica.", "opcion_b": "Nutrición enteral por sonda nasoduodenal.", "opcion_c": "Nutrición enteral por gastrostomía.", "opcion_d": "Nutrición enteral por yeyunostomía.", "correcta": "C", "explicacion": "La respuesta correcta es C) Nutrición enteral por gastrostomía: en pacientes con disfagia neurológica completa y necesidad de soporte nutricional prolongado, la gastrostomía permite una alimentación segura, cómoda y con menor riesgo de aspiración que las sondas nasales, además de ser más tolerable a largo plazo. Esta vía evita la irritación de la mucosa nasal y reduce las complicaciones asociadas a la permanencia de la sonda. Descartamos A, porque la sonda nasogástrica está indicada solo para uso temporal y presenta alto riesgo de aspiración y de desplazamiento. Descartamos B, porque la sonda nasoduodenal tampoco es adecuada para nutrición crónica y comparte los inconvenientes de las sondas nasales. Descartamos D, porque la yeyunostomía es una opción menos habitual y más invasiva que la gastrostomía para este tipo de pacientes.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 95, "especialidad": "Endocrinología", "tema": "Metabolismo del calcio y patología paratiroidea", "pregunta": "Mujer de 45 años de edad que acude al servicio de urgencias por cuadro confusional que se acompaña de disfonía. A la exploración presenta masa palpable en el cuello y en el análisis de sangre cifras de calcio plasmático de 15 mg/dL (normal hasta 10,2 mg/dL). Ante estos hallazgos, ¿cuál de los siguiente diagnósticos debe sospecharse?", "opcion_a": "Carcinoma paratiroideo.", "opcion_b": "Carcinoma medular de tiroides.", "opcion_c": "MEN tipo I.", "opcion_d": "Adenoma de paratiroides.", "correcta": "A", "explicacion": "La respuesta correcta es A) Carcinoma paratiroideo: la combinación de hipercalcemia severa, masa palpable en el cuello y disfonía sugiere un tumor paratiroideo maligno que produce niveles de calcio muy elevados y puede comprimir el nervio laríngeo. Descartamos B, porque el carcinoma medular de tiroides no produce hipercalcemia tan marcada ni suele presentar masa palpable de paratiroides. Descartamos C, porque el MEN tipo I se asocia con adenomas paratiroideos y no con carcinoma ni con masas palpables tan evidentes. Descartamos D, porque el adenoma de paratiroides típicamente genera hipercalcemia moderada y rara vez se palpa como una masa cervical.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 96, "especialidad": "Ginecología", "tema": "Menopausia, climaterio y sangrado posmenopáusico", "pregunta": "Mujer de 64 años. Menopausia a los 54 años. Dos embarazos y partos eutócicos. No toma ninguna medicación. Acude al servicio de urgencias referiendo sangrado vaginal de dos días de duración con molestias en hipogastrio. La exploración clínica realizada por el ginecólogo no objetiva lesiones en genitales externos, vagina ni cérvix. El tacto vaginal no es concluyente. ¿Cuál de las siguientes conductas le parece más adecuada como primera aproximación diagnóstica?", "opcion_a": "Ecografía transvaginal y medición del espesor endometrial. En función de éste tomar biopsia endometrial o no.", "opcion_b": "Biopsia endometrial por aspiración en consulta. Con ella puedo obtener el diagnóstico muy fiablemente y es económica.", "opcion_c": "Histeroscopia con sedación y biopsia dirigida si se ve alguna lesión.", "opcion_d": "Realizaría un microlegrado, ya que es la prueba que me proporcionaría el diagnóstico definitivo.", "correcta": "A", "explicacion": "La respuesta correcta es A) Ecografía transvaginal y medición del espesor endometrial. En función de éste tomar biopsia endometrial o no: La ecografía permite valorar de forma no invasiva el grosor endometrial y descartar hiperplasia o carcinoma antes de realizar una biopsia, y es la estrategia recomendada en sangrado postmenopáusico. Descartamos B, porque la biopsia por aspiración sin previa valoración ecográfica puede fallar en casos de atrofia o insuficiente tejido. Descartamos C, porque la histeroscopia con sedación es más invasiva y se reserva cuando la ecografía sugiere una lesión focal. Descartamos D, porque el microlegrado es una prueba quirúrgica que se utiliza después de una valoración inicial y no es la primera opción diagnóstica.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 97, "especialidad": "Ginecología", "tema": null, "pregunta": "Mujer de 24 años consulta por dolor abdominal bajo de dos semanas de evolución que ha empeorado con la última relación sexual. Refiere tener pareja reciente con la que sólo ocasionalmente utiliza preservativo. A la exploración presenta regular estado general. Tª de 38,6°C, leucocitos 16.000/µL (85% neutrófilos); PCR 30 mg/L. La exploración con espéculo evidencia flujo vaginal anormal abundante y movilización cervical dolorosa. Indique la respuesta FALSA:", "opcion_a": "Iniciaríamos tratamiento antibiótico tan pronto como sospechemos el diagnóstico.", "opcion_b": "Indicaríamos como prueba complementaria preferente una histerosalpingografía para valoración tubárica.", "opcion_c": "El retraso en el diagnóstico y tratamiento aumenta la aparición de secuelas.", "opcion_d": "La presencia de absceso sería criterio de hospitalización.", "correcta": "B", "explicacion": "La respuesta correcta es B) Indicaríamos como prueba complementaria preferente una histerosalpingografía para valoración tubárica: en el contexto de enfermedad inflamatoria pélvica aguda la histerosalpingografía no es la prueba de elección, pues requiere radiación y contraste y se reserva para la evaluación de la permeabilidad tubárica después del tratamiento; la prueba de primera línea es la ecografía transvaginal o la PCR de Chlamydia. Descartamos A, porque el manejo de la enfermedad inflamatoria pélvica incluye iniciar antibiótico tan pronto como se sospecha para evitar complicaciones. Descartamos C, porque el retraso en el diagnóstico y tratamiento está asociado a mayor riesgo de infertilidad, dolor crónico y abscesos. Descartamos D, porque la presencia de un absceso tubo-ovárico es una indicación clara de hospitalización para drenaje y terapia intravenosa.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 98, "especialidad": "Ginecología", "tema": "Amenorrea, fallo ovárico y trastornos del eje hipotálamo-hipófisis-ovario", "pregunta": "Mujer de 21 años de edad que acude a consulta aportando un estudio hormonal con FSH 0,29 mUI/mL (normal en fase folicular = 3,50-12,50 mUI/mL) y LH < 0,1 mUI/mL (normal en fase folicular 2,40-12,60 mUI/mL). Deberemos realizar un diagnóstico diferencial entre las siguiente situaciones clínicas EXCEPTO:", "opcion_a": "Admisnistración de anticonceptivos orales combinados.", "opcion_b": "Fallo ovárico prematuro.", "opcion_c": "Trastorno del comportamiento alimentario.", "opcion_d": "Craneofaringioma.", "correcta": "B", "explicacion": "La respuesta correcta es B) Fallo ovárico prematuro: los niveles de FSH y LH están muy por debajo de los valores esperados en la fase folicular, lo que indica una supresión del eje hipófalo-hipofisario y no una insuficiencia ovárica, cuya característica es elevación de estas gonadotropinas. Descartamos A, porque los anticonceptivos orales combinados suprimen la secreción de FSH y LH produciendo valores bajos. Descartamos C, porque los trastornos del comportamiento alimentario pueden generar un estado de inanición que reduce la liberación de GnRH y, consecuentemente, disminuye FSH y LH. Descartamos D, porque un craneofaringioma puede comprimir la hipófisis o el hipotálamo y provocar una disminución de la secreción de gonadotropinas, generando niveles bajos de FSH y LH.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 99, "especialidad": "Miscelánea", "tema": "Geriatría y polifarmacia — envejecimiento, criterios STOPP-START, anticolinérgicos, incontinencia, marcha, cuidados paliativos en mayores", "pregunta": "Respecto a la incontinencia de orina señale la respuesta FALSA:", "opcion_a": "En la incontinencia urinaria de esfuerzo, un factor precipitante es el ejercicio físico.", "opcion_b": "En la incontinencia de urgencia la frecuencia miccional es normal.", "opcion_c": "La prueba más fiable para establecer un diagnóstico exacto del tipo de incontinencia es el estudio urodinámico.", "opcion_d": "En el tratamiento de la incontinencia de orina de urgencia se utilizan medicamentos anticolinérgicos.", "correcta": "B", "explicacion": "La respuesta correcta es B) En la incontinencia de urgencia la frecuencia miccional es normal: esta afirmación es falsa porque la incontinencia de urgencia se acompaña típicamente de una frecuencia urinaria aumentada y nocturia. Los pacientes suelen presentar urgencia y necesidad de vaciar la vejiga con mayor frecuencia. Descartamos A, porque el esfuerzo físico y el aumento de la presión intraabdominal son desencadenantes clásicos de la incontinencia de esfuerzo. Descartamos C, porque el estudio urodinámico es la prueba de referencia para diferenciar los tipos de incontinencia con precisión. Descartamos D, porque los fármacos anticolinérgicos son el tratamiento de primera línea en la incontinencia de urgencia.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 100, "especialidad": "Ginecología", "tema": "Oncología ginecológica — cérvix, ovario, endometrio", "pregunta": "Mujer de 34 años de edad que consulta por coitorragias de repetición. Aporta una citología con una lesión intraepitelial de alto grado (H-SIL). Posteriormente se realiza colposcopia y biopsia sobre una zona de mosaico y la histología nos habla de un foco de carcinoma escamoso invasor de 2 mm de longitud. ¿Qué opción terapéutica es la más adecuada para esta paciente?", "opcion_a": "Conización.", "opcion_b": "Histerectomía total sin anexectomía.", "opcion_c": "Radioterapia pélvica con intención curativa.", "opcion_d": "Repetir una biopsia más amplia.", "correcta": "A", "explicacion": "La respuesta correcta es A) Conización: la lesión intraepitelial de alto grado con microinvasión de 2 mm se puede tratar con una conización que permite extirpar el foco invasivo y preservar la fertilidad. Además, la conización brinda diagnóstico definitivo y margen libre. Descartamos B, porque la histerectomía total sin anexectomía sería un tratamiento excesivo y comprometería la fertilidad en una paciente joven. Descartamos C, porque la radioterapia pélvica se reserva para enfermedad más avanzada o cuando la cirugía no es posible. Descartamos D, porque una biopsia más amplia no elimina el carcinoma invasor y retrasaría el tratamiento definitivo.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 101, "especialidad": "Oncología", "tema": "Cáncer de mama", "pregunta": "¿Qué características anatomopatológicas presentan, en la mayor parte de los casos, los tumores incluidos en el subtipo molecular de cáncer de mama denominado \"basal-like\"?", "opcion_a": "Positividad elevada para receptores hormonales, negatividad para HER2 y baja expresión de Ki67.", "opcion_b": "Positividad elevada para receptores hormonales, negatividad para HER2 y alta expresión de Ki67.", "opcion_c": "Ausencia de expresión de receptores hormonales y negatividad para HER2.", "opcion_d": "Ausencia de expresión de receptores hormonales y presencia de HER2 positivo (sobreexpresado o amplificado).", "correcta": "C", "explicacion": "La respuesta correcta es C) Ausencia de expresión de receptores hormonales y negatividad para HER2: los tumores basal‑like carecen de receptores de estrógeno y progesterona y no sobreexpresan HER2, mostrando un perfil triple negativo que se asocia a una biología agresiva y alta proliferación. Este patrón define el subtipo basal‑like. Descartamos A, porque esa opción describe tumores hormonales positivos y bajo Ki67, lo que no corresponde al basal‑like. Descartamos B, porque aunque menciona alta Ki67, mantiene receptores hormonales positivos, lo cual es incorrecto. Descartamos D, porque incluye HER2 positivo, mientras que los basal‑like son HER2 negativo.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 102, "especialidad": "Oncología", "tema": "Cáncer de mama", "pregunta": "Mujer de 64 años, sin comorbilidades relevantes, intervenida de un cáncer de mama derecha mediante una tumorectomía ampliada y biopsia selectiva del ganglio centinela, con el siguiente resultado anatomopatológico: carcinoma ductal infiltrante pobremente diferenciado (grado 3), tamaño de 2,2 cm (pT2), receptores de estrógenos y progesterona positivos, Ki67 25%, HER2 negativo. Presenta afectación macroscópica del ganglio centinela, aunque no hay afectación del resto de ganglios axilares aislados (pN1). ¿Qué tratamiento sistémico adyuvante considera más adecuado para esta paciente?", "opcion_a": "Hormonoterapia adyuvante que incluya inhibidores de aromatasa.", "opcion_b": "Quimioterapia adyuvante, preferentemente con antraciclinas y taxanos, seguida de hormonoterapia.", "opcion_c": "Quimioterapia adyuvante en asociación con el anticuerpo monoclonal trastuzumab, seguida de hormonoterapia.", "opcion_d": "Quimioterapia adyuvante, preferiblemente con antraciclinas y taxanos.", "correcta": "B", "explicacion": "La respuesta correcta es B) Quimioterapia adyuvante, preferentemente con antraciclinas y taxanos, seguida de hormonoterapia: El tumor es de grado 3, de 2,2 cm y con afectación del ganglio centinela, lo que confiere un riesgo de recurrencia que justifica la quimioterapia. La ausencia de HER2 elimina la necesidad de trastuzumab y la positividad hormonal indica que la hormonoterapia es necesaria después de la quimioterapia. Descartamos A, porque la hormonoterapia sola no cubre el riesgo elevado asociado a la alta gradación y al compromiso ganglionar. Descartamos C, porque el trastuzumab solo se indica en tumores HER2 positivos. Descartamos D, porque la combinación con hormonoterapia es esencial dado el estatus hormonal positivo.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 103, "especialidad": "Ginecología", "tema": "Vía del parto y trabajo de parto — presentación, criterios de elección", "pregunta": "¿Cuál de los siguientes NO es un movimiento en el mecanismo de parto de cabeza?", "opcion_a": "Retroflexión.", "opcion_b": "Flexión.", "opcion_c": "Desprendimiento.", "opcion_d": "Rotación intrapélvica.", "correcta": "A", "explicacion": "La respuesta correcta es A) Retroflexión: la retroflexión no constituye uno de los movimientos fisiológicos del mecanismo de parto de cabeza, que se compone de flexión, descenso, rotación interna, extensión y expulsión. Por tanto, no se incluye en la descripción clásica del proceso. Descartamos B, porque la flexión es el primer movimiento que permite que la cabeza se doble y facilite el paso por el canal. Descartamos C, porque el desprendimiento o expulsión de la cabeza es la fase final del mecanismo de parto. Descartamos D, porque la rotación intrapélvica (rotación interna) es necesaria para alinear el diámetro biparietal con el diámetro anteroposterior del canal.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 104, "especialidad": "Ginecología", "tema": "Patología obstétrica y complicaciones del embarazo — sangrado en gestante, prematuridad, crecimiento fetal", "pregunta": "Mujer de 36 años que acude a la consulta por haber sufrido tres abortos espontáneos en el primer trimestre. No ha tenido ningún embarazo a término. Entre los estudios que solicitará en primer término, NO se incluye:", "opcion_a": "Histerosalpingografía.", "opcion_b": "Cariotipo en sangre periférica de ambos miembros de la pareja.", "opcion_c": "Determinación de anticuerpos antifosfolípidos.", "opcion_d": "Ecografía vaginal.", "correcta": "A", "explicacion": "La respuesta correcta es A) Histerosalpingografía: no se incluye entre los estudios de primer nivel para abortos recurrentes porque la evaluación de la permeabilidad tubárica no es prioritaria en este contexto y existen métodos más adecuados para valorar la cavidad uterina. Descartamos B, porque el cariotipo en sangre periférica de ambos miembros de la pareja es fundamental para detectar anomalías cromosómicas que pueden explicar los abortos. Descartamos C, porque la determinación de anticuerpos antifosfolípidos es necesaria para descartar el síndrome antifosfolípido, una causa frecuente de pérdida gestacional temprana. Descartamos D, porque la ecografía vaginal permite valorar la morfología y la integridad del útero, detectando posibles malformaciones que contribuyan a los abortos.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 105, "especialidad": "Ginecología", "tema": "Patología obstétrica y complicaciones del embarazo — sangrado en gestante, prematuridad, crecimiento fetal", "pregunta": "¿Cuál de las siguientes es la secuencia de medidas CORRECTA ante una hemorragia postparto?", "opcion_a": "Masaje uterino, colocación de sonda vesical, reposición de la volemia, administración de uterotónicos y revisión del canal del parto.", "opcion_b": "Masaje uterino, colocación de sonda vesical, reposición de la volemia, administración de uterotónicos y ecografía transvaginal.", "opcion_c": "Masaje uterino, colocación de sonda vesical, reposición de la volemia, administración de uterotónicos y taponamiento uterino.", "opcion_d": "Masaje uterino, colocación de sonda vesical, reposición de la volemia, administración de uterotónicos y ligadura de arterias uterinas.", "correcta": "A", "explicacion": "La respuesta correcta es A) Masaje uterino, colocación de sonda vesical, reposición de la volemia, administración de uterotónicos y revisión del canal del parto: el masaje uterino permite la contracción inmediata del útero, la sonda vesical vacía la vejiga que puede impedir la compresión uterina, la reposición de la volemia estabiliza la hemodinámica y los uterotónicos refuerzan la contracción, y la revisión del canal del parto detecta restos placentarios o laceraciones que pueden mantener el sangrado. Descartamos B, porque la ecografía transvaginal no forma parte de las medidas inmediatas de control del sangrado. Descartamos C, porque el taponamiento uterino se reserva para casos en que los uterotónicos no logran la hemostasia. Descartamos D, porque la ligadura de arterias uterinas es una intervención quirúrgica de último recurso y no se incluye en la secuencia inicial.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 106, "especialidad": "Hematología", "tema": "Anemias", "pregunta": "Mujer de 40 años que consulta por anemia. En la analítica destaca Hb 10,5 g/dL, ferropenia, macrocitosis e hipergastrinemia. Tiene antecedentes artropatía lúpica y enfermedad de Graves Basedow. Está en tratamiento con prednisona 15 mg/d, colchicina 0,5 mg cada 12 h y metimazol 10 mg/d. ¿Cuál considera la causa más probable de la anemia?", "opcion_a": "Pérdidas hemáticas en relación con el tratamiento esteroideo.", "opcion_b": "Hipoplasia medular 2º a colchicina.", "opcion_c": "Hemólisis secundaria a la toma de metimazol.", "opcion_d": "Gastritis tipo A.", "correcta": "D", "explicacion": "La respuesta correcta es D) Gastritis tipo A: la combinación de anemia macrocítica, ferropenia y sobre todo hipergastrinemia sugiere una gastritis atrófica tipo A con pérdida de células parietales, lo que reduce la absorción de hierro y vitamina B12 y eleva la gastrina. Descartamos A, porque la pérdida hemorrágica por esteroides produciría anemia microcítica o normocítica y no explicaría la hipergastrinemia. Descartamos B, porque la colchicina puede causar supresión medular pero no genera hipergastrinemia ni macrocitosis. Descartamos C, porque la hemólisis inducida por metimazol daría una anemia normocítica y no se asocia a niveles elevados de gastrina.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 107, "especialidad": "Ginecología", "tema": null, "pregunta": "Una mujer de 32 años de edad consulta porque desea quedar embarazada y refiere antecedentes de episodio de embolia de pulmón 7 años antes mientras estaba tomando anticonceptivos orales. Se realizó tratamiento con acenocumarol durante 6 meses. El estudio de trombofilia fue negativo. Se aconseja realizar profilaxis de trombosis venosa en el caso de que quede embarazada. Señale la respuesta correcta:", "opcion_a": "Debe aconsejarse tratamiento profiláctico con heparina de bajo peso molecular durante el embarazo y hasta 6 semanas posparto.", "opcion_b": "Debe aconsejarse tratamiento profiláctico con aspirina durante todo el embarazo.", "opcion_c": "Debe aconsejarse realizar profilaxis con acenocumarol durante todo el embarazo.", "opcion_d": "Dado que el estudio de trombofilia fue negativo solo se precisa realizar profilaxis de trombosis venosa con medias compresivas para miembros inferiores.", "correcta": "A", "explicacion": "La respuesta correcta es A) Debe aconsejarse tratamiento profiláctico con heparina de bajo peso molecular durante el embarazo y hasta 6 semanas posparto: la historia de una embolia pulmonar previa constituye un factor de riesgo alto de recurrencia en el embarazo, y la profilaxis con LMWH es la medida recomendada por las guías para prevenir trombosis venosa durante la gestación y el puerperio inmediato. Descartamos B, porque la aspirina sola no ofrece una protección adecuada contra eventos trombóticos venosos en pacientes con antecedente de embolia pulmonar. Descartamos C, porque los anticoagulantes orales tipo vitamina K están contraindicados durante el embarazo. Descartamos D, porque las medias de compresión no son suficientes en presencia de un antecedente de tromboembolismo venoso.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 108, "especialidad": "Hematología", "tema": "Trastornos de la coagulación y hemostasia", "pregunta": "Respecto al tratamiento anticoagulante indique la respuesta FALSA:", "opcion_a": "Dabigatran - Inhibidor directo de la trombina.", "opcion_b": "Plasugrel - Inhibidor de agregación y activación plaquetaria.", "opcion_c": "Edoxaban - Inhibidor directo de factor Xa.", "opcion_d": "Idarucizumab - Inhibidor de la activación del plasminógeno.", "correcta": "-", "explicacion": null, "explicacion_calidad": null, "imagen_path": null, "anulada": true, "motivo_anulacion": "Anulada en la plantilla oficial del Ministerio de Sanidad (sin respuesta correcta).", "requiere_revision": false, "motivo_revision": null}, {"numero": 109, "especialidad": "Hematología", "tema": "Medicina transfusional y trasplante hematopoyético", "pregunta": "Hombre de 35 años con leucemia mieloide aguda sometido a alotrasplante de progenitores hematopoyéticos con acondicionamiento mieloablativo. Se encuentra en tratamiento con tacrolimus en rango terapéutico y profilaxis con aciclovir y un azol. Estando ambulatorio y sin complicaciones previas, acude al hospital en el día +24 postrasplante con eritema cutáneo generalizado que afecta con mayor intensidad a palmas y plantas, cara, cuello, tronco, flancos y cara interna de los muslos. Es de reciente aparición (24-48 horas) y se acompaña de anorexia, náuseas, diarrea acuosa y dolor abdominal. ¿Cuál es la actitud terapéutica más adecuada?", "opcion_a": "Suspender lo antes posible el tratamiento inmunosupresor con tacrolimus.", "opcion_b": "Iniciar tratamiento con esteroides a dosis altas.", "opcion_c": "Iniciar infusión de linfocitos del donante.", "opcion_d": "Iniciar tratamiento con fotoaféresis extracorpórea.", "correcta": "B", "explicacion": "La respuesta correcta es B) Iniciar tratamiento con esteroides a dosis altas: el paciente presenta rash cutáneo generalizado con afectación de palmas y plantas, diarrea y dolor abdominal, hallazgos típicos de enfermedad injerto contra huésped aguda, cuyo manejo inicial son corticoides sistémicos de alta dosis. Descartamos A, porque suspender tacrolimus eliminaría la inmunosupresión y empeoraría la enfermedad. Descartamos C, porque la infusión de linfocitos del donante se reserva para recaídas de la enfermedad subyacente y no para tratar la enfermedad injerto contra huésped. Descartamos D, porque la fotoaféresis extracorpórea es una terapia de segunda línea para casos refractarios a corticoides.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 110, "especialidad": "Hematología", "tema": "Síndromes linfoproliferativos y leucemias", "pregunta": "Mujer de 64 años, con antecedente de túnel carpiano bilateral. Presenta en los últimos meses un cuadro de astenia y disnea progresiva, hasta hacerse de pequeños esfuerzos. En la analítica destaca un pro-BNP de 2.500 pg/mL, así como la existencia de un componente monoclonal (inmunofijación positiva para cadenas lambda) en suero de 0,4 g/dL. Los niveles de cadenas ligeras libres kappa y lambda son 1,2 y 67,8 mg/dL, respectivamente. Se realiza una punción esternal observándose una plasmocitosis medular del 6%. Ausencia de lesiones líticas en TC de esqueleto entero. ¿Cuál es el diagnóstico de sospecha y la prueba diagnóstica inicial para su confirmación?", "opcion_a": "Macroglobulinemia de Waldenström - Análisis molecular del gen MYD88.", "opcion_b": "Mieloma múltiple sintomático - PET/TC.", "opcion_c": "Amiloidosis AL - Aspirado/biopsia de grasa abdominal.", "opcion_d": "Síndrome POEMS - Determinación de VEGF.", "correcta": "C", "explicacion": "La respuesta correcta es C) Amiloidosis AL - Aspirado/biopsia de grasa abdominal: la paciente presenta un componente monoclonal de cadena lambda con un marcado aumento de la cadena ligera libre lambda y una plasmocitosis medular del 6 %, sin lesiones óseas líticas, hallazgos que orientan a una amiloidosis AL cuya confirmación se realiza mediante biopsia de grasa abdominal que muestra depósitos amiloides. Descartamos A, porque la macroglobulinemia de Waldenström se asocia a una inmunoglobulina M monoclonal y a la mutación MYD88, no al patrón descrito. Descartamos B, porque el mieloma múltiple sintomático requiere presencia de lesiones óseas líticas o una mayor infiltración medular, ausentes en este caso. Descartamos D, porque el síndrome POEMS se caracteriza por neuropatía, organomegalia y elevación de VEGF, no por un componente monoclonal lambda aislado.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 111, "especialidad": "Hematología", "tema": "Trastornos de la coagulación y hemostasia", "pregunta": "Mujer de 17 años que presenta desde la primera menstruación reglas muy abundantes. Refiere epistaxis frecuentes. Hematimetría: Hb 10,5 g/dL, VCM 77 fL, leucocitos 7.200/µL con fórmula normal, plaquetas 182.000/µL. Tiempo de protrombina 12” (12”), TTPa 34” (30”), fibrinógeno 340 mg/dL. Agregación plaquetaria con ADP, colágeno y epinefrina: ausencia de respuesta. Aglutina con ristocetina. En citometría se observa ausencia de Gp IIb-IIIa. ¿Cuál es el diagnóstico?", "opcion_a": "Tromboastenia de Glanzmann.", "opcion_b": "Enfermedad de von Willebrand.", "opcion_c": "Trombocitopenia inmune primaria.", "opcion_d": "Síndrome de Bernard-Soulier.", "correcta": "A", "explicacion": "La respuesta correcta es A) Tromboastenia de Glanzmann: la ausencia de agregación plaquetaria con ADP, colágeno y epinefrina con respuesta normal a ristocetina y la falta de Gp IIb-IIIa en citometría son hallazgos típicos de esta enfermedad; los demás parámetros de coagulación y el recuento plaquetario son normales. Descartamos B, porque en la enfermedad de von Willebrand la agregación con ristocetina está disminuida. Descartamos C, porque la trombocitopenia inmune primaria se caracteriza por una disminución del número de plaquetas. Descartamos D, porque el síndrome de Bernard Soulier presenta deficiencia de Gp Ib y alteración de la agregación con ristocetina, no ausencia de Gp IIb-IIIa.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 112, "especialidad": "Hematología", "tema": "Trastornos de la coagulación y hemostasia", "pregunta": "Una joven de 23 años es referida por su obstetra para estudio de trombocitopenia. Sus plaquetas en la primera evaluación prenatal hace un mes fueron de 42.000/µL. Está embarazada de 16 semanas y no refiere manifestaciones hemorrágicas. La exploración física es normal. Hemograma: leucocitos 8.500/µL, Hb 12 g/dL, plaquetas 51.000/µL. La revisión del frotis sanguíneo revela plaquetas en acúmulos. ¿Cuál es la sospecha diagnóstica?", "opcion_a": "Trombocitopenia inmune primaria.", "opcion_b": "Trombocitopenia del embarazo.", "opcion_c": "Seudotrombocitopenia por EDTA.", "opcion_d": "Púrpura trombótica trombocitopénica.", "correcta": "C", "explicacion": "La respuesta correcta es C) Seudotrombocitopenia por EDTA: la presencia de plaquetas en acúmulos en el frotis sugiere artefacto de agregación inducido por el anticoante EDTA, lo que explica la baja cuenta sin síntomas hemorrágicos. Descartamos A, porque la trombocitopenia inmune primaria suele presentar destrucción plaquetaria sin agregación en frotis y puede asociarse a sangrado. Descartamos B, porque la trombocitopenia del embarazo se diagnostica por recuento bajo sin evidencia de clumping y suele presentarse en etapas más avanzadas. Descartamos D, porque la púrpura trombótica trombociténica se caracteriza por microangiopatía, anemia hemolítica y esquistocitos, ausentes en este caso.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 113, "especialidad": "Hematología", "tema": "Medicina transfusional y trasplante hematopoyético", "pregunta": "Con respecto al trasplante de progenitores hematopoyéticos señale la afirmación FALSA:", "opcion_a": "En pacientes que carecen de un donante familiar o no emparentado HLA-idéntico se puede emplear la sangre de cordón umbilical como fuente alternativa.", "opcion_b": "En pacientes que carecen de un donante familiar o no emparentado HLA-idéntico se pueden emplear células progenitoras de un donante haploidéntico.", "opcion_c": "En el trasplante autólogo las células se encuentran criopreservadas y han de descongelarse previo a su administración.", "opcion_d": "El efecto injerto contra leucemia es mayor en el trasplante autólogo que en el alogénico.", "correcta": "D", "explicacion": "La respuesta correcta es D) El efecto injerto contra leucemia es mayor en el trasplante autólogo que en el alogénico: En el trasplante autólogo el paciente recibe sus propias células, por lo que no existe una respuesta inmune contra la leucemia residual. En el alogénico las células del donante pueden reconocer y eliminar células leucémicas, generando un potente efecto GVL; por ello la afirmación es falsa. Descartamos A, porque la sangre de cordón umbilical es una fuente aceptada cuando no hay donante HLA idéntico. Descartamos B, porque los donantes haploidénticos pueden proporcionar células progenitoras en ausencia de un donante idéntico. Descartamos C, porque en el trasplante autólogo las células se congelan y deben descongelarse antes de su administración.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 114, "especialidad": "Infecciosas", "tema": "Infecciones de transmisión sexual y VIH — sífilis, VIH, infecciones congénitas/perinatales relacionadas", "pregunta": "Hombre de 34 años que consulta en el servicio de urgencias por disuria y quemazón en el meato uretral, con presencia de una secreción blaquecina y espesa que sale a través del meato desde hace 3 días. ¿Cuál de las siguientes respuestas es FALSA?", "opcion_a": "Hay que obtener una muestra del exudado uretral para realizar el diagnóstico etiológico.", "opcion_b": "Se realizará tratamiento empírico con ceftriaxona intramuscular y azitromicina vía oral en dosis únicas, en espera de los resultados microbiológicos.", "opcion_c": "Hay que realizar antibiograma en los casos en que se aisle N. gonorrhoeae.", "opcion_d": "A las 2-3 semanas de la administración del tratamiento, hay que obtener nuevas muestras uretrales para confirmar la curación microbiológica.", "correcta": "D", "explicacion": "La respuesta correcta es D) A las 2-3 semanas de la administración del tratamiento, hay que obtener nuevas muestras uretrales para confirmar la curación microbiológica: no se recomienda realizar un control microbiológico rutinario a esas semanas porque la curación se verifica clínicamente y con pruebas de seguimiento solo si persisten síntomas o se sospecha resistencia. Descartamos A, porque el exudado uretral es la muestra de referencia para identificar N. gonorrhoeae y C. trachomatis. Descartamos B, porque el esquema de ceftriaxona IM + azitromicina oral única es la terapia empírica recomendada para gonorrea y clamidia mientras se esperan los resultados. Descartamos C, porque cuando se aísla N. gonorrhoeae es necesario realizar un antibiograma para guiar terapias en caso de resistencia.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 115, "especialidad": "Infecciosas", "tema": "Infecciones en el paciente inmunodeprimido/trasplantado — oportunistas", "pregunta": "Mujer de 65 años, sometida a trasplante de precursores hematopoyéticos hace 30 días y neutropenia grave. Comienza con tos y expectoración hemoptoica además de fiebre y disnea de moderados esfuerzos que no mejora a pesar de cinco días de tratamiento con amoxicilina-clavulánico (875/125 mg/8 h) y levofloxacino (500 mg/12 h). En la radiografía de tórax se observan múltiples nódulos pulmonares mal definidos, alguno de ellos cavitado. De entre los siguientes, ¿cuál es el diagnóstico de sospecha más probable?", "opcion_a": "Embolismos sépticos.", "opcion_b": "Aspergilosis pulmonar invasiva.", "opcion_c": "Neumonía por Estafilococo aureus.", "opcion_d": "Candidiasis sistémica.", "correcta": "B", "explicacion": "La respuesta correcta es B) Aspergilosis pulmonar invasiva: una paciente en el primer mes tras un trasplante de progenitores hematopoyéticos, con neutropenia grave y profunda, que presenta fiebre, tos, hemoptisis y nódulos pulmonares mal definidos, algunos cavitados, sin respuesta a antibióticos de amplio espectro, tiene como primera sospecha una infección fúngica invasiva por hongos filamentosos, y la más frecuente es la aspergilosis. Aspergillus invade los vasos y produce nódulos con infarto hemorrágico, de ahí la hemoptisis, que pueden cavitarse. Descartamos A, porque los émbolos sépticos suelen asociarse a un foco endovascular conocido, como un catéter infectado, una tromboflebitis séptica o una endocarditis derecha, con bacteriemia, y no son la primera sospecha en este contexto de neutropenia profunda sin respuesta a antibióticos. Descartamos C, porque la neumonía por Staphylococcus aureus sensible quedaría en buena parte cubierta con amoxicilina-clavulánico, y en un neutropénico de alto riesgo con nódulos que progresan pese a antibióticos los hongos filamentosos son mucho más probables. Descartamos D, porque la candidiasis invasiva rara vez produce neumonía nodular cavitada; su forma típica tras la neutropenia es la diseminada o la hepatoesplénica.", "explicacion_calidad": "revisada", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 116, "especialidad": "Infecciosas", "tema": "Enfermedades importadas, zoonosis y fiebres de origen desconocido — histoplasmosis, leptospirosis, viajes", "pregunta": "Hombre de 38 años que acude a urgencias por cuadro de fiebre por encima de 39°C y deterioro del nivel de conciencia tras haber realizado un viaje a Guinea Ecuatorial sin profilaxis antimalárica. En la analítica destaca: creatinina de 3,4 mg/dL, AST 764 U/L, ALT 678 U/L. El laboratorio informa de la visualización en sangre de un Plasmodium falciparum con un nivel de parasitemia del 6%. ¿Qué tratamiento instauraría en este momento?", "opcion_a": "Mefloquina por vía oral.", "opcion_b": "Artesunato intravenoso.", "opcion_c": "Doxiciclina por vía oral.", "opcion_d": "Sulfato de quinina por vía oral.", "correcta": "B", "explicacion": "La respuesta correcta es B) Artesunato intravenoso: la presencia de Plasmodium falciparum con parasitemia del 6 % y compromiso renal y hepático indica malaria grave, para la cual la guía recomienda artesunato por vía intravenosa como primera línea. Descartamos A, porque la mefloquina oral no es adecuada para malaria grave ni con alta parasitemia. Descartamos C, porque la doxiciclina oral es un fármaco de segunda línea y no se usa en casos de gravedad. Descartamos D, porque la quinina oral no alcanza concentraciones suficientes en malaria severa y la vía recomendada sería intravenosa, no oral.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 117, "especialidad": "Infecciosas", "tema": "Sepsis y shock séptico — manejo inicial, antibioterapia empírica", "pregunta": "Hombre de 85 años portador de catéter venoso periférico que, una semana después de estar hospitalizado por un ictus, comienza con tiritona y fiebre. Se realizan hemocultivos y desde microbiología se informa que están creciendo cocos gram positivos en racimos. En espera del antibiograma, ¿cuál es el tratamiento antibiótico más adecuado?", "opcion_a": "Cefazolina.", "opcion_b": "Cloxacilina.", "opcion_c": "Vancomicina.", "opcion_d": "Linezolid.", "correcta": "C", "explicacion": "La respuesta correcta es C) Vancomicina: en un paciente con catéter venoso y cultivo que muestra cocos gram positivos en racimos, la sospecha principal es Staphylococcus aureus y la alta prevalencia de cepas resistentes a meticilina en entornos hospitalarios obliga a iniciar terapia con vancomicina mientras se espera el antibiograma. Además, la vancomicina cubre tanto cepas sensibles como resistentes y es la opción de amplio espectro recomendada en sepsis grave. Descartamos A, porque la cefazolina no cubre cepas resistentes a meticilina. Descartamos B, porque la cloxacilina es ineficaz contra s. aureus resistente a meticilina. Descartamos D, porque el linezolid, aunque activo, se reserva para situaciones de intolerancia o falla de vancomicina.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 118, "especialidad": "Infecciosas", "tema": "Sepsis y shock séptico — manejo inicial, antibioterapia empírica", "pregunta": "Luis es un joven de 25 años que sufrió esplenectomía tras accidente de bicicleta hace 1 año. Tiene un perro que le mordió hace 24 horas y le ha producido una pequeña herida en la mano derecha. Acude a su centro de salud (situado a 3 horas del hospital más cercano) por fiebre de 39°C, dolor en la herida y malestar general. A la exploración PA 100/60 mm Hg, FC 110 latidos por minuto, ligera inflamación en la herida sin pus. ¿Cuál de las siguientes actuaciones está más indicada en este momento?", "opcion_a": "Enviar al hospital para vacunar de rabia y tétanos y mantener en observación.", "opcion_b": "Limpiar la herida y administrar gammaglobulina inespecífica intramuscular.", "opcion_c": "Dar 400 mg de moxifloxacino oral y enviar al hospital.", "opcion_d": "Dar clindamicina 600 mg oral cada 8 horas y observación.", "correcta": "C", "explicacion": "La respuesta correcta es C) Dar 400 mg de moxifloxacino oral y enviar al hospital: el paciente asplénico tiene un riesgo elevado de infección grave por bacterias de la boca del perro, y la moxifloxacino cubre a Pasteurella, Capnocytophaga y otras gram‑negativas, proporcionando una terapia empírica adecuada mientras se traslada al centro con recursos de cuidados intensivos; además, la presencia de fiebre, taquicardia y presión arterial borderline justifica la derivación urgente. Descartamos A, porque la vacunación antirrábica y antitetánica no aborda la infección bacteriana ni la posible sepsis. Descartamos B, porque la gammaglobulina inespecífica no tiene evidencia de beneficio en mordeduras de perro y no sustituye la antibioterapia. Descartamos D, porque la clindamicina no cubre de forma fiable a los patógenos típicos de mordeduras caninas y es insuficiente ante el riesgo de sepsis.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 119, "especialidad": "Infecciosas", "tema": "Enfermedades importadas, zoonosis y fiebres de origen desconocido — histoplasmosis, leptospirosis, viajes", "pregunta": "Mujer de 38 años de edad de profesión veterinaria, encargada de la vigilancia de animales salvajes y de ayudar a partos de ganado doméstico. Comienza con un cuadro de fiebre alta con escalofríos, cefalea, mialgias y tos no productiva que interpreta como un proceso gripal. Acude por presentar dolor torácico. En la radiografía de tórax se objetivan infiltrados pulmonares bilaterales en campos inferiores. Se realiza una prueba serológica con elevación de títulos de anticuerpos frente a antígenos en fase II. ¿Cuál de las siguientes afirmaciones es CIERTA?", "opcion_a": "La forma de trasmisión de esta entidad es por garrapatas.", "opcion_b": "Tanto la doxiciclina como la hidroxicloroquina son eficaces para tratar las formas agudas de esta enfermedad.", "opcion_c": "En su forma aguda también presenta, generalmente, elevación de anticuerpos frente a antígenos en fase I.", "opcion_d": "La mortalidad en las formas agudas es casi inexistente.", "correcta": "D", "explicacion": "La respuesta correcta es D) La mortalidad en las formas agudas es casi inexistente: la fiebre Q aguda se presenta con síntomas gripales, infiltrados pulmonares y anticuerpos de fase II elevados, y su evolución suele ser benigna con muy poca mortalidad. Además, el tratamiento de elección es la doxiciclina y la hidroxicloroquina se reserva para la enfermedad crónica. Descartamos A, porque la transmisión principal es por inhalación de aerosoles de productos de animales infectados y no por garrapatas. Descartamos B, porque la hidroxicloroquina no es eficaz en la fase aguda y solo se usa en la forma crónica junto a doxiciclina. Descartamos C, porque en la fase aguda los anticuerpos contra antígenos de fase I no están elevados de forma significativa.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 120, "especialidad": "Infecciosas", "tema": "Tuberculosis y micobacterias — diagnóstico, resistencias, retratamiento", "pregunta": "¿Cuál es la pauta estándar actual, en nuestro medio, de tratamiento de la tuberculosis pulmonar?", "opcion_a": "Isoniazida + rifampicina + pirazinamida (6 meses).", "opcion_b": "Isoniazida + rifampicina + pirazinamida + etambutol (2 meses) seguido de isoniazida + rifampicina (4 meses).", "opcion_c": "Isoniazida + rifabutina + etambutol (9 meses).", "opcion_d": "Isoniazida + rifampicina + pirazinamida (2 meses) seguido de isoniazida + rifampicina (4 meses).", "correcta": "B", "explicacion": "La respuesta correcta es B) Isoniazida + rifampicina + pirazinamida + etambutol (2 meses) seguido de isoniazida + rifampicina (4 meses): es la pauta recomendada por las guías nacionales e internacionales para tuberculosis pulmonar sensible, con fase intensiva de dos meses de cuatro fármacos y fase de continuación de cuatro meses de dos fármacos. Descartamos A, porque omite etambutol en la fase intensiva, lo que no corresponde a la pauta estándar. Descartamos C, porque utiliza rifabutina, no incluye pirazinamida y prolonga el tratamiento a nueve meses, lo cual no está indicado. Descartamos D, porque carece de etambutol en la fase intensiva, que es esencial en la terapia estándar.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 121, "especialidad": "Respiratorio", "tema": "Infecciones respiratorias", "pregunta": "Hombre de 45 años que consulta por tos productiva, dolor pleurítico en costado derecho y fiebre de 48 h de evolución. Se aprecia una saturación basal de O2 del 88% y estertores en base derecha. La RX de tórax muestra una consolidación basal derecha. Tiene antecedentes de infección por VIH bien controlada con antirretrovirales (linfocitos CD4 550 cel/µL y carga viral de VIH indectectable). ¿Cuál de los tratamientos antimicrobianos empíricos que se citan a continuación le parece más adecuado?", "opcion_a": "Ceftriaxona 2 g y azitromicina 500 mg cada 24 horas.", "opcion_b": "Ceftriaxona 2 g, azitromicina 500 mg cada 24 horas y trimetoprim-sulfametoxazol 5 mg/kg/8 h (basado en dosis de trimetoprim).", "opcion_c": "Metil-prednisolona 40 mg /día, ceftriaxona 2 g IV/24 h y trimetoprim-sulfametoxazol 5 mg/kg/8 h (basado en dosis de trimetoprim).", "opcion_d": "Meropenem 1 g/8 h y vancomicina 1 g/12 h.", "correcta": "A", "explicacion": "La respuesta correcta es A) Ceftriaxona 2 g y azitromicina 500 mg cada 24 horas: cubre los patógenos típicos y atípicos responsables de neumonía adquirida en la comunidad, es suficiente en un paciente con VIH bien controlado y sin factores de riesgo de resistencia o de organismos multirresistentes. Esta combinación brinda una cobertura empírica adecuada para la presentación clínica. Descartamos B, porque añadir trimetoprim‑sulfametoxazol solo está indicado cuando se sospecha Pneumocystis jirovecii u otras infecciones oportunistas, lo cual no se justifica aquí. Descartamos C, porque los corticoides no están recomendados en neumonía comunitaria sin insuficiencia respiratoria grave y el trimetoprim‑sulfametoxazol no aporta beneficio adicional. Descartamos D, porque meropenem y vancomicina son antibióticos de amplio espectro reservados para neumonías graves o con alto riesgo de patógenos resistentes, excediendo la necesidad del caso.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 122, "especialidad": "Infecciosas", "tema": null, "pregunta": "Con respecto a la infección por el virus de la hepatitis C (VHC), señale la respuesta correcta:", "opcion_a": "En el mundo, la vía de transmisión más frecuente del VHC es la vertical.", "opcion_b": "Si el VHC se adquiere en edad adulta, se cronifica en el 5-10% de los casos.", "opcion_c": "La mayoría de los pacientes con infección crónica por el VHC presentan anticuerpos anti VHC positivos.", "opcion_d": "La infección aguda por el VHC cursa con ictericia franca en más del 80% de los casos.", "correcta": "C", "explicacion": "La respuesta correcta es C) La mayoría de los pacientes con infección crónica por el VHC presentan anticuerpos anti VHC positivos: la infección persistente mantiene una respuesta inmunitaria detectable y la serología anti‑VHC es el método estándar para identificar la cronicidad. Descartamos A, porque la transmisión vertical no es la vía más frecuente a nivel mundial, predominando la exposición parenteral. Descartamos B, porque la tasa de cronicidad tras adquisición en edad adulta es considerablemente mayor que la indicada. Descartamos D, porque la infección aguda rara vez se manifiesta con ictericia franca en la mayoría de los casos.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 123, "especialidad": "Reumatología", "tema": null, "pregunta": "Mujer de 65 años que acude a su odontólogo por dolor en cuerpo mandibular derecho y lesión ulcerada en mucosa oral con exposición de hueso sobre una zona de roce por su prótesis dental, de tres meses de evolución. Entre sus antecedentes destaca una fractura vertebral por osteoporosis hace 5 años, fumadora de un paquete de cigarrillos al día, diabetes tipo 2 desde hace 15 años, polimialgia reumática en tratamiento esteroideo oral (5 mg de prednisona diariamente desde hace 5 años) y neoplasia de mama derecha tratada hace 5 años con cirugía y radioterapia local. La paciente recibe tratamiento con denosumab desde hace 5 años. ¿Cuál es el diagnóstico clínico más probable?", "opcion_a": "Lesión ósea mandibular secundaria a radioterapia (osteorradionecrosis).", "opcion_b": "Necrosis ósea vascular mandibular secundaria a vasculopatía diabética, tabaquismo y osteoporosis.", "opcion_c": "Carcinoma epidermoide verrucoso-ulcerado.", "opcion_d": "Osteonecrosis mandibular secundaria a tratamiento con denosumab.", "correcta": "D", "explicacion": "La respuesta correcta es D) Osteonecrosis mandibular secundaria a tratamiento con denosumab: la aparición de una lesión ulcerada con exposición ósea en zona de roce después de varios años de denosumab es típica de la osteonecrosis mandibular inducida por fármacos antiresortivos, y la ausencia de signos de infección o tumor la hacen la causa más plausible. Además, el denosumab inhibe la resorción ósea y predispone a la necrosis tras traumatismo menor como la prótesis dental. Descartamos A, porque la radioterapia local fue hace varios años y la lesión se localiza en zona de roce dental, no típica de osteorradionecrosis. Descartamos B, porque aunque la paciente tiene factores vasculares, la característica clínica de exposición ósea tras trauma menor es más propia de la necrosis inducida por fármacos que de una necrosis vascular. Descartamos C, porque la lesión ulcerada no muestra características de carcinoma escamoso ni evidencia de crecimiento tumoral.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 124, "especialidad": "ORL", "tema": "Oncología de cabeza y cuello", "pregunta": "¿En cuál de las siguientes lesiones de los maxilares el tratamiento exige realizar una resección parcial o marginal, ya que la simple enucleación o curetaje de la misma NO es suficiente para erradicarla?", "opcion_a": "Tumor odontogénico adenomatoide.", "opcion_b": "Mixoma odontogénico.", "opcion_c": "Osteoblastoma.", "opcion_d": "Granuloma eosinófilo.", "correcta": "B", "explicacion": "La respuesta correcta es B) Mixoma odontogénico: el mixoma odontogénico es una neoplasia benigna pero localmente agresiva, sin cápsula, que infiltra el hueso trabecular vecino y tiene una alta tasa de recidiva tras la enucleación o el curetaje, por lo que se trata con una resección parcial o marginal con margen de hueso sano. Descartamos A, porque el tumor odontogénico adenomatoide es una lesión bien encapsulada que se cura con enucleación simple y apenas recidiva. Descartamos C, porque el osteoblastoma suele tratarse con curetaje o escisión local. Descartamos D, porque el granuloma eosinófilo se trata con curetaje, infiltración local de corticoides o incluso observación.", "explicacion_calidad": "revisada", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 125, "especialidad": "ORL", "tema": "Hipoacusia y patología audiológica", "pregunta": "¿Qué resultado ofrecería la acumetría con un diapasón de 500 Hz, en una sordera brusca idiopática del oído derecho?", "opcion_a": "Rinne positivo (+) del oído derecho y Weber hacia el oído izquierdo.", "opcion_b": "Rinne negativo (-) del oído derecho y Weber hacia el oído izquierdo.", "opcion_c": "Rinne positivo (+) del oído izquierdo y Weber hacia el oído derecho.", "opcion_d": "Rinne negativo (-) del oído izquierdo y Weber hacia el oído derecho.", "correcta": "A", "explicacion": "La respuesta correcta es A) Rinne positivo (+) del oído derecho y Weber hacia el oído izquierdo: En la sordera brusca idiopática del oído derecho la pérdida es sensorineural, por lo que la conducción aérea supera a la ósea y el Rinne resulta positivo. El test de Weber se desvía hacia el oído sano, en este caso el izquierdo, porque el oído afectado percibe menos intensidad sonora. Así se confirma el patrón típico de una pérdida neurosensorial unilateral. Descartamos B, porque un Rinne negativo indicaría una pérdida conductiva, lo cual no corresponde a una sordera brusca idiopática. Descartamos C, porque el Rinne positivo del oído izquierdo y la desviación del Weber al derecho describen una pérdida del oído izquierdo, no del derecho. Descartamos D, porque un Rinne negativo del oído izquierdo y la desviación del Weber al derecho son incompatibles con la fisiopatología de la sordera brusca idiopática del oído derecho.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 126, "especialidad": "ORL", "tema": "Oncología de cabeza y cuello", "pregunta": "Hombre de 47 años, con antecedente de un adenoma pleomorfo parotídeo derecho, tratado con cirugía (parotidectomía extrafacial) hace 6 meses, que acude a nuestra consulta por presentar durante la masticación dolor con sudoración y enrojecimiento de la piel de la región preauricular. ¿Qué tratamiento sería el de elección?", "opcion_a": "Parotidectomía total ampliada ante la sospecha de recidiva tumoral.", "opcion_b": "Pregabalina.", "opcion_c": "Inyección de toxina botulínica intradérmica.", "opcion_d": "Antibioterapia de amplio espectro.", "correcta": "C", "explicacion": "La respuesta correcta es C) Inyección de toxina botulínica intradérmica: la combinación de dolor, sudoración y enrojecimiento cutáneo al masticar es típica del síndrome de Frey, una hiperhidrosis gustatoria que se controla eficazmente con toxina botulínica que bloquea la liberación de acetilcolina en las terminaciones sudoríparas. La aplicación intradérmica permite una mejora sintomática duradera y evita intervenciones quirúrgicas mayores. Descartamos A, porque la sospecha de recidiva tumoral no se sustenta en hallazgos de masa ni en síntomas de malignidad. Descartamos B, porque la pregabalina alivia el dolor neuropático pero no afecta la sudoración ni el enrojecimiento. Descartamos D, porque la presencia de infección no está demostrada y la antibioterapia no tiene efecto sobre la hiperhidrosis gustatoria.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 127, "especialidad": "ORL", "tema": "Vértigo y patología vestibular", "pregunta": "Considerando que la fisiopatología del vértigo posicional paroxístico benigno es la cupulolitiasis, ¿qué tratamiento indicaría en un paciente en el que los síntomas persisten pasadas dos semanas?", "opcion_a": "Sedantes vestibulares neurolépticos o antidopaminérgicos.", "opcion_b": "Corticosteroides.", "opcion_c": "Maniobra de reposición de partículas.", "opcion_d": "Neurectomía del nervio singular.", "correcta": "C", "explicacion": "La respuesta correcta es C) Maniobra de reposición de partículas: en la cupulolitiasis los otoconios desplazados se encuentran adheridos a la cupula y la reposición mediante maniobras de reposicionamiento, como la de Epley o la de Semont, permite su reubicación en el utrículo y la resolución del vértigo. Cuando los síntomas persisten más de dos semanas, la maniobra sigue siendo el tratamiento de elección antes de considerar intervenciones más invasivas. Descartamos A, porque los sedantes vestibulares pueden aliviar los síntomas pero no eliminan la causa subyacente de la cupulolitiasis. Descartamos B, porque los corticosteroides no tienen evidencia de eficacia en el vértigo posicional paroxístico benigno y su uso está reservado a otras patologías vestibulares inflamatorias. Descartamos D, porque la neurectomía del nervio singular es una medida extrema indicada solo en casos de enfermedad de Menière refractaria, no en el vértigo posicional paroxístico benigno.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 128, "especialidad": "Nefrología", "tema": "Fracaso renal agudo: causas y manejo", "pregunta": "Sospecharemos insuficiencia renal aguda de origen pre-renal en presencia de:", "opcion_a": "Hipotensión, elevación de las cifras de urea y creatinina sérica, osmolaridad en orina inferior a 500 mOsm/kg y excreción fraccional de sodio superior a 1%.", "opcion_b": "Intolerancia digestiva, elevación de las cifras de urea y creatinina séricas, osmolaridad en orina superior a 500 mOsm/kg y excreción fraccional de sodio inferior a 1%.", "opcion_c": "Administración intravenosa previa de contraste iodado, elevación de las cifras de urea y creatinina séricas, osmolaridad en orina inferior a 500 mOsm/kg y excreción fraccional de sodio superior a 1%.", "opcion_d": "Administración previa de un antibiótico aminoglicósido, elevación de las cifras de urea y creatinina séricas e isostenuria.", "correcta": "B", "explicacion": "La respuesta correcta es B) Intolerancia digestiva, elevación de las cifras de urea y creatinina séricas, osmolaridad en orina superior a 500 mOsm/kg y excreción fraccional de sodio inferior a 1%: la combinación de una causa de pérdida de volumen (intolerancia digestiva) con alta osmolaridad urinaria y bajo FeNa indica una retención de agua y sodio típica del estado pre‑renal. Descartamos A, porque la osmolaridad urinaria es inferior a 500 mOsm/kg y la fracción de sodio es superior al 1%, hallazgos incompatibles con pre‑renal. Descartamos C, porque la administración de contraste sugiere lesión tubular y la osmolaridad urinaria baja y FeNa alta son típicos de lesión intrínseca. Descartamos D, porque la isostenuria indica incapacidad de concentrar la orina, característica de daño tubular y no de pre‑renal.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 129, "especialidad": "Nefrología", "tema": "Enfermedad renal crónica y manejo terapéutico", "pregunta": "La asociación de alteraciones metabólicas más característica que podemos encontrar en presencia de insuficiencia renal crónica en estadios avanzados es:", "opcion_a": "Hiperpotasemia, hipofosforemia, hipercalcemia y acidosis metabólica.", "opcion_b": "Hipopotasemia, hipofosforemia, hipocalcemia y acidosis metabólica.", "opcion_c": "Hiperpotasemia, hiperfosforemia, hipocalcemia y acidosis metabólica.", "opcion_d": "Hiperpotasemia, hiperfosforemia, hipocalcemia y alcalosis metabólica.", "correcta": "C", "explicacion": "La respuesta correcta es C) Hiperpotasemia, hiperfosforemia, hipocalcemia y acidosis metabólica: En la insuficiencia renal crónica avanzada la eliminación de potasio y fosfato se ve reducida, lo que produce hiperpotasemia e hiperfosforemia. La retención de fosfato y la disminución de la síntesis de calcitriol provocan hipocalcemia, y la incapacidad para excretar ácidos genera una acidosis metabólica. Descartamos A, porque la hipofosforemia y la hipercalcemia no se observan en la enfermedad renal avanzada. Descartamos B, porque la hipopotasemia y la hipofosforemia son contrarias a la fisiopatología renal. Descartamos D, porque la alcalosis metabólica no es típica de la insuficiencia renal crónica.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 130, "especialidad": "Nefrología", "tema": "Glomerulonefritis y enfermedades glomerulares", "pregunta": "Hombre de 28 años de edad que acude a urgencias del hospital por presentar hematuria macroscópica. ¿Cuál de las siguientes alteraciones en el análisis de orina apoyaría el diagnóstico de glomerulonefritis?", "opcion_a": "Hematíes dismórficos y/o cilindros hemáticos.", "opcion_b": "Proteinuria de 1 g/día, con resultado negativo en tira reactiva y con microalbuminuria mayor de 300 mg/24 horas.", "opcion_c": "Coexistencia de hematuria con piuria sin bacteriuria.", "opcion_d": "Coágulos en la orina a simple vista.", "correcta": "A", "explicacion": "La respuesta correcta es A) Hematíes dismórficos y/o cilindros hemáticos: la presencia de eritrocitos con forma anormal y cilindros hemáticos indica origen glomerular de la hematuria, pues estos elementos se forman en el túbulo después de filtración de sangre dañada. Otros hallazgos no son específicos de glomerulonefritis. Descartamos B, porque la proteinuria descrita no se detecta en tira reactiva y la microalbuminuria no es típica de un proceso glomerular agudo. Descartamos C, porque la piuria sin bacteriuria sugiere una infección del tracto urinario o inflamación no glomerular. Descartamos D, porque los coágulos visibles son más frecuentes en hematuria de origen no glomerular, como cálculos o trauma.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 131, "especialidad": "Nefrología", "tema": "Glomerulonefritis y enfermedades glomerulares", "pregunta": "Hombre de 25 años sin antecedentes conocidos de interés. Lleva 2 meses con orinas espumosas y cargadas, sin otra sintomatología. Exploración física sin hallazgos. Orina elemental: pH 5; glucosa -; hemoglobina ++; proteinas ++; esterasa leucocitaria -; proteinuria 1,5 g/24 horas; Na urinario 60 mEq/L; K urinario 30 mEq/L; Cl urinario 100 mEq/L. Bioquímica sanguínea: creatinina 1,6 mg/dL; urea 80 mg/dL; Na 140 mEq/L; K 3,8 mEq/L. Estudio inmunológico: antiDNA negativo; ANCA negativo; antiMBG negativo; factor reumatoide negativo; C3 20 mg/dL (normal 60-120); C4 10 mg/dL (normal 20-40). Se realiza biopsia renal. ¿Cuál de estos diagnósticos le parece más probable encontrar en la biopsia?", "opcion_a": "Glomerulonefritis membranosa.", "opcion_b": "Glomerulonefritis de cambios mínimos.", "opcion_c": "Glomerulonefritis mesangial IgA.", "opcion_d": "Glomerulonefritis membranoproliferativa.", "correcta": "D", "explicacion": "La respuesta correcta es D) Glomerulonefritis membranoproliferativa: la combinación de proteinuria significativa, elevación de creatinina y consumo de complementos C3 y C4 sugiere una nefropatía por complejos inmunes típica de glomerulonefritis membranoproliferativa. Además, la ausencia de anticuerpos específicos y la edad del paciente encajan con esta entidad. Descartamos A, porque la glomerulonefritis membranosa se asocia con proteinuria nefrótica y complementos normales. Descartamos B, porque la enfermedad de cambios mínimos presenta complementos normales y proteinuria mayor sin deterioro de la función renal. Descartamos C, porque la glomerulonefritis mesangial IgA suele presentar hematuria macroscópica y niveles de complemento no disminuidos.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 132, "especialidad": "Nefrología", "tema": "Nefritis intersticial y nefrotoxicidad farmacológica", "pregunta": "¿Cuál de las siguientes es la forma más frecuente de presentación de la nefropatía por litio?", "opcion_a": "Glomeruloesclerosis.", "opcion_b": "Diabetes insípida nefrógena.", "opcion_c": "Nefropatía túbulo-intersticial crónica.", "opcion_d": "Nefritis intersticial aguda.", "correcta": "B", "explicacion": "La respuesta correcta es B) Diabetes insípida nefrógena: la litio interfiere con la acción de la vasopresina en los túbulos colectores, produciendo una resistencia al ADH que se traduce en poliuria y polidipsia. Esta alteración funcional es la forma clínica más frecuente de nefropatía por litio. Descartamos A, porque la glomeruloesclerosis no es la manifestación renal típica del litio y ocurre con menor frecuencia. Descartamos C, porque la nefropatía túbulo-intersticial crónica es menos frecuente que la diabetes insípida nefrógena. Descartamos D, porque la nefritis intersticial aguda es una reacción poco frecuente y no representa la presentación más habitual.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 133, "especialidad": "Nefrología", "tema": "Fracaso renal agudo: causas y manejo", "pregunta": "Hombre de 55 años al que hace 24 horas se le ha realizado un trasplante renal. Comienza con hematuria y posteriormente con un cese brusco de la diuresis. ¿Qué prueba de imagen es la indicada para aclarar el diagnóstico?", "opcion_a": "Renograma isotópico.", "opcion_b": "Ecografía-doppler.", "opcion_c": "Urografía intravenosa.", "opcion_d": "Resonancia magnética.", "correcta": "B", "explicacion": "La respuesta correcta es B) Ecografía-doppler: en el post‑trasplante la aparición súbita de hematuria y oliguria sugiere una complicación vascular como la trombosis de la arteria o la vena del injerto, que se evalúa de forma rápida y no invasiva con ecografía Doppler que muestra flujo sanguíneo y posible estenosis. Además, permite descartar colecciones perirrenales y valorar la perfusión renal en tiempo real. Descartamos A, porque el renograma isotópico requiere tiempo y no brinda información inmediata del flujo vascular. Descartamos C, porque la urografía intravenosa es menos sensible para detectar alteraciones vasculares y conlleva riesgo de contraste nefrotóxico. Descartamos D, porque la resonancia magnética es menos accesible, más costosa y no necesaria cuando la ecografía Doppler es suficiente.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 134, "especialidad": "MFyC", "tema": null, "pregunta": "Hombre de 55 años diabético con buen control glucémico que acude por disfunción eréctil de 3 años de evolución, de inicio lento. En el tratamiento de la disfunción eréctil inicialmente se deben tratar las causas etiológicas, modificar estilos de vida que favorecen la disfunción eréctil e identificar las necesidades y expectativas del paciente y de su pareja. ¿Cuál debería ser el tratamiento complementario a considerar?", "opcion_a": "Inhibidores de fosfodiesterasa 5.", "opcion_b": "Dispositivos de vacío.", "opcion_c": "Alprostadilo tópico.", "opcion_d": "Inyecciones intracavernosas.", "correcta": "A", "explicacion": "La respuesta correcta es A) Inhibidores de fosfodiesterasa 5: son la primera línea en la disfunción eréctil cuando se han tratado las causas subyacentes y se han modificado los factores de riesgo, su eficacia está demostrada y su perfil de seguridad es aceptable en pacientes diabéticos con buen control glucémico. Además, se administran oralmente, lo que facilita la adherencia. Descartamos B, porque los dispositivos de vacío se reservan para casos en los que los inhibidores de PDE5 no son eficaces o están contraindicados. Descartamos C, porque el alprostadilo tópico se utiliza principalmente cuando los inhibidores orales fallan y requiere aplicación local que puede ser incómoda. Descartamos D, porque las inyecciones intracavernosas son una opción de segunda o tercera línea y conllevan mayor invasividad y riesgo de efectos adversos.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 135, "especialidad": "Oncología", "tema": "Tumores genitourinarios", "pregunta": "Hombre de 63 años, sin antecedentes familiares de carcinoma prostático, que consulta por leve sintomatología miccional obstructiva. Aporta una determinación de antígeno prostático específico (PSA) menor de 1 ng/mL. En el tacto rectal se aprecia una zona endurecida y fija de medio centímetro, en un lóbulo prostático. Ante este caso, la actitud correcta es:", "opcion_a": "Repetir la determinación de PSA en tres meses.", "opcion_b": "Indicar una biopsia prostática transrrectal.", "opcion_c": "Tratar con un alfa bloqueante para mejorar la sintomatología obstructiva y repetir anualmente el PSA.", "opcion_d": "Programar una resección prostática retropúbica.", "correcta": "B", "explicacion": "La respuesta correcta es B) Indicar una biopsia prostática transrrectal: la presencia de una zona endurecida y fija en el tacto rectal sugiere una lesión sospechosa de carcinoma, y el PSA bajo no excluye la enfermedad, por lo que se requiere confirmación histológica. Descartamos A, porque repetir el PSA no permite diagnosticar la lesión palpable. Descartamos C, porque el tratamiento sintomático no sustituye la necesidad de biopsia ante hallazgo anómalo. Descartamos D, porque la resección prostática retropúbica es un procedimiento terapéutico que solo se justifica tras diagnóstico confirmado.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 136, "especialidad": "Pediatría", "tema": null, "pregunta": "Niña de dos años diagnosticada de reflujo vesicoureteral unilateral grado II (reflujo al uréter, pelvis y cálices sin dilatación de la vía urinaria y morfología papilar normal). ¿Cuál es el tratamiento más adecuado de inicio ante esta patología?", "opcion_a": "Inyección endoscópica de dextranómero en el trayecto ureteral intramural.", "opcion_b": "Reimplantación ureteral por vía abierta.", "opcion_c": "Reimplantación ureteral laparoscópica.", "opcion_d": "Tratamiento conservador mediante observación y profilaxis antibiótica/antiséptica.", "correcta": "D", "explicacion": "La respuesta correcta es D) Tratamiento conservador mediante observación y profilaxis antibiótica/antiséptica: en un reflujo vesicoureteral unilateral de grado II sin dilatación ni anomalías papilares, la evidencia sugiere que la mayoría de los casos se resuelven espontáneamente y la profilaxis reduce el riesgo de infecciones; por tanto se inicia con vigilancia y antibióticos profilácticos. Descartamos A, porque la inyección endoscópica se reserva a grados más altos o a fracaso del manejo conservador. Descartamos B, porque la reimplantación abierta es invasiva y no está indicada en un grado II sin complicaciones. Descartamos C, porque la reimplantación laparoscópica comparte los mismos criterios de indicación que la abierta y tampoco se justifica en este escenario.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 137, "especialidad": "Urgencias", "tema": "Urgencias urológicas y vasculares periféricas", "pregunta": "Hombre de 35 años que acude a urgencias por cuadro de 48 horas de evolución de fiebre de 39°C, tiritona, mal estado general, polaquiuria, disuria, tenesmo vesical y dolor perianal. En la analítica presenta valores de creatinina de 0,9 mg/dL, procalcitonina de 1,5 ng/mL, leucocitos de 20.000/µL y PSA de 45 ng/mL. ¿Cuál es la actitud a seguir en este paciente?", "opcion_a": "Sueroterapia, antitérmicos, toma de urocultivo, antibioterapia y TC toracoabdominal.", "opcion_b": "Sueroterapia, antitérmicos y antibioterapia previa a la realización de biopsia prostática.", "opcion_c": "Sueroterapia, antitérmicos y antibioterapia durante tres semanas y repetir niveles de PSA en tres meses.", "opcion_d": "Sueroterapia, antitérmicos y antibioterapia. Solicitar niveles de fosfatasa ácida prostática.", "correcta": "C", "explicacion": "La respuesta correcta es C) Sueroterapia, antitérmicos y antibioterapia durante tres semanas y repetir niveles de PSA en tres meses: el cuadro clínico sugiere prostatitis aguda, que se trata con hidratación, control de la fiebre y antibióticos de amplio espectro durante al menos tres semanas, y una vez controlada la infección se vuelve a medir el PSA para descartar neoplasia. Descartamos A, porque la tomografía no está indicada sin sospecha de complicaciones locales. Descartamos B, porque la biopsia prostática está contraindicada durante la fase infecciosa. Descartamos D, porque la fosfatasa ácida prostática no aporta información relevante en este contexto.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 138, "especialidad": "Urgencias", "tema": "Urgencias urológicas y vasculares periféricas", "pregunta": "Una mujer acude a urgencias tres días después de ser sometido a litotricia extracorpórea por ondas de choque sobre un cálculo de 2,1 cm de diámetro máximo situado en el riñón izquierdo. Presenta mal estado general, dolor en fosa renal izquierda, náuseas y fiebre de 39,2°C. Se realiza Rx simple en la que se aprecian varios cálculos, de pequeño tamaño, en el área del uréter distal izquierdo. El radiólogo nos informa de que en la ecografía observa la existencia de dilatación grado II pielocalicial izquierda. El siguiente paso debe ser:", "opcion_a": "Ureteroscopia de urgencia dada la existencia de uropatía obstructiva de causa litiásica.", "opcion_b": "Ingreso con hidratación intravenosa, así como tratamiento antibiótico, dada la sospecha de infección urinaria.", "opcion_c": "Derivación urinaria urgente (cateterismo ureteral o nefrostomía percutánea) dada la sospecha de uropatía obstructiva complicada.", "opcion_d": "Nueva sesión de litotricia extracorpórea por ondas de choque, previo tratamiento síntomatico del paciente con antiinflamatorios, tratamiento antibiótico e hidratación intravenosa.", "correcta": "C", "explicacion": "La respuesta correcta es C) Derivación urinaria urgente (cateterismo ureteral o nefrostomía percutánea) dada la sospecha de uropatía obstructiva complicada: la paciente presenta fiebre alta, dolor lumbar y dilatación pielocalicial grado II, lo que indica una infección urinaria asociada a obstrucción, situación que requiere desobstrucción inmediata para evitar sepsis. La derivación permite drenar el sistema colector y controlar la infección antes de cualquier intervención definitiva. Descartamos A, porque la ureteroscopia no debe realizarse mientras exista infección sin drenaje previo. Descartamos B, porque solo antibiótico e hidratación no resuelven la obstrucción y el riesgo de deterioro. Descartamos D, porque la litotricia en presencia de infección y obstrucción está contraindicada.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 139, "especialidad": "Respiratorio", "tema": "Asma bronquial", "pregunta": "Una mujer de 29 años con asma moderada persistente bien controlada con fluticasona/salmeterol cada 12 horas y terbutalina a demanda descubre que está embarazada de 5 semanas. ¿Qué actitud es la más correcta?", "opcion_a": "Sustituir fluticasona/salmeterol por budesonida/formoterol.", "opcion_b": "Suspender fluticasona/salmeterol y mantener solo salbutamol a demanda.", "opcion_c": "Suspender fluticasona/salmeterol e intentar mantenimiento sólo con montelukast.", "opcion_d": "Retirar fluticasona/salmeterol e intentar mantenimiento sólo con budesonida a dosis medias.", "correcta": "D", "explicacion": "La respuesta correcta es D) Retirar fluticasona/salmeterol e intentar mantenimiento sólo con budesonida a dosis medias: en el embarazo se prefiere un corticoide inhalado de seguridad probada y con menor absorción sistémica, como la budesonida, y se evita la combinación con LABA que no está recomendada como monoterapia en gestantes; la dosis media garantiza control del asma moderada sin exponer al feto a dosis altas. Descartamos A, porque el formoterol, al igual que el salmeterol, es un LABA y su uso continuo en embarazo no está recomendado. Descartamos B, porque suspender el corticoide inhalado dejaría al asma sin control antiinflamatorio. Descartamos C, porque el montelukast no sustituye la terapia antiinflamatoria de base y su evidencia en embarazo es limitada.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 140, "especialidad": "Urgencias", "tema": "Trauma y politraumatismo", "pregunta": "Mujer de 23 años de edad que es traída a urgencias por el servicio de emergencias extrahospitalario tras accidente de tráfico con el resultado de 2 muertos y ella la única superviviente. A su llegada a nuestro centro la paciente está bajo intubación orotraqueal y hemodinámicamente estable. La exploración física nos revela lesiones contusas múltiples por todo el cuerpo, lesión sangrante en sábana sobre cuero cabelludo así como ligera hipofonesis generalizada bilateral. Auscultación cardiaca normal. Abdomen: blando y depresible sin signos de peritonismo. Resto de exploración física por aparatos normal. Se decide realizar TC cráneo-cervico-torácico-abdomino-pélvico. ¿Qué hallazgo radiológico NO sería compatible con una rotura de aorta contenida?", "opcion_a": "Derrame pleural izquierdo.", "opcion_b": "Enfisema mediastínico.", "opcion_c": "Derrame pericárdico.", "opcion_d": "Ensanchamiento mediastínico.", "correcta": "B", "explicacion": "La respuesta correcta es B) Enfisema mediastínico: este hallazgo indica presencia de aire en el mediastino, lo que se asocia más a lesiones del árbol respiratorio o esófago y no a una rotura aórtica contenida, por lo que no es compatible. Descartamos A, porque el derrame pleural izquierdo es frecuente por hemorragia secundaria a la rotura aórtica. Descartamos C, porque el derrame pericárdico puede deberse a sangrado mediado por la lesión aórtica. Descartamos D, porque el ensanchamiento mediastínico es un signo clásico de lesión aórtica traumática.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 141, "especialidad": "Respiratorio", "tema": "Insuficiencia respiratoria aguda y SDRA", "pregunta": "Dentro de la definición del síndrome de distrés respiratorio agudo (SDRA), señale la respuesta INCORRECTA:", "opcion_a": "Es debido a una alteración de la membrana capilar pulmonar.", "opcion_b": "Radiológicamente se objetivan opacidades bilaterales no explicadas por derrame pleural, atelectasia o nódulos pulmonares.", "opcion_c": "Es necesario que exista una presión de oclusión de la arteria pulmonar (POAP) > 18 mmHg.", "opcion_d": "El cociente PaO2/FiO2 debe ser menor o igual a 200 mmHg.", "correcta": "C", "explicacion": "La respuesta correcta es C) Es necesario que exista una presión de oclusión de la arteria pulmonar (POAP) > 18 mmHg: esa afirmación es falsa porque un POAP elevado indica edema pulmonar hidrostático y no la lesión no cardiogénica del SDRA, cuyo criterio es POAP ≤ 18 mmHg. Descartamos A, porque el SDRA se produce por daño de la membrana capilar pulmonar que aumenta la permeabilidad. Descartamos B, porque la definición radiológica exige opacidades bilaterales que no se expliquen por derrame pleural, atelectasia o nódulos. Descartamos D, porque el criterio de gravedad incluye un cociente PaO2/FiO2 ≤ 200 mmHg.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 142, "especialidad": "Respiratorio", "tema": "EPOC", "pregunta": "El estudio de la gravedad multifuncional de la EPOC se realiza con los índices BODEX y BODE, que tienen algunos criterios comunes. ¿Cuál de los siguientes criterios forma parte exclusivamente de uno de los dos índices?", "opcion_a": "Valoración de la disnea (MRC).", "opcion_b": "Distancia recorrida (metros).", "opcion_c": "Índice de masa corporal (IMC).", "opcion_d": "Capacidad vital forzada (FVC).", "correcta": "B", "explicacion": "La respuesta correcta es B) Distancia recorrida (metros): el índice BODE incluye la prueba de caminata de seis minutos como medida de capacidad funcional, mientras que el BODEX no la contempla; por tanto, la distancia recorrida es un criterio exclusivo del BODE. Descartamos A, porque la valoración de la disnea mediante la escala MRC está presente tanto en BODE como en BODEX. Descartamos C, porque el índice de masa corporal forma parte de los dos índices. Descartamos D, porque la capacidad vital forzada no se incluye en ninguno de los dos índices.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 143, "especialidad": "Respiratorio", "tema": "EPOC", "pregunta": "Recibe en su consulta a un varón de 65 años, ex fumador con un consumo acumulado de 50 paquetes/año y con diagnóstico de EPOC tipo enfisema. Refiere tos con poca expectoración y disnea de moderados esfuerzos. Solicita pruebas funcionales respiratorias. De los siguientes resultados, ¿cuál le parece MENOS probable?", "opcion_a": "FEV1 (flujo espiratorio en el primer segundo) menor del 80%.", "opcion_b": "DLCO (capacidad de difusión) normal.", "opcion_c": "Relación FEV1/FVC menor del 70%.", "opcion_d": "TLC (capacidad pulmonar total) aumentada.", "correcta": "B", "explicacion": "La respuesta correcta es B) DLCO (capacidad de difusión) normal: en el enfisema la destrucción de la membrana alveolo capilar reduce la difusión, por lo que una DLCO normal es poco probable. Descartamos A, porque la obstrucción típica de la EPOC disminuye el FEV1 por debajo del 80% del valor esperado. Descartamos C, porque una relación FEV1/FVC menor del 70% es el criterio diagnóstico de la enfermedad y se observa con frecuencia. Descartamos D, porque el enfisema produce hiperinsuflación y aumento del TLC, por lo que es habitual.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 144, "especialidad": "Urgencias", "tema": "Toxicología y reacciones farmacológicas", "pregunta": "Hombre de 47 años, con antecedentes de síndrome depresivo, es atendido en urgencias tras haberlo encontrado en su domicilio inconsciente. En la gasometría arterial destaca: pH 6,94; HCO3 5 mEq/L; PaCO2 17 mmHg. El anión gap o hiato aniónico es de 35 (valor normal 12 ± 2). La glucemia y la creatinina fueron normales y los cuerpos cetónicos negativos. La osmolaridad calculada reveló un valor de 295 mOsm/kg, frente a una osmolaridad medida directamente de 325 mOsm/kg. Señale la afirmación correcta:", "opcion_a": "El paciente presenta una acidosis mixta.", "opcion_b": "Debe descartarse la posibilidad de intoxicación por metanol.", "opcion_c": "Se trata de una acidosis metabólica por pérdida de bicarbonato. Hay que descartar diarreas o pérdidas renales.", "opcion_d": "Dada la disminución del bicarbonato, es ineludible su reposición inmediata con el objetivo de alcanzar, en la primera hora, sus valores plasmáticos normales.", "correcta": "B", "explicacion": "La respuesta correcta es B) Debe descartarse la posibilidad de intoxicación por metanol: la combinación de una acidosis metabólica con anión gap muy elevado, un bicarbonato extremadamente bajo y una diferencia significativa entre la osmolaridad medida y la calculada indica la presencia de un osmolar gap, hallazgo típico de intoxicaciones por alcoholes tóxicos como el metanol. Descartamos A, porque la compensación respiratoria es adecuada y no hay evidencia de una segunda alteración acidobásica. Desc\n\n\n\nDescartamos C, porque la acidosis presenta anión gap elevado y osmolar gap, lo que no ocurre en pérdidas de bicarbonato por diarrea o renales. Descartamos D, porque la prioridad es identificar y tratar la causa subyacente, y la reposición inmediata de bicarbonato no es obligatoria ni siempre segura en este contexto.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 145, "especialidad": "Respiratorio", "tema": null, "pregunta": "Una mujer de 51 años refiere disnea de esfuerzos moderados de varios meses de evolución. No tiene antecedentes de interés y la analítica elemental (hemograma y bioquímica básica) es normal. En las pruebas funcionales respiratorias, se observa una relación FEV1/FVC superior a 0,7 y una FVC y una TLC del 85% y 83% en relación a sus valores teóricos, respectivamente. La DLCO es del 40%. Ante estos datos, pensaría en:", "opcion_a": "Trastorno de la caja torácica o neuromuscular.", "opcion_b": "Enfisema.", "opcion_c": "Enfermedad pulmonar vascular.", "opcion_d": "Asma.", "correcta": "C", "explicacion": "La respuesta correcta es C) Enfermedad pulmonar vascular: la combinación de una relación FEV1/FVC normal, volúmenes pulmonares cercanos a lo esperado y una difusión de carbono monóxido muy reducida indica un daño predominantemente vascular del parénquima sin compromiso obstructivo ni restrictivo. Este patrón es típico de la enfermedad pulmonar vascular, donde la reducción de la superficie capilar disminuye la DLCO. Descartamos A, porque los trastornos de la caja torácica o neuromusculares producirían una disminución de la capacidad vital y de la capacidad total pulmonar. Descartamos B, porque el enfisema se caracteriza por una relación FEV1/FVC disminuida y suele acompañarse de hiperinsuflación. Descartamos D, porque el asma presenta una obstrucción reversible con FEV1/FVC reducido.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 146, "especialidad": "Respiratorio", "tema": "Infecciones respiratorias", "pregunta": "En un paciente diagnosticado de neumonía y con derrame pleural metaneumónico en 2/3 de hemitórax derecho, ¿cuál de las siguientes asociaciones de signos es frecuente observar?", "opcion_a": "Murmullo vesicular normal - vibraciones vocales normales-percusión mate.", "opcion_b": "Murmullo vesicular disminuido - vibraciones vocales aumentadas-percusión mate.", "opcion_c": "Estertores - vibraciones vocales aumentadas-percusión mate.", "opcion_d": "Murmullo vesicular disminuido - vibraciones vocales disminuidas-percusión mate.", "correcta": "D", "explicacion": "La respuesta correcta es D) Murmullo vesicular disminuido - vibraciones vocales disminuidas-percusión mate: en presencia de derrame pleural extenso el aire se reemplaza por líquido, lo que atenúa el murmullo vesicular y reduce las vibraciones vocales, mientras que la percusión se vuelve mate. Descartamos A, porque la percusión mate no se asocia a murmullo vesicular normal ni a vibraciones vocales normales. Descartamos B, porque el derrame pleural disminuye, no aumenta, las vibraciones vocales. Descartamos C, porque los estertores indican consolidación pulmonar, no un derrame pleural predominante.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 147, "especialidad": "Respiratorio", "tema": "Cáncer de pulmón y patología nodular", "pregunta": "En el estudio de un hombre fumador de 65 años se aprecia una masa pulmonar de 8 cm de diámetro en el lóbulo superior derecho, con afectación ganglionar hiliar ipsilateral. El paciente es diagnosticado finalmente de un adenocarcinoma pulmonar. En base a las características citadas, señale cuál de los siguientes tratamientos es el más adecuado:", "opcion_a": "Resección quirúrgica seguida de quimioterapia adyuvante.", "opcion_b": "Cirugía más radioterapia postoperatoria.", "opcion_c": "Quimioterapia neoadyuvante seguida de cirugía.", "opcion_d": "Quimiorradioterapia combinada seguida de cirugía.", "correcta": "A", "explicacion": "La respuesta correcta es A) Resección quirúrgica seguida de quimioterapia adyuvante: el adenocarcinoma de 8 cm con afectación ganglionar hiliar ipsilateral es resecable y la cirugía constituye el tratamiento curativo de elección, mientras que la quimioterapia adyuvante reduce el riesgo de recaídas. Descartamos B, porque la radioterapia postoperatoria no está indicada como complemento rutinario cuando la resección es completa. Descartamos C, porque la quimioterapia neoadyuvante no aporta beneficio adicional en un tumor que ya es quirúrgicamente resecable. Descartamos D, porque la quimiorradioterapia combinada antes de la cirugía se reserva a tumores localmente avanzados no resecables, no al caso descrito.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 148, "especialidad": "Neurología", "tema": "Hipertensión intracraneal y neurología crítica", "pregunta": "Mujer de 59 años con crisis epilépticas de reciente instauración que acude a urgencias. En la exploración presenta signos piramidales izquierdos y edema de papila. Se le realiza una RM cerebral que muestra una masa hemisférica derecha con edema, desviación de la línea media y signos de herniación tentorial. Refiere que desde hace una semana sufre dolor de cabeza que ha ido progresando en intensidad. ¿Cuál de las siguientes características asociadas a la cefalea le parece más probable en esta paciente?", "opcion_a": "Predominio matutino.", "opcion_b": "No cambia con esfuerzos.", "opcion_c": "Fotofobia.", "opcion_d": "Sonofobia.", "correcta": "A", "explicacion": "La respuesta correcta es A) Predominio matutino: en los tumores intracraneos la cefalea suele empeorar al despertar porque la presión intracraneal aumenta durante la noche y al levantarse se percibe con mayor intensidad. Además, la presencia de edema de papila y herniación sugiere aumento de presión que se manifiesta con dolor matutino. Descartamos B, porque la cefalea por masa suele variar con los cambios de presión y empeorar al acostarse. Descartamos C, porque la fotofobia es típica de cefalea primaria como migraña, no de hipertensión intracraneal. Descartamos D, porque la sonofobia también se asocia a cefaleas primarias y no a procesos de masa.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 149, "especialidad": "Neurología", "tema": "Epilepsia y crisis comiciales", "pregunta": "En una mujer con una crisis epiléptica que presenta las siguientes características clínicas: aura epigástrica, olor desagradable, desconexión del medio, automatismos motores (chupeteo, deglución, apertura y cierre de una mano) y amnesia postcrítica, ¿cuál es su sospecha diagnóstica?", "opcion_a": "Crisis generalizada no convulsiva o ausencia típica.", "opcion_b": "Epilepsia parcial contínua.", "opcion_c": "Crisis amiotónica.", "opcion_d": "Crisis parcial compleja del lóbulo temporal.", "correcta": "D", "explicacion": "La respuesta correcta es D) Crisis parcial compleja del lóbulo temporal: la presencia de aura epigástrica y olfatoria, los automatismos motores de tipo oral y manual y la amnesia postcrítica son característicos de una crisis focal que se origina en la zona mesial del lóbulo temporal. Estos hallazgos indican una afectación del lóbulo temporal y su red límbica. Descartamos A, porque una ausencia típica carece de aura y de automatismos complejos y no produce amnesia postictal. Descartamos B, porque la epilepsia parcial continua se refiere a un estado de actividad ictal sostenida, no a una crisis aislada con inicio y final claros. Descartamos C, porque la crisis amiotónica se manifiesta con pérdida brusca del tono muscular y caída, sin aura epigástrica ni automatismos.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 150, "especialidad": "Neurología", "tema": "Trastornos del movimiento", "pregunta": "Un hombre de 25 años consulta por temblor. La exploración objetiva disartria y distonía. Tiene una historia familiar de enfermedad psiquiátrica y trastornos del movimiento. ¿Qué prueba diagnóstica considera más acertada?", "opcion_a": "DATSCAN.", "opcion_b": "Estudio de conducción nerviosa.", "opcion_c": "Electroencefalograma.", "opcion_d": "Cobre en orina de 24 horas.", "correcta": "D", "explicacion": "La respuesta correcta es D) Cobre en orina de 24 horas: la combinación de temblor, disartria y distonía sugiere una enfermedad de depósito de cobre, como la enfermedad de Wilson, que se confirma mediante la medición del cobre excretado en orina de 24 h. Esta prueba es la más específica para detectar el exceso de cobre y orientar el diagnóstico y tratamiento. Descartamos A, porque el DATSCAN se utiliza para evaluar la integridad de los transportadores de dopamina en trastornos neurodegenerativos y no detecta alteraciones metabólicas de cobre. Descartamos B, porque el estudio de conducción nerviosa evalúa la función de los nervios periféricos y no aporta información sobre trastornos del movimiento de origen metabólico. Descartamos C, porque el electroencefalograma registra la actividad eléctrica cerebral y es útil en epilepsia, pero no es diagnóstico de la enfermedad de Wilson.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 151, "especialidad": "Neurología", "tema": "Neuro-oncología", "pregunta": "Un niño de 13 años presenta un cuadro subagudo de cefalea y diplopia. La exploración neurológica muestra una parálisis de la mirada vertical y la resonancia magnética una lesión captante de contraste en la región pineal que obstruye el acueducto de Silvio. El diagnóstico más probable es:", "opcion_a": "Glioblastoma.", "opcion_b": "Meduloblastoma.", "opcion_c": "Tumor de células germinales.", "opcion_d": "Meningioma.", "correcta": "C", "explicacion": "La respuesta correcta es C) Tumor de células germinales: la lesión pineal que capta contraste y bloquea el acueducto, con parálisis de la mirada vertical, es típica de los germinomas pineales, los tumores más frecuentes en adolescentes en esa zona. Descartamos A, porque el glioblastoma es raro en niños y habitualmente se localiza supratentorialmente, no en la región pineal. Descartamos B, porque el meduloblastoma se origina en el cerebelo y no forma masas en la pineal. Descartamos D, porque el meningioma es poco frecuente en la infancia y suele ser extraaxial, no una lesión pineal que cause hidrocefalia obstructiva.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 152, "especialidad": "Neurología", "tema": "Enfermedades neurodegenerativas y demencias", "pregunta": "Una mujer de 78 años presenta un cuadro clínico de amnesia episódica de 2 años de evolución al que se ha asociado en los últimos meses dificultad para el reconocimiento de caras conocidas, apraxia del vestido, anomia y desorientación temporal. La familia confirma un claro deterioro funcional en actividades instrumentales de la vida diaria respecto a su nivel previo. La paciente muestra una anosognosia muy evidente. Los estudios analíticos generales, hormonas tiroideas y vitamina B12 son normales. ¿Cuál de los siguientes hallazgos clínicos NO espería encontrar en esta situación?", "opcion_a": "Placas neuríticas y ovillos neurofibrilares en el hipocampo, corteza temporal y núcleo de Meynert como hallazgos de anatomía patológica.", "opcion_b": "Trastorno de conducta del sueño REM.", "opcion_c": "Atrofia cortical temporal medial en la resonancia magnética cerebral.", "opcion_d": "Genotipo heterocigoto ApoE 3/4.", "correcta": "B", "explicacion": "La respuesta correcta es B) Trastorno de conducta del sueño REM: en la enfermedad de Alzheimer, que concuerda con el cuadro clínico descrito, los trastornos del sueño REM no son característicos, siendo más típicos los despertares fragmentados y la disminución del sueño profundo. Por tanto, su presencia sería atípica. Descartamos A, porque la presencia de placas neuríticas y ovillos neurofibrilares en hipocampo, corteza temporal y núcleo de Meynert es patognomónica de la enfermedad de Alzheimer. Descartamos C, porque la atrofia cortical temporal medial es una alteración estructural frecuente en la resonancia magnética de pacientes con Alzheimer. Descartamos D, porque el genotipo heterocigoto ApoE 3/4 es un factor de riesgo reconocido y se observa con frecuencia en pacientes con enfermedad de Alzheimer.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 153, "especialidad": "Neurología", "tema": "Enfermedades neuromusculares y de nervio periférico", "pregunta": "Una mujer de 65 años consulta por debilidad en la mano derecha que se ha extendido en pocos meses a otros territorios musculares de ambos brazos y piernas, de predominio distal. En la exploración hay atrofia y fasciculaciones en distintos territorios metaméricos con sensibilidad conservada. Existe un signo de Babinski bilateral. ¿Cuál es la prueba diagnóstica que confirmaría el diagnóstico de sospecha?", "opcion_a": "TC cerebral.", "opcion_b": "Estudio electromiográfico.", "opcion_c": "RM cerebral.", "opcion_d": "Potenciales evocados multimodales.", "correcta": "B", "explicacion": "La respuesta correcta es B) Estudio electromiográfico: la clínica sugiere una enfermedad motoneuronal con atrofia, fasciculaciones y signo de Babinski, por lo que el EMG permite demostrar denervación y confirmar el daño de la unidad motora. Además, es la prueba de referencia para diferenciar neuropatías periféricas. Descartamos A, porque la TC cerebral no aporta información sobre la actividad muscular ni sobre la lesión de la motoneurona. Descartamos C, porque la RM cerebral tampoco evalúa la función eléctrica de los músculos. Descartamos D, porque los potenciales evocados multimodales se usan para trastornos sensoriales y de conducción, no para confirmar una enfermedad motoneuronal.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 154, "especialidad": "Neurología", "tema": "Neurología básica/fisiología", "pregunta": "Un hombre presenta en la exploración neurológica un déficit sensitivo termoalgésico en la pierna izquierda asociado a una pérdida de sensibilidad vibratoria y posicional en la pierna derecha. Al mismo tiempo presenta torpeza y pérdida de fuerza distal en la pierna derecha yun reflejo cutáneo plantar derecho en extensión. ¿Cuál de las siguientes afirmaciones es cierta?", "opcion_a": "Es un síndrome centromedular tipo siringomielia.", "opcion_b": "Es un síndrome hemimedular.", "opcion_c": "Es un patrón de lesión medular transversa.", "opcion_d": "Es un patrón de lesión bulbar lateral.", "correcta": "B", "explicacion": "La respuesta correcta es B) Es un síndrome hemimedular: la combinación de pérdida de sensibilidad termoalgésica en la pierna izquierda (tracto espinotalámico cruzado) y pérdida de sensibilidad vibratoria y posicional en la pierna derecha (tractos dorsal y propioceptivo) junto con debilidad distal y reflejo plantar extensor derecho indica una lesión que afecta a una mitad de la médula a ese nivel, es decir, un síndrome hemimedular. Esto corresponde a la afectación de la vía espinotalámica contralateral, de las columnas dorsales ipsilaterales y de la vía corticoespinal del mismo hemicordón. Descartamos A, porque la siringomielia produce un patrón central con afectación bilateral de fibras cruzadas y no explica la disociación sensitiva descrita. Descartamos C, porque una lesión medular transversa produciría déficits sensoriales y motores en ambos lados. Descartamos D, porque el síndrome bulbar lateral afecta a los nervios craneales y a la musculatura facial, no a la sensibilidad y fuerza de las piernas.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 155, "especialidad": "Neurología", "tema": "Enfermedad cerebrovascular", "pregunta": "En un hombre de 70 años, hipertenso, con una hemiplejia derecha de instauración brusca con una leve disartria, sin alteraciones en la evocación ni en la comprensión del lenguaje, ¿qué tipo de ictus cree que es más probable que haya sufrido?", "opcion_a": "Un infarto lacunar capsular izquierdo.", "opcion_b": "Un infarto silviano cortico - subcortical fronto-temporal izquierdo.", "opcion_c": "Un infarto de tronco cerebral.", "opcion_d": "Una hemorragia lenticular izquierda.", "correcta": "A", "explicacion": "La respuesta correcta es A) Un infarto lacunar capsular izquierdo: produce una hemiplejia pura con disartria leve y preserva la comprensión y la evocación del lenguaje, hallazgos típicos de una lesión en la cápsula interna. Descartamos B, porque un infarto silviano cortico‑subcortical implicaría alteraciones del lenguaje o déficits cognitivos. Descartamos C, porque un infarto de tronco cerebral suele acompañarse de signos de los nervios craneales y alteración de la conciencia. Descartamos D, porque una hemorragia lenticular suele presentar un cuadro más grave, con cefalea y posible pérdida de la conciencia.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 156, "especialidad": "Endocrinología", "tema": "Patología tiroidea", "pregunta": "Niña de 13 años intervenida por enfermedad de Hirschsprung a los 3 meses de vida. ¿Cuál de los siguientes tumores es más probable que presente?", "opcion_a": "Neuroblastoma abdominal.", "opcion_b": "Tumor de Wilms.", "opcion_c": "Nefroma mesoblástico.", "opcion_d": "Carcinoma medular de tiroides familiar.", "correcta": "D", "explicacion": "La respuesta correcta es D) Carcinoma medular de tiroides familiar: la enfermedad de Hirschsprung está asociada a mutaciones del gen RET, el mismo que predispone al carcinoma medular de tiroides familiar, por lo que la asociación es biológica y clínica; además, la aparición temprana de la enfermedad sugiere una predisposición genética subyacente. Descartamos A, porque el neuroblastoma no guarda relación genética con Hirschsprung. Descartamos B, porque el tumor de Wilms no está vinculado a alteraciones del RET. Descartamos C, porque el nefroma mesoblástico no tiene asociación conocida con esta patología.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 157, "especialidad": "Pediatría", "tema": "Nutrición, lactancia y cuidados del lactante sano", "pregunta": "La llamada \"alimentación complementaria\" o \"Beikost\", consiste en la introducción de alimentos diferentes de la leche materna o leche de formula en los niños, señale una opción incorrecta en este tipo de dieta:", "opcion_a": "A partir de los 4 meses yema de huevo", "opcion_b": "A partir de los 4 meses cereales sin gluten", "opcion_c": "A partir de los 4 meses fruta fresca", "opcion_d": "A partir de los 6 meses cereales con gluten", "correcta": "A", "explicacion": "La respuesta correcta es A) A partir de los 4 meses yema de huevo: la yema de huevo se considera un alimento potencialmente alergénico y su introducción temprana está contraindicada antes de los seis meses, por lo que no debe ofrecerse a los cuatro meses. Descartamos B, porque los cereales sin gluten pueden iniciarse a los cuatro meses según la práctica habitual. Descartamos C, porque la fruta fresca es adecuada a partir de los cuatro meses. Descartamos D, porque los cereales con gluten se introducen a los seis meses, no antes.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 158, "especialidad": "Pediatría", "tema": "Gastroenterología pediátrica — invaginación intestinal, cuadros abdominales agudos", "pregunta": "Lactante de 1 mes de vida que presenta vómitos de 24 horas de evolución. Come con apetito y llora entre las tomas. Desde el nacimiento toma biberón y no vomitaba previamente. En función de la sospecha diagnóstica más probable, ¿qué pruebas diagnósticas le parecen más adecuadas?", "opcion_a": "Es un reflujo gastro-esofágico fisiológico para su edad, es suficiente con posición semiincorporada tras las tomas.", "opcion_b": "Puede ser una gastroenteritis, haría gasometría venosa e iones y administraría rehidratación intravenosa.", "opcion_c": "Probablemente tenga una estenosis hipertrófica de píloro, le pediría una ecografía.", "opcion_d": "Hay que descartar una malformación congénita del tracto digestivo con un tránsito gastro-duodenal.", "correcta": "C", "explicacion": "La respuesta correcta es C) Probablemente tenga una estenosis hipertrófica de píloro, le pediría una ecografía: el lactante presenta vómitos persistentes desde hace 24 h, mantiene buen apetito y no hay diarrea ni signos de infección, hallazgos típicos de la estenosis hipertrófica de píloro; la ecografía permite visualizar el engrosamiento del músculo pilórico y el diámetro aumentado, confirmando el diagnóstico. Descartamos A, porque el reflujo fisiológico no produce vómitos continuos ni requiere intervención. Descartamos B, porque la gastroenteritis suele acompañarse de diarrea y deshidratación y la primera prueba no es una gasometría. Descartamos D, porque una malformación congénita del tracto digestivo como atresia duodenal se manifestaría con vómitos biliosos y signos de obstrucción más tempranos.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 159, "especialidad": "Pediatría", "tema": "Nutrición, lactancia y cuidados del lactante sano", "pregunta": "Señale qué perfil bioquímico en suero es sugerente de raquitismo por deficiencia de vitamina D en un lactante de 5 meses de edad:", "opcion_a": "Calcio normal; fosfato normal; fosfatasas alcalinas (FA) normales; hormona paratiroidea (PTH) normal; 25 OH vitamina D baja.", "opcion_b": "Calcio normal; fosfato bajo; FA normales; PTH normal; 25 OH vitamina D baja.", "opcion_c": "Calcio bajo; fosfato alto; FA elevadas; PTH normal; 25 OH vitamina D baja.", "opcion_d": "Calcio normal; fosfato normal; FA elevadas; PTH elevada; 25 OH vitamina D baja.", "correcta": "D", "explicacion": "La respuesta correcta es D) Calcio normal; fosfato normal; FA elevadas; PTH elevada; 25 OH vitamina D baja: la deficiencia de vitamina D reduce la absorción intestinal de calcio y fósforo, lo que genera una PTH secundaria elevada que mantiene la Ca sérica normal y eleva la fosfatasa alcalina. Además, la 25 OH vitamina D está disminuida y este patrón corresponde a la opción D. Descartamos A, porque la deficiencia de vitamina D no deja todos los parámetros bioquímicos normales. Descartamos B, porque la FA y la PTH deberían estar elevadas en la deficiencia de vitamina D y no normales. Descartamos C, porque la combinación de Ca bajo, fosfato alto y PTH normal es típica de hipoparatiroidismo, no de deficiencia de vitamina D.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 160, "especialidad": "Neurología", "tema": "Epilepsia y crisis comiciales", "pregunta": "Un lactante de 6 meses de edad presenta episodios de espasmos en flexión, en rachas, más frecuentemente cuando tiene somnolencia. Los padres le encuentran apagado y triste y con impresión de escasos avances en el desarrollo. En la exploración física se encuentran 7 manchas hipopigmentadas en tronco y en las extremidades. Entre los estudios complementarios realizados destaca el hallazgo en la ecocardiografía de una tumoración cardiaca aparentemente asintomática. ¿Cuál de las siguientes patologías es más probable en este niño?", "opcion_a": "Síndrome de Sturge-Weber.", "opcion_b": "Neurofibromatosis tipo 1.", "opcion_c": "Neurofibromatosis tipo 2.", "opcion_d": "Esclerosis tuberosa.", "correcta": "D", "explicacion": "La respuesta correcta es D) Esclerosis tuberosa: los espasmos en flexión en lactante, las manchas hipopigmentadas y la tumoración cardiaca (rhabdomioma) son hallazgos clásicos de esta enfermedad. Descartamos A, porque el síndrome de Sturge‑Weber se asocia a manchas vasculares faciales y leptomeningitis, no a hipopigmentación ni tumores cardiacos. Descartamos B, porque la neurofibromatosis tipo 1 presenta manchas café‑au‑lait y neurofibromas, sin los rhabdomiomas típicos. Descartamos C, porque la neurofibromatosis tipo 2 se caracteriza por schwannomas vestibulares y no por espasmos infantiles ni lesiones cutáneas hipopigmentadas.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 161, "especialidad": "Pediatría", "tema": "Neonatología y patología del recién nacido — cardiopatías congénitas, RCIU/macrosomía, síndromes congénitos", "pregunta": "En la hernia diafragmática congénita con defecto posterolateral, ¿qué alteración tiene mayor importancia fisiopatológica y clínica?", "opcion_a": "La herniación del hígado en el tórax.", "opcion_b": "La malrotación intestinal asociada.", "opcion_c": "El saco herniario peritoneal intratorácico.", "opcion_d": "La hipoplasia pulmonar y la hipertensión arterial pulmonar.", "correcta": "D", "explicacion": "La respuesta correcta es D) La hipoplasia pulmonar y la hipertensión arterial pulmonar: la compresión del pulmón en desarrollo por la hernia impide su crecimiento normal y genera una vasculatura pulmonar mal desarrollada que produce hipertensión pulmonar, condición que determina la gravedad clínica y la mortalidad. Esta combinación de hipoplasia y hipertensión es la principal causa de insuficiencia respiratoria y de la necesidad de ventilación mecánica. Descartamos A, porque la presencia del hígado en el tórax es un factor anatómico que puede agravar la compresión pero no es la causa principal de la insuficiencia respiratoria; Descartamos B, porque la malrotación intestinal es una anomalía ocasional que no influye de forma significativa en la fisiopatología respiratoria; Descartamos C, porque el saco herniario peritoneal intratorácico es simplemente una envoltura del contenido herniado y no determina la hipoplasia pulmonar ni la hipertensión.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 162, "especialidad": "Urgencias", "tema": "Urgencias urológicas y vasculares periféricas", "pregunta": "Ante un niño de 9 años con dolor testicular de 6 horas de evolución, intenso, que casi le impide caminar, sin traumatismo previo, ¿cuál es el diagnóstico más probable?", "opcion_a": "Hernia crural.", "opcion_b": "Torsión de hidátide de Morgagni.", "opcion_c": "Epididimitis.", "opcion_d": "Torsión testicular.", "correcta": "D", "explicacion": "La respuesta correcta es D) Torsión testicular: el cuadro de dolor testicular intenso de inicio súbito en un niño, sin traumatismo previo, es típico de torsión testicular, que requiere intervención urgente. La imposibilidad de caminar refuerza la sospecha. Descartamos A, porque la hernia crural se localiza por debajo del ligamento inguinal y no produce dolor testicular. Descartamos B, porque la torsión de la hidátide de Morgagni suele causar dolor menos intenso y a menudo se acompaña de un signo de la cabeza de apéndice testicular. Descartamos C, porque la epididimitis se presenta con dolor progresivo, a menudo con fiebre, y no con dolor tan agudo que impida caminar.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 163, "especialidad": "Pediatría", "tema": "Gastroenterología pediátrica — invaginación intestinal, cuadros abdominales agudos", "pregunta": "Neonato de 20 días que presenta un cuadro de regurgitaciones y vómitos desde el nacimiento. Presenta aspecto desnutrido y letárgico. Lactancia artificial desde el nacimiento. En la analítica destaca leucocitosis con desviación izquierda. Se indica dieta absoluta, perfusión glucosalina y antibióticos intravenosos. Ante la mejoría clínica se reintroduce la alimentación oral a las 48 horas que es seguida de vómitos repetidos, incoercibles, más intensos que los que presentaba al ingreso, reaparición del aspecto letárgico y las mismas alteraciones analíticas. El diagnóstico más probable de este paciente es:", "opcion_a": "Síndrome de enterocolitis inducida por proteínas de la leche de vaca.", "opcion_b": "Hernia hiatal de gran tamaño.", "opcion_c": "Sepsis grave.", "opcion_d": "Enfermedad por reflujo gastroesofágico.", "correcta": "A", "explicacion": "La respuesta correcta es A) Síndrome de enterocolitis inducida por proteínas de la leche de vaca: el neonato alimentado con fórmula presenta vómitos persistentes, deterioro clínico y leucocitosis con desviación izquierda que empeoran al reintroducir la leche, hallazgos típicos de la enterocolitis alérgica por proteínas de vaca. Descartamos B, porque una hernia hiatal no explica la leucocitosis ni la reactivación tras la reintroducción de la alimentación. Descartamos C, porque la sepsis grave no se relaciona específicamente con la reintroducción de la leche y los síntomas son más compatibles con una reacción alérgica. Descartamos D, porque el reflujo gastroesofágico no produce leucocitosis ni empeoramiento súbito al iniciar la alimentación.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 164, "especialidad": "Pediatría", "tema": "Neonatología y patología del recién nacido — cardiopatías congénitas, RCIU/macrosomía, síndromes congénitos", "pregunta": "Un recién nacido presenta al minuto del nacimiento una frecuencia cardiaca de 80 latidos por minuto, una respiración lenta e irregular, ausencia de tono muscular con flacidez generalizada, respuesta ausente al golpeo enérgico de la planta del pie y coloración rosada en el cuerpo con las extremidades azuladas. ¿Qué puntuación del test de Apgar le corresponde?", "opcion_a": "Dos puntos.", "opcion_b": "Cinco puntos.", "opcion_c": "Tres puntos.", "opcion_d": "Seis puntos.", "correcta": "C", "explicacion": "La respuesta correcta es C) Tres puntos: la frecuencia cardiaca está por debajo del umbral que otorga punto, la respiración es lenta e irregular, no hay tono muscular, no hay respuesta al estímulo y la coloración es rosada en el cuerpo con extremidades azuladas, lo que suma la puntuación indicada. Descartamos A, porque la puntuación no es tan baja. Descartamos B, porque la puntuación no alcanza la indicada en esa opción. Descartamos D, porque la puntuación no llega a la indicada.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 165, "especialidad": "Traumatología", "tema": "Ortopedia infantil", "pregunta": "Niño de 7 años de edad que acude al servicio de urgencias del hospital tras caída en unas camas elásticas colocadas en la plaza del pueblo. Presenta una deformidad evidente en el antebrazo derecho, con pulsos conservados y sensibilidad normal. ¿Qué tipo de lesión presenta el paciente?", "opcion_a": "Fractura en tallo verde de radio y cúbito.", "opcion_b": "Esguince de muñeca.", "opcion_c": "Fractura aislada de radio.", "opcion_d": "Fractura espiroidea larga de cúbito aislada.", "correcta": "A", "explicacion": "La respuesta correcta es A) Fractura en tallo verde de radio y cúbito: en niños los huesos son más flexibles y pueden romperse sin desplazamiento completo, produciéndose una fractura en tallo verde que suele afectar a ambos huesos del antebrazo tras una caída. La deformidad evidente con pulsos y sensibilidad preservados es típica de este tipo de lesión. Descartamos B, porque un esguince de muñeca no genera deformidad ósea visible. Descartamos C, porque la lesión involucra ambos huesos y no solo el radio. Descartamos D, porque una fractura espiral larga del cúbito aislada no explica la deformidad bilateral del antebrazo.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 166, "especialidad": "Reumatología", "tema": null, "pregunta": "Hombre de 80 años de edad con artritis reumatoide desde hace 10 años e hipertensión arterial. Recibe tratamiento con paracetamol, tramadol e indapamida desde hace años y en los últimos 3 meses también con prednisona 7,5 mg al día y etanercept, con buen resultado. Consulta porque desde hace 2 semanas tiene dolor invalidante de la cadera izquierda sin fiebre. Los análisis muestran 14.000 leucocitos/µL, hemoglobina 10 g/dL, PCR 50 mg/L, creatinina 1,2 mg/dL. La radiografía de pelvis es normal. Indique la actitud CORRECTA:", "opcion_a": "Es un brote de artritis reumatoide insuficientemente controlado. Debe aumentarse la dosis de prednisona o asociar un antiinflamatorio vigilando la función renal.", "opcion_b": "La leucocitosis y el tratamiento reciente con corticoides sugieren osteonecrosis aséptica de la cabeza femoral. Debe aumentarse la analgesia y asegurar descarga con bastones o encamamiento.", "opcion_c": "Requiere ingreso hospitalario por sospecha de artritis infecciosa aguda de la cadera. Debe iniciarse antibioterapia de forma precoz.", "opcion_d": "Se trata de una artritis gotosa aguda de la cadera. Debe asociarse alopurinol y aumentar la analgesia si precisa, recurriendo a opioides mayores.", "correcta": "C", "explicacion": "La respuesta correcta es C) Requiere ingreso hospitalario por sospecha de artritis infecciosa aguda de la cadera. Debe iniciarse antibioterapia de forma precoz: la combinación de dolor intenso de cadera, leucocitosis y PCR elevada en un paciente bajo corticoides sugiere una infección articular, la radiografía puede ser normal en las etapas iniciales y el retraso en el tratamiento aumenta el riesgo de daño irreversible; por ello la prioridad es la valoración hospitalaria y el inicio inmediato de antibióticos. Descartamos A, porque la clínica y los marcadores inflamatorios son más compatibles con infección que con un brote de artritis reumatoide y la dosis de prednisona ya es baja. Descartamos B, porque la necrosis aséptica se presenta de forma crónica y no se acompaña de leucocitosis ni de elevación marcada de PCR. Descartamos D, porque la artritis gotosa de cadera es extremadamente infrecuente y no explica la leucocitosis ni la respuesta inflamatoria aguda.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 167, "especialidad": "Reumatología", "tema": null, "pregunta": "Acude a su consulta una mujer de 40 años con un cuadro de inicio insidioso de 10 semanas de evolución consistente en dolor, eritema y aumento de la temperatura de las articulaciones metacarpofalángicas segunda y tercera de ambas manos y del carpo derecho. A pesar de que el dolor calma parcialmente desde que toma 3 comprimidos diarios de ibuprofeno continúa encontrándose mal. Además refiere una sensación de arenilla constante en los ojos y que éstos le lloran con frecuencia cuando sale a la calle. ¿Cuál de los siguientes síntomas es MENOS probable que se encuentre durante la anamnesis?", "opcion_a": "Rigidez en las manos de predominio matutino de más de una hora de duración.", "opcion_b": "Nódulos subcutáneos en las superficies de roce de codos, rodillas y dedos de las manos.", "opcion_c": "Astenia, anorexia y febrícula.", "opcion_d": "Dolor lumbar de ritmo inflamatorio.", "correcta": "D", "explicacion": "La respuesta correcta es D) Dolor lumbar de ritmo inflamatorio: el cuadro clínico descrito encaja con artritis reumatoide y síndrome de Sjögren, patologías que no suelen presentar compromiso lumbar inflamatorio. Descartamos A, porque la rigidez matutina prolongada es típica de la artritis reumatoide. Descartamos B, porque los nódulos subcutáneos son hallazgos frecuentes en la artritis reumatoide. Descartamos C, porque la astenia, anorexia y febrícula son síntomas sistémicos comunes en la artritis reumatoide.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 168, "especialidad": "Reumatología", "tema": "Lupus eritematoso sistémico y complicaciones", "pregunta": "Respecto a los anticuerpos anti Ro (SS-A) señale la respuesta INCORRECTA:", "opcion_a": "Se asocian con síndrome de Sjögren.", "opcion_b": "Se asocian con trombosis venosas y arteriales.", "opcion_c": "Se asocian con lupus cutáneo subagudo.", "opcion_d": "Se asocian con lupus neonatal con bloqueo cardiaco.", "correcta": "B", "explicacion": "La respuesta correcta es B) Se asocian con trombosis venosas y arteriales: los anticuerpos anti‑Ro/SS‑A están relacionados con manifestaciones cutáneas, síndrome de Sjögren y lupus neonatal, pero no con un mayor riesgo trombótico; la asociación trombótica corresponde a anticuerpos antifosfolípidos, no a anti‑Ro. Por lo tanto, la afirmación de que se asocian con trombosis es incorrecta. Descartamos A, porque los anti‑Ro son marcadores clásicos del síndrome de Sjögren y se encuentran en una alta proporción de pacientes. Descartamos C, porque el lupus cutáneo subagudo está fuertemente ligado a la presencia de anti‑Ro/SS‑A. Descartamos D, porque el paso de anticuerpos anti‑Ro a la placenta puede producir lupus neonatal con bloqueo cardíaco.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 169, "especialidad": "Reumatología", "tema": null, "pregunta": "¿Cuál de las siguientes NO es una característica propia de la fibromialgia?", "opcion_a": "Su diagnóstico es esencialmente clínico, pues no hay alteraciones de laboratorio características.", "opcion_b": "Distribución simétrica de los puntos dolorosos.", "opcion_c": "Presencia de síntomas como parestesias, alteraciones del sueño y rigidez.", "opcion_d": "Buena respuesta al tratamiento con glucocorticoides.", "correcta": "D", "explicacion": "La respuesta correcta es D) Buena respuesta al tratamiento con glucocorticoides: la fibromialgia no responde de forma significativa a los glucocorticoides, ya que su fisiopatología es de origen central y no inflamatorio, por lo que estos fármacos no mejoran los síntomas. Descartamos A, porque el diagnóstico es esencialmente clínico y no existen alteraciones de laboratorio específicas. Descartamos B, porque la distribución de los puntos dolorosos en la fibromialgia es simétrica y bilateral. Descartamos C, porque la enfermedad se asocia frecuentemente con parestesias, alteraciones del sueño y rigidez matutina.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 170, "especialidad": "Reumatología", "tema": "Espondiloartropatías", "pregunta": "Hombre diabético de 50 años de edad, con dolor raquídeo mecánico y rigidez. La exploración denota limitación de todos los movimientos de raquis lumbar y cervical. Los reactantes de fase aguda son negativos. El antígeno HLA-B27 es negativo. La radiología de pelvis es normal. La radiología de columna demuestra la presencia de puentes óseos intervertebrales gruesos y separados del raquis y en la columna lumbar sólo en el lado derecho de la misma. ¿Cuál es la primera posibilidad diagnóstica?", "opcion_a": "Espondilitis anquilosante.", "opcion_b": "Hiperostosis vertebral anquilosante.", "opcion_c": "Enfermedad de Paget.", "opcion_d": "Artropatía psoriásica.", "correcta": "B", "explicacion": "La respuesta correcta es B) Hiperostosis vertebral anquilosante: la presencia de puentes óseos intervertebrales gruesos y asimétricos, sin afectación sacroilíaca ni alteraciones en la pelvis, y con reactantes de fase aguda y HLA‑B27 negativos, es típica de esta entidad. Descartamos A, porque la espondilitis anquilosante requiere sacroilitis y suele asociarse a HLA‑B27 positivo. Descartamos C, porque la enfermedad de Paget produce remodelación ósea difusa y elevación de fosfatasa alcalina, no puentes intervertebrales aislados. Descartamos D, porque la artropatía psoriásica se asocia a psoriasis cutánea y a menudo a sacroilitis, ausentes en este caso.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 171, "especialidad": "Reumatología", "tema": "Artropatías por depósito de microcristales", "pregunta": "Un hombre de 60 años con antecedentes de litiasis renal por ácido úrico y artropatía tofácea crónica que presentó hace un año una reacción alérgica grave a alopurinol, consulta por episodios mensuales de artritis monoarticular en rodillas, tobillos y articulaciones metatarsofalángicas. En la analítica destacan uricemia de 12 mg/dL y ácido úrico en orina de 24 horas de 1.100 mg. Además de tratamiento del brote articular, ¿cuál es el tratamiento de fondo más adecuado para su artropatía?", "opcion_a": "Tratamiento con febuxostat.", "opcion_b": "Tratamiento con indometacina.", "opcion_c": "Tratamiento con benzbromarona.", "opcion_d": "Tratamiento con ejercicio, dieta estricta baja en purinas y colchicina.", "correcta": "A", "explicacion": "La respuesta correcta es A) Tratamiento con febuxostat: es un inhibidor de la xantina oxidasa que reduce la producción de ácido úrico y está indicado en pacientes con hipuricemia que no pueden usar alopurinol por alergia. Además, su eficacia es comparable o superior al alopurinol y no depende de la función renal, lo que lo hace apropiado en este caso de litiasis y alta excreción urinaria. Descartamos B, porque la indometacina es solo antiinflamatorio sintomático y no controla la hiperuricemia. Descartamos C, porque la benzbromarona actúa aumentando la excreción renal de urato y está contraindicada en pacientes con alto riesgo de litiasis por ácido úrico. Descartamos D, porque la dieta y colchicina pueden ayudar, pero no sustituyen una terapia urato‑reductora de fondo en un paciente con intolerancia al alopurinol.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 172, "especialidad": "Reumatología", "tema": "Vasculitis sistémicas", "pregunta": "Mujer de 18 años con historia de asma bronquial, que consulta ante púrpura cutánea, artralgias y edemas en miembros inferiores. Presenta elevación de reactantes de fase aguda, filtrado glomerular normal y proteinuria en rango no nefrótico. En la radiología se observa un velamiento de los senos paranasales. Los anticuerpos anti citoplasma de neutrófilos (ANCA) y anticuerpos antinucleares (ANA) son negativos. ¿Cuál es el diagnóstico más probable?", "opcion_a": "Lupus eritematoso sistémico con afectación renal.", "opcion_b": "Vasculitis tipo EGPA (granulomatosis eosinofílica con poliangeitis o síndrome de Churg-Strauss).", "opcion_c": "Púrpura de Schönlein-Henoch.", "opcion_d": "Granulomatosis con poliangeitis (enfermedad de Wegener).", "correcta": "B", "explicacion": "La respuesta correcta es B) Vasculitis tipo EGPA (granulomatosis eosinofílica con poliangeitis o síndrome de Churg-Strauss): la combinación de asma bronquial, afectación de senos paranasales, púrpura cutánea, artralgias, edema de miembros inferiores, elevación de reactantes de fase aguda y proteinuria no nefrótica con ANCA y ANA negativos es típica de EGPA. Descartamos A, porque el lupus suele presentar ANA positivos y afectación renal más marcada. Descartamos C, porque la púrpura de Schönlein-Henoch no se asocia con asma ni con compromiso sinusal. Descartamos D, porque la granulomatosis con poliangeitis suele presentar ANCA positivos y daño renal más severo.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 173, "especialidad": "Traumatología", "tema": "Fracturas y traumatismos agudos", "pregunta": "Hombre de 36 años de edad sin antecedentes de interés que tras un traumatismo de alta energía al caer de una motocicleta presenta una fractura diafisaria media de tibia, abierta, grado II de Gustilo. ¿Cuál de las siguientes maniobras o terapias es más efectiva para la prevención de la infección?", "opcion_a": "Antibioterapia inmediata intravenosa de amplio espectro.", "opcion_b": "Desbridamiento-lavado exhaustivo de la herida en quirófano con al menos 10 litros de suero fisiológico.", "opcion_c": "Estabilización urgente de la fractura mediante fijación externa y cierre precoz de la herida.", "opcion_d": "Cierre precoz de la herida con antisépticos y oxigenoterapia a dos litros por minuto.", "correcta": "B", "explicacion": "La respuesta correcta es B) Desbridamiento-lavado exhaustivo de la herida en quirófano con al menos 10 litros de suero fisiológico: la irrigación abundante elimina el tejido contaminado y reduce la carga bacteriana, y el desbridamiento quirúrgico permite retirar tejido necrótico, lo que se ha demostrado que disminuye significativamente la tasa de infección en fracturas abiertas de grado II. Descartamos A, porque la antibioterapia inmediata es necesaria pero insuficiente sin una descontaminación mecánica adecuada. Descartamos C, porque la estabilización externa y el cierre precoz no sustituyen la necesidad de una irrigación copiosa y un desbridamiento exhaustivo. Descartamos D, porque el cierre con antisépticos y oxigenoterapia no garantiza la eliminación del tejido contaminado ni la reducción de la carga bacteriana.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 174, "especialidad": "Traumatología", "tema": "Patología de hombro", "pregunta": "Mujer de 60 años, diabética insulinodependiente, que presenta omalgia derecha de predominio nocturno de varias semanas de evolución. No refiere traumatismo. En la exploración física destaca una limitación activa y pasiva de todos los arcos de movimiento del hombro. ¿Qué cuadro clínico sospecha como primera posibilidad diagnóstica?", "opcion_a": "Una tumoración maligna localizada en la epífisis proximal de húmero.", "opcion_b": "Una artritis séptica de hombro.", "opcion_c": "Una capsulitis adhesiva.", "opcion_d": "Un proceso degenerativo artrósico acromioclavicular.", "correcta": "C", "explicacion": "La respuesta correcta es C) Una capsulitis adhesiva: la paciente presenta dolor nocturno y limitación global del hombro sin antecedente traumático, hallazgos típicos de la capsulitis adhesiva, que se caracteriza por rigidez dolorosa y pérdida de movimiento activo y pasivo. Descartamos A, porque una tumoración maligna de la epífisis proximal produciría dolor localizado y a menudo masa palpable, no una rigidez global. Descartamos B, porque la artritis séptica suele acompañarse de fiebre, inflamación aguda y dolor intenso al movimiento, además de signos sistémicos. Descartamos D, porque la artrosis acromioclavicular genera dolor localizado en la articulación acromioclavicular y limitación de movimientos específicos, no una restricción completa del hombro.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 175, "especialidad": "Neurología", "tema": "Enfermedades neuromusculares y de nervio periférico", "pregunta": "Hombre de 36 años sin antecedentes personales de interés que acude al servicio de urgencias por un cuadro de aparición brusca de intenso dolor en la cara posterior del miembro inferior derecho que llega hasta el pie. En la exploración presenta: Lasègue derecho positivo a 10°, disminución de fuerza en la flexión plantar del pie derecho, hipoestesia en borde externo del pie derecho y ausencia de reflejo aquíleo derecho. La radiografía simple de columna lumbar no muestra alteraciones significativas. ¿Cuál de los siguientes es el diagnóstico más probable?", "opcion_a": "Hernia discal L1/L2.", "opcion_b": "Síndrome de cola de caballo.", "opcion_c": "Hernia discal L4/L5.", "opcion_d": "Hernia discal L5/S1.", "correcta": "D", "explicacion": "La respuesta correcta es D) Hernia discal L5/S1: la clínica de dolor intenso en la cara posterior del miembro inferior derecho que llega al pie, con debilidad en la flexión plantar, hipoestesia en el borde externo del pie y ausencia del reflejo aquíleo, es típica de compresión de la raíz S1 por una hernia discal L5/S1. Descartamos A, porque una hernia L1/L2 no produce síntomas en la pierna ni alteraciones del reflejo aquíleo. Descartamos B, porque el síndrome de cola de caballo se caracteriza por compromiso de varias raíces, con síntomas de vejiga/intestino y anestesia en silla de montar, ausentes aquí. Descartamos C, porque una hernia L4/L5 afecta la dorsiflexión y el reflejo patelar, no la flexión plantar ni el reflejo aquíleo.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 176, "especialidad": "Traumatología", "tema": "Patología de tobillo y pie", "pregunta": "Joven de 18 años, que hace 1 año presentó un esguince de tobillo derecho tratado con inmovilización. Desde entonces presenta un cuadro de dolor intenso y alodinia. Inicialmente la piel presentó un aspecto edematoso, hiperémico y caliente. En el momento de la consulta se aprecia un edema cutáneo duro, cianótico y frío. Las pruebas complementarias muestran ligera desmineralización en la extremidad afecta sin otros hallazgos de interés. ¿Qué tratamiento NO es recomendable?", "opcion_a": "Tramadol.", "opcion_b": "Amitriptilina.", "opcion_c": "Alendronato.", "opcion_d": "Celecoxib.", "correcta": "D", "explicacion": "La respuesta correcta es D) Celecoxib: no es recomendable porque los antiinflamatorios no esteroideos pueden reducir aún más la perfusión en una zona ya fría y cianótica, y no tratan la alodinia ni la pérdida ósea. Descartamos A, porque el tramadol alivia el dolor intenso y la alodinia sin comprometer la circulación. Descartamos B, porque la amitriptilina es eficaz para el dolor neuropático y la alodinia en crps. Descartamos C, porque el alendronato puede contrarrestar la desmineralización ósea y es útil en este contexto.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 177, "especialidad": "Oncología", "tema": "Tumores óseos y de partes blandas", "pregunta": "Joven de 18 años que acude a urgencias por presentar dolor e impotencia funcional en la rodilla derecha. Tras el estudio con biopsia se establece el diagnóstico de osteosarcoma osteoblástico del fémur distal. Dado el tipo de tumor y la localización, ¿qué protocolo de tratamiento se efectúa de forma habitual en la mayoría de los casos?", "opcion_a": "Amputación de la extremidad.", "opcion_b": "Quimioterapia neoadyuvante - Cirugía - Quimioterapia adyuvante.", "opcion_c": "Radioterapia y quimioterapia.", "opcion_d": "Cirugía y radioterapia.", "correcta": "B", "explicacion": "La respuesta correcta es B) Quimioterapia neoadyuvante - Cirugía - Quimioterapia adyuvante: este tumor es sensible a los agentes citotóxicos y la quimioterapia preoperatoria permite reducir su volumen y tratar micrometástasis, mientras que la resección quirúrgica local garantiza la extirpación completa del tejido tumoral; posteriormente, la quimioterapia adyuvante consolida la respuesta y disminuye la tasa de recaídas. Descartamos A, porque la amputación radical no es necesaria cuando se puede lograr una resección conservadora tras la reducción tumoral con quimioterapia. Descartamos C, porque el osteosarcoma no responde de forma eficaz a la radioterapia y esta no sustituye la cirugía. Descartamos D, porque la radioterapia no es el método de elección y la cirugía sola no aborda la enfermedad sistémica.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 178, "especialidad": "Cardiología", "tema": "Cardiopatía isquémica", "pregunta": "Se presenta en la consulta de valoración preanestésica un hombre portador de stent fármaco activo implantado hace 2 meses, en tratamiento con ácido acetilsalicílico (AAS) 300 mg/d y clopidogrel 75 mg/d y que debe someterse a una cirugía programada de extracción dentaria múltiple. Señale la mejor recomendación para mantener el equilibrio entre el riesgo trombótico y el riesgo hemorrágico de la cirugía propuesta:", "opcion_a": "Retrasar la cirugía durante 3 meses.", "opcion_b": "Mantener el tratamiento antiagregante.", "opcion_c": "Suspender el AAS y mantener el clopidogrel.", "opcion_d": "Reducir la dosis de AAS a 100 mg/día y suspender el clopidogrel hasta el día siguiente de la cirugía.", "correcta": "-", "explicacion": null, "explicacion_calidad": null, "imagen_path": null, "anulada": true, "motivo_anulacion": "Anulada en la plantilla oficial del Ministerio de Sanidad (sin respuesta correcta).", "requiere_revision": false, "motivo_revision": null}, {"numero": 179, "especialidad": "Urgencias", "tema": "Trauma y politraumatismo", "pregunta": "El triaje es un método de clasificación de pacientes que siguiendo una escala de colores nos permite establecer prioridades a la hora de asistir a un enfermo. Su uso está extendido en la urgencia hospitalaria pero también se emplea en la medicina extrahospitalaria en situaciones de desastres o accidentes con múltiples víctimas. Imagina que acudes en una UVI móvil como primer recurso interviniente en una de estas situaciones. ¿Qué harías para identificar a los pacientes más leves o verdes?", "opcion_a": "Explorar detenidamente a cada uno de los pacientes asegurándome que están conscientes y no presentan heridas visibles.", "opcion_b": "Preguntar a cada paciente cómo se encuentra y considerar verdes a los que no refieran ningún dolor.", "opcion_c": "Identificar a los que tengan una disminución del nivel de conciencia para así poder separar a los leves.", "opcion_d": "Gritar de forma clara: “aquellos que puedan caminar que me sigan” y alejarlos a una zona segura.", "correcta": "D", "explicacion": "La respuesta correcta es D) Gritar de forma clara: “aquellos que puedan caminar que me sigan” y alejarlos a una zona segura: permite separar rápidamente a los pacientes que pueden moverse sin ayuda, reduciendo la carga de trabajo y priorizando a los críticos; esta técnica es la base del método de “caminar y correr” usado en desastres masivos. Descartamos A, porque inspeccionar a todos retrasaría la clasificación y no garantiza identificar a los verdes. Descartamos B, porque depender del dolor subjetivo es poco fiable en situaciones caóticas. Descartamos C, porque la disminución del nivel de conciencia indica gravedad, no ligereza.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 180, "especialidad": "Urgencias", "tema": "Urgencias neurológicas", "pregunta": "¿Cuál de los siguientes parámetros NO forma parte de la escala de coma de Glasgow?", "opcion_a": "Apertura ocular.", "opcion_b": "Respuesta verbal.", "opcion_c": "Respuesta motora.", "opcion_d": "Reactividad pupilar.", "correcta": "D", "explicacion": "La respuesta correcta es D) Reactividad pupilar: la escala de Glasgow evalúa la apertura ocular, la respuesta verbal y la respuesta motora, pero no incluye la evaluación de la pupila, que se utiliza en otras escalas neurológicas. Por ello, la reactividad pupilar no forma parte de la puntuación. Descartamos A, porque la apertura ocular es uno de los tres componentes de la escala de Glasgow. Descartamos B, porque la respuesta verbal forma parte de la puntuación de la escala. Descartamos C, porque la respuesta motora también es un componente esencial de la escala.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 181, "especialidad": "Dermatología", "tema": "Oncología cutánea", "pregunta": "Acude a su consulta una mujer diabética con una úlcera maleolar de aproximadamente 10 años de evolución. Ha requerido curas tópicas contínuas pero la herida nunca ha terminado de cerrarse por segunda intención. Usted observa que uno de los bordes de la úlcera comienza a mamelonarse. ¿Cuál debe ser su actitud inmediata?", "opcion_a": "Ingreso hospitalario y tratamiento antibiótico por vía intravenosa.", "opcion_b": "Biopsia de la zona mamelonada.", "opcion_c": "Realizar curas con pomadas enzimáticas desbridantes.", "opcion_d": "Cobertura de la úlcera con injerto de piel.", "correcta": "B", "explicacion": "La respuesta correcta es B) Biopsia de la zona mamelonada: la aparición de un borde mamelonado en una úlcera crónica sugiere transformación neoplásica y solo la histología puede confirmar o descartar carcinoma; la biopsia permite diagnóstico precoz y tratamiento adecuado, evitando retrasos peligrosos. Descartamos A, porque la presencia de un nódulo no indica infección sistémica que justifique antibióticos intravenosos. Descartamos C, porque los desbridamientos enzimáticos no resolverán una posible neoplasia subyacente. Descartamos D, porque el injerto de piel no es apropiado sin antes confirmar la naturaleza benigna de la lesión.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 182, "especialidad": "Miscelánea", "tema": "Geriatría y polifarmacia — envejecimiento, criterios STOPP-START, anticolinérgicos, incontinencia, marcha, cuidados paliativos en mayores", "pregunta": "Los cambios fisiológicos que acontecen con el envejecimiento favorecen el desarrollo de enfermedad. Respecto a los mismos, señale la respuesta INCORRECTA:", "opcion_a": "Se produce una disminución en el número de nefronas relacionado con la edad biológica que condiciona pérdida fisiológica de función renal.", "opcion_b": "La esclerosis de los miocitos cardiacos favorece el desarrollo de insuficiencia cardiaca sistólica.", "opcion_c": "La disminución de la masa magra y aumento de grasa favorece el acúmulo de las benzodiacepinas de larga duración.", "opcion_d": "El aumento de infecciones en la edad avanzada está favorecido por la inmunosenescencia.", "correcta": "B", "explicacion": "La respuesta correcta es B) La esclerosis de los miocitos cardiacos favorece el desarrollo de insuficiencia cardiaca sistólica: La esclerosis produce fibrosis y rigidez del miocardio, lo que afecta principalmente la relajación y genera insuficiencia cardiaca diastólica, no sistólica, por lo que la afirmación es falsa. Descartamos A, porque la pérdida fisiológica de nefronas con la edad biológica reduce la masa renal y la función glomerular, un cambio normal del envejecimiento. Descartamos C, porque la mayor proporción de tejido adiposo y la menor masa magra aumentan la distribución y retención de benzodiacepinas de larga duración, favoreciendo su acumulación. Descartamos D, porque la inmunosenescencia disminuye la respuesta inmune y predispone a un mayor número de infecciones en la vejez.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 183, "especialidad": "Psiquiatría", "tema": "Psicogeriatría y trastornos cognitivos/delirium", "pregunta": "En relación al delirium o síndrome confusional agudo hospitalario en el anciano, señale la verdadera:", "opcion_a": "La demencia y la depresión previas son factores precipitantes de delirium.", "opcion_b": "Iniciar un tratamiento esteroideo es una causa potencial de delirium.", "opcion_c": "Las benzodiacepinas son los fármacos más adecuados para el tratamiento de la inversión del ciclo sueño-vigilia característico del delirium.", "opcion_d": "La movilización precoz del paciente durante la hospitalización no previene la aparición del delirium.", "correcta": "B", "explicacion": "La respuesta correcta es B) Iniciar un tratamiento esteroideo es una causa potencial de delirium: los corticoides pueden desencadenar alteraciones del estado mental, como delirium, por su efecto sobre neurotransmisores y metabolismo cerebral, y son un factor de riesgo reconocido en pacientes hospitalizados. Por tanto, iniciar un tratamiento esteroideo constituye una causa potencial de delirium. Descartamos A, porque la demencia y la depresión previas son factores predisponentes, no precipitantes, del delirium. Descartamos C, porque las benzodiacepinas no son el fármaco de elección para corregir la alteración del ciclo sueño‑vigilia y pueden empeorar el delirium. Descartamos D, porque la movilización precoz sí se ha demostrado que reduce la incidencia de delirium en pacientes hospitalizados.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 184, "especialidad": "Neurología", "tema": "Trastornos del movimiento", "pregunta": "¿Cuál de los siguientes fármacos se ha demostrado eficaz en el control de los síntomas en un paciente mayor con síndrome de piernas inquietas?", "opcion_a": "Pramipexol.", "opcion_b": "Risperidona.", "opcion_c": "Litio.", "opcion_d": "Fluoxetina.", "correcta": "A", "explicacion": "La respuesta correcta es A) Pramipexol: es un agonista dopaminérgico de alta afinidad que ha demostrado eficacia en el síndrome de piernas inquietas, especialmente en pacientes mayores, al reducir la intensidad y frecuencia de los síntomas. Además, su perfil de seguridad es aceptable en esta población. Descartamos B, porque la risperidona es un antipsicótico que puede empeorar los síntomas dopaminérgicos del síndrome. Descartamos C, porque el litio se utiliza en trastornos del ánimo y no tiene evidencia en el tratamiento del síndrome de piernas inquietas. Descartamos D, porque la fluoxetina es un inhibidor selectivo de la recaptación de serotonina y no está indicada para esta condición.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 185, "especialidad": "Oncología", "tema": "Tumores genitourinarios", "pregunta": "Hombre de 27 años diagnosticado tras una orquiectomía de carcinoma embrionario de testículo. Tras la cirugía persisten elevados los marcadores tumorales y en la TC de estadificación presenta múltiples adenopatías retroperitoneales superiores a los 3 cm. ¿Cuál es el tratamiento indicado?", "opcion_a": "Linfadenectomía retroperitoneal.", "opcion_b": "Radioterapia sobre el retroperitoneo.", "opcion_c": "Linfadenectomía retroperitoneal seguida de radioterapia.", "opcion_d": "Quimioterapia tipo BEP.", "correcta": "D", "explicacion": "La respuesta correcta es D) Quimioterapia tipo BEP: en un carcinoma embrionario testicular con marcadores tumorales persistentes y adenopatías retroperitoneales mayores de 3 cm, el manejo estándar es quimioterapia sistémica con el esquema BEP, que logra altas tasas de curación sin necesidad de cirugía local. Descartamos A, porque la resección quirúrgica de los ganglios retroperitoneales no es la primera línea en presencia de enfermedad metastásica con marcadores positivos; Descartamos B, porque la radioterapia no es eficaz ni está indicada en tumores no seminomatosos con metástasis retroperitoneales; Descartamos C, porque combinar cirugía y radioterapia no aporta beneficio adicional frente a la quimioterapia estándar.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 186, "especialidad": "Oncología", "tema": "Tumores digestivos", "pregunta": "Mujer de 65 años sin antecedentes personales de interés, intervenida de adenocarcinoma de sigma que infiltra la serosa (T4) con afectación de 2 ganglios de 35 aislados (N1). En el estudio de extensión no se evidencian metástasis a distancia (M0). ¿Cuál es el siguiente paso a realizar?", "opcion_a": "Determinar mutación de KRAS y NRAS para poder administrar un anti-EFGR en caso de no ser mutado.", "opcion_b": "Asociar al tratamiento con quimioterapia bevacizumab en caso de ser mutado.", "opcion_c": "Administrar una combinación de quimioterapia con fluorouracilo y oxaliplatino.", "opcion_d": "Realizar tratamiento con radioterapia al tener afectación ganglionar.", "correcta": "C", "explicacion": "La respuesta correcta es C) Administrar una combinación de quimioterapia con fluorouracilo y oxaliplatino: en un tumor de colon con invasión serosa (T4) y afectación ganglionar (N1) sin metástasis, la terapia adyuvante estándar es la combinación de fluorouracilo y oxaliplatino, que mejora la supervivencia global y libre de enfermedad. Este esquema constituye la base del tratamiento antes o después de la cirugía en este estadio. Descartamos A, porque la determinación de mutaciones de kras y nras se reserva para pacientes con enfermedad metastásica que requieran terapia dirigida con anti‑egfr, no para la fase adyuvante de un tumor localmente avanzado. Descartamos B, porque el bevacizumab se utiliza en combinación con quimioterapia en enfermedad metastásica y no está indicado como tratamiento adyuvante en ausencia de metástasis. Descartamos D, porque la radioterapia no es parte del manejo estándar adyuvante para cáncer de colon con afectación ganglionar, reservándose para casos de resección incompleta o tumores rectales.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 187, "especialidad": "Oncología", "tema": "Cáncer de pulmón", "pregunta": "En relación a la presencia de mutaciones en EFGR en pacientes con cáncer de pulmón no microcítico, ¿cúal de las siguientes afirmaciones es FALSA?", "opcion_a": "Son especialmente frecuentes en pacientes de raza caucásica y excepcionales en población asiática.", "opcion_b": "Se localizan mayoritariamente en los exones 19 y 21 del gen.", "opcion_c": "Son más frecuentes en adenocarcinomas, en no fumadores y en el sexo femenino.", "opcion_d": "En pacientes con estadios avanzados, el empleo de inhibidores de la tirosina kinasa (gefitinib o erlotinib), se ha mostrado superior a la quimioterapia.", "correcta": "A", "explicacion": "La respuesta correcta es A) Son especialmente frecuentes en pacientes de raza caucásica y excepcionales en población asiática: la afirmación es falsa, porque ocurre justo lo contrario: las mutaciones activadoras de EGFR son mucho más frecuentes en pacientes de origen asiático oriental que en caucásicos. Descartamos B, porque es cierto que la mayoría son deleciones del exón 19 y la mutación puntual L858R del exón 21. Descartamos C, porque es cierto que se asocian a histología de adenocarcinoma, a no fumadores y al sexo femenino. Descartamos D, porque es cierto que en estadios avanzados con mutación de EGFR los inhibidores de tirosina cinasa, como gefitinib o erlotinib, han demostrado ser superiores a la quimioterapia en primera línea.", "explicacion_calidad": "revisada", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 188, "especialidad": "Oncología", "tema": "Tumores genitourinarios", "pregunta": "Todos los siguientes fármacos se han demostrado eficaces en el tratamiento del cáncer de próstata hormono-resistente, EXCEPTO:", "opcion_a": "Docetaxel.", "opcion_b": "Abiraterona.", "opcion_c": "Enzalutamida.", "opcion_d": "Nivolumab.", "correcta": "D", "explicacion": "La respuesta correcta es D) Nivolumab: no ha demostrado eficacia en el cáncer de próstata hormono-resistente, pues los ensayos clínicos no han mostrado beneficio en supervivencia ni respuesta tumoral. Descartamos A, porque el docetaxel ha mejorado la supervivencia global en pacientes con enfermedad resistente a la castración. Descartamos B, porque la abiraterona inhibe la síntesis de andrógenos y ha demostrado prolongar la vida en este contexto. Descartamos C, porque la enzalutamida bloquea el receptor de andrógenos y ha mostrado eficacia clínica en el cáncer de próstata resistente a la castración.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 189, "especialidad": "Urgencias", "tema": "Paliativos y manejo del dolor en urgencias", "pregunta": "En relación con la agonía, señalar la respuesta INCORRECTA:", "opcion_a": "El fármaco ideal para la sedación es el midazolam.", "opcion_b": "La morfina está contraindicada en el tratamiento de la disnea porque produce depresión respiratoria.", "opcion_c": "El tratamiento estándar para los estertores premortem es la administracióin de anticolinérgicos.", "opcion_d": "En la agitación el tratamiento es el haloperidol.", "correcta": "B", "explicacion": "La respuesta correcta es B) La morfina está contraindicada en el tratamiento de la disnea porque produce depresión respiratoria: en la agonía la morfina alivia la disnea sin producir depresión respiratoria significativa cuando se administra en dosis adecuadas, y su uso está indicado para mejorar la comodidad del paciente. Además, su efecto analgésico y ansiolítico reduce la sensación de falta de aire. Descartamos A, porque el midazolam es el fármaco de elección para la sedación profunda en la fase final. Descartamos C, porque los anticolinérgicos no son el tratamiento estándar de los estertores premortem, que se manejan con opioides y benzodiacepinas. Descartamos D, porque el haloperidol es el fármaco recomendado para controlar la agitación en la fase terminal.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 190, "especialidad": "Oncología", "tema": "Cáncer de mama", "pregunta": "Mujer de 45 años diagnosticada de cáncer de mama estadio IV con metástasis óseas múltiples, en tratamiento hormonal y bifosfonatos intravenosos. Acude a su consulta refiriendo dolor óseo basal intenso (EVA=7), en varias localizaciones, sin sintomatología neurológica asociada y exacerbaciones del dolor (EVA=9) varias veces al día que le obligan a permanecer en reposo. En tratamiento con ibuprofeno (600 mg cada 8 horas) y tramadol (150 mg al día). ¿Qué tratamiento consideraría más adecuado en esta paciente para mejorar el control del dolor?", "opcion_a": "Suspender ibuprofeno y tramadol e iniciar un opioide mayor como morfina u oxicodona.", "opcion_b": "Suspender tramadol, mantener ibuprofeno e iniciar un opioide mayor como morfina u oxicodona.", "opcion_c": "Suspender ibuprofeno y tramadol e iniciar un opioide mayor como morfina u oxicodona, y a la vez tratamiento para el dolor irruptivo con fentanilo sublingual.", "opcion_d": "Suspender tramadol, mantener ibuprofeno e iniciar un opioide mayor como morfina u oxicodona, y a la vez tratamiento para el dolor irruptivo con fentanilo sublingual.", "correcta": "D", "explicacion": "La respuesta correcta es D) Suspender tramadol, mantener ibuprofeno e iniciar un opioide mayor como morfina u oxicodona, y a la vez tratamiento para el dolor irruptivo con fentanilo sublingual: la combinación de un antiinflamatorio con un opioide fuerte cubre el dolor basal y el fentanilo sublingual controla los picos de dolor, lo que se ajusta a la escalera analgésica para dolor óseo metastásico. Descartamos A, porque elimina el ibuprofeno que aporta control antiinflamatorio y no incluye tratamiento para el dolor irruptivo. Descartamos B, porque no contempla el manejo del dolor irruptivo que la paciente experimenta. Descartamos C, porque suprime el ibuprofeno privando al paciente del beneficio antiinflamatorio, aunque incluye fentanilo para el dolor irruptivo.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 191, "especialidad": "Oncología", "tema": "Farmacología oncológica", "pregunta": "Acude al domicilio de un paciente oncológico que últimamente no tiene bien controlado el dolor. En la exploración física parece que no hay evidencia de progresión tumoral, no revela ningún dato de interés de lo conocido previamente. En la anamnesis el cuidador principal manifiesta que el paciente tiene dolor a las 8 horas de haber recibido la dosis basal pautada de morfina cada 12 horas. Esta situación clínica se de-nomina:", "opcion_a": "Tolerancia.", "opcion_b": "Hiperalgesia.", "opcion_c": "Dependencia.", "opcion_d": "Ineficacia.", "correcta": "-", "explicacion": null, "explicacion_calidad": null, "imagen_path": null, "anulada": true, "motivo_anulacion": "Anulada en la plantilla oficial del Ministerio de Sanidad (sin respuesta correcta).", "requiere_revision": false, "motivo_revision": null}, {"numero": 192, "especialidad": "Urgencias", "tema": "Trauma y politraumatismo", "pregunta": "Te encuentras de viaje circulando en tu coche particular y presencias un accidente de tráfico que se ha producido justo en ese mismo momento. ¿Cuál debe ser tu primera acción?", "opcion_a": "Avisar a los servicios de emergencias (112) indicando localización y víctimas afectadas.", "opcion_b": "Proteger a los accidentados y a ti mismo, señalizando adecuadamente el lugar del accidente.", "opcion_c": "Socorrer a los accidentados evitando movilizarlos bruscamente.", "opcion_d": "Alejarte de la zona evitando que se formen aglomeraciones.", "correcta": "B", "explicacion": "La respuesta correcta es B) Proteger a los accidentados y a ti mismo, señalizando adecuadamente el lugar del accidente: la prioridad inicial es evitar nuevos peligros y garantizar la seguridad de los presentes, ya que un accidente sin señalización puede generar colisiones adicionales y dificultar la llegada de los servicios de urgencia. Señalar el lugar con triángulos de seguridad o cualquier elemento visible permite aislar la zona y facilita la intervención de los profesionales. Descartamos A, porque aunque avisar al 112 es esencial, no puede ser la primera medida antes de asegurar la zona y evitar nuevos incidentes. Descartamos C, porque socorrer sin antes proteger el entorno puede exponer a los socorristas y a los heridos a riesgos adicionales. Descartamos D, porque alejarse y evitar aglomeraciones no garantiza la seguridad ni la señalización necesaria para la correcta gestión del accidente.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 193, "especialidad": "Ética médica", "tema": "Planificación anticipada de decisiones", "pregunta": "Mujer con enfermedad neurodegenerativa en fase avanzada. Llega al servicio de urgencias del hospital con una infección respiratoria, que ha desencadenado una insuficiencia respiratoria global aguda. La paciente tiene registrada una directriz anticipada. En dichas instrucciones previas señala “que no quiere ser sometida a ventilación mecánica”. También dejó establecido que nombra como su representante a su amigo Pedro. El médico que valora a la paciente en urgencias y ha leído la directriz anticipada plantea a Pedro sus dudas sobre la misma, ya que el cuadro es agudo y potencialmente reversible tras tratamiento que incluye la ventilación mecánica, y parece que el documento está redactado pensando en una situación crónica, no en la actual. Usted considera CIERTO que:", "opcion_a": "El representante puede cambiar la directriz anticipada de la paciente, en su mejor interés.", "opcion_b": "El médico por ser una situación de urgencia no está obligado a seguir la directriz anticipada ni consultar con el representante.", "opcion_c": "El representante no puede cambiar la directriz anticipada. Su finalidad es garantizar el respeto a los valores de la paciente y el cumplimiento de la instrucción.", "opcion_d": "Los familiares directos presentes, pueden hacer una decisión de sustitución en su mejor interés, y no importa la opinión del representante.", "correcta": "C", "explicacion": "La respuesta correcta es C) El representante no puede cambiar la directriz anticipada. Su finalidad es garantizar el respeto a los valores de la paciente y el cumplimiento de la instrucción: la directriz anticipada es expresión vinculante de la voluntad del paciente y el representante solo actúa como garante de esa voluntad, no como sustituto para modificarla. Descartamos A, porque el representante no tiene autoridad para alterar la voluntad expresada por la paciente. Descartamos B, porque la urgencia no exime al médico de respetar la directiva anticipada válida. Descartamos D, porque la decisión de sustitución solo procede en ausencia de directiva, y la opinión del representante es la que debe respetarse.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 194, "especialidad": "Bioestadística", "tema": "Pruebas diagnósticas: sensibilidad, especificidad y valores predictivos", "pregunta": "El sobrediagnóstico es el fenómeno que ocurre cuando las personas son diagnosticadas de enfermedades que nunca les causarían síntomas ni les acortarían la vida, pero en cambio la alarma generada por el hallazgo les puede ocasionar consecuencias indeseables. ¿Cuál de las siguientes actuaciones se considera que es causante de sobrediagnóstico?", "opcion_a": "El cribado del cáncer de colon dirigido al segmento poblacional de 50-69 años mediante el test de sangre oculta en heces.", "opcion_b": "El cribado del cáncer de próstata en hombres sanos mediante la prueba del PSA.", "opcion_c": "Iniciar un estudio diagnóstico a las personas que acuden a la consulta por presentar microhematuria persistente.", "opcion_d": "Iniciar un estudio diagnóstico a las personas que acuden a la consulta por presentar tos crónica.", "correcta": "B", "explicacion": "La respuesta correcta es B) El cribado del cáncer de próstata en hombres sanos mediante la prueba del PSA: esta prueba detecta tumores de crecimiento lento que, en la mayoría de los casos, nunca producirían síntomas ni afectarían la supervivencia, lo que genera diagnósticos innecesarios y tratamientos potencialmente dañinos. El cribado se realiza en hombres asintomáticos sin factores de riesgo específicos, lo que incrementa la probabilidad de identificar lesiones de bajo potencial clínico. Por tanto, el PSA es un claro ejemplo de sobrediagnóstico. Descartamos A, porque el test de sangre oculta en heces está dirigido a una población de edad con riesgo probado y su objetivo es detectar lesiones que, de no tratarse, sí pueden progresar a enfermedad grave. Descartamos C, porque la microhematuria persistente es un signo de posible patología urológica significativa que justifica una investigación diagnóstica. Descartamos D, porque la tos crónica puede ser indicio de enfermedad respiratoria importante que requiere evaluación.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 195, "especialidad": "Ética médica", "tema": "Toma de decisiones al final de la vida — limitación del esfuerzo terapéutico, futilidad, sedación paliativa, retirada de soporte vital", "pregunta": "Un hombre de 75 años ingresa en el hospital porque se niega a comer y ha perdido un 30% de su peso. Tiene historia de esclerosis múltiple que ha empeorado en los últimos meses. Vive en residencia desde hace 15 años. Su único familiar era su hermana que murió hace 3 meses y desde entonces es cuando él se ha deteriorado. Se ha vuelto incontinente, ha dejado de comer y de participar en eventos sociales. Impresiona de depresión psicótica. Físicamente es capaz de comer. Se inicia medicación psicotropa que se suspende por eventos adversos. Si su estado nutricional mejora, es posible retomar sus medicaciones. Rechaza líquidos intravenosos y luego los acepta pero se arranca la vía IV unas horas más tarde. Una alternativa es realizar una gastrostomía endoscópica percutánea (PEG) y darle el alta a su residencia. ¿Cuál de las siguientes actuaciones es la más apropiada para este paciente?", "opcion_a": "Solicitar a la comisión de ética del hospital que ayude a determinar la decisión que sea de mayor interés para el paciente.", "opcion_b": "Valorar si la residencia acoge al paciente si no se realiza la PEG.", "opcion_c": "Pedir una orden judicial para realizar la PEG.", "opcion_d": "Enrolar al paciente en cuidados paliativos terminales.", "correcta": "A", "explicacion": "La respuesta correcta es A) Solicitar a la comisión de ética del hospital que ayude a determinar la decisión que sea de mayor interés para el paciente: la situación presenta conflicto entre la voluntad del paciente, la falta de consenso familiar y la complejidad clínica, por lo que la comisión de ética puede aportar una valoración multidisciplinar y guiar la decisión respetando la autonomía y el principio de beneficencia. Descartamos B, porque la admisión de la residencia no resuelve el dilema ético ni la necesidad de una decisión informada. Descartamos C, porque no existe indicio de incapacidad legal que justifique una orden judicial y la medida sería desproporcionada. Descartamos D, porque el paciente no se encuentra en fase terminal clara y la intervención paliativa no aborda la cuestión de la nutrición artificial.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 196, "especialidad": "Ética médica", "tema": "Consentimiento informado y capacidad de decisión — competencia, situaciones de urgencia/incapacidad", "pregunta": "¿Por qué es necesario obtener un consentimiento informado de procedimientos diagnósticos y terapéuticos?", "opcion_a": "Es un requisito legal que exime al médico de cualquier responsabilidad.", "opcion_b": "Supone una toma de decisión compartida después de informar al paciente del procedimiento.", "opcion_c": "Da libertad al médico para realizar nuevos procedimientos.", "opcion_d": "Permite determinar si el paciente es capaz de tomar decisiones.", "correcta": "B", "explicacion": "La respuesta correcta es B) Supone una toma de decisión compartida después de informar al paciente del procedimiento: el consentimiento informado garantiza que el paciente conozca los riesgos, beneficios y alternativas y participe activamente en la elección, respetando su autonomía y la ética clínica. Descartamos A, porque no se trata simplemente de un requisito legal que elimine la responsabilidad del médico. Descartamos C, porque el consentimiento no otorga libertad al profesional para realizar cualquier procedimiento sin justificación. Descartamos D, porque aunque la capacidad del paciente es evaluada, el objetivo principal del consentimiento es la decisión compartida, no solo la valoración de la capacidad.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 197, "especialidad": "Dermatología", "tema": "Oncología cutánea", "pregunta": "Señale la variable de la que dependerá, funda-mentalmente, la decisión sobre los márgenes quirúrgicos en el tratamiento de un caso de melanoma cutáneo:", "opcion_a": "Diámetro mayor de la lesión, en milímetros.", "opcion_b": "Máximo espesor de la lesión, en milímetros (índice de Breslow).", "opcion_c": "Presencia de ulceración en la lesión.", "opcion_d": "Mitosis por milímetro cuadrado (índice mitótico).", "correcta": "B", "explicacion": "La respuesta correcta es B) Máximo espesor de la lesión, en milímetros (índice de Breslow): el espesor tumoral es el factor principal que determina la extensión del tejido sano que se debe resecar para garantizar márgenes libres y está directamente relacionado con el riesgo de metástasis; por ello las guías establecen márgenes quirúrgicos basados en el grosor de Breslow. Descartamos A, porque el diámetro clínico no refleja la profundidad invasiva del melanoma; Descartamos C, porque la ulceración afecta al pronóstico pero no al cálculo del margen quirúrgico; Descartamos D, porque el índice mitótico indica agresividad pero no determina la distancia de resección requerida.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 198, "especialidad": "Dermatología", "tema": "Manifestaciones cutáneas de enfermedad sistémica", "pregunta": "Un hombre de 74 años acude a su consulta por presentar síndrome constitucional con pérdida de 5 kilos de peso en el último mes, junto a astenia. Refiere que en las tres últimas semanas, además, ha observado la aparición de lesiones rojizas en piernas que en ocasiones drenan un material oleoso, asociándose también dolor abdominal y costal, así como dolor y rubor en tobillos y rodillas. Usted decide realizar una biopsia y observa que en el tejido celular subcutáneo aparecen \"células fantasma\". Las manifestaciones clínicas del paciente y este hallazgo de la biopsia cutánea le llevará a realizar una de las siguientes pruebas para hacer el diagnóstico definitivo:", "opcion_a": "Endoscopia digestiva: adenocarcinoma gástrico.", "opcion_b": "TC abdominal: cáncer de páncreas.", "opcion_c": "TC torácico: sarcoidosis ganglionar (síndrome de Löfgren).", "opcion_d": "Cultivo de los nódulos cutáneos: tuberculosis cutánea (lupus vulgar).", "correcta": "B", "explicacion": "La respuesta correcta es B) TC abdominal: cáncer de páncreas: la presencia de pérdida de peso, dolor abdominal y costal, lesiones cutáneas rojizas con drenaje oleoso y células fantasma en tejido subcutáneo sugiere una neoplasia pancreática con metástasis cutáneas de tipo necroinflamatorio. El hallazgo de células fantasma es típico de la necrosis grasa asociada a adenocarcinoma pancreático, por lo que la TC abdominal es la prueba indicada para confirmar el diagnóstico. Descartamos A, porque la endoscopia digestiva busca un tumor gástrico que no explica las células fantasma ni el patrón de dolor costal. Descartamos C, porque la sarcoidosis no produce células fantasma ni drenaje oleoso en lesiones cutáneas. Descartamos D, porque la tuberculosis cutánea no se asocia a células fantasma y el cuadro clínico no sugiere infección.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 199, "especialidad": "Oftalmología", "tema": null, "pregunta": "Ante un traumatismo directo sobre la región orbitaria, señale la respuesta correcta:", "opcion_a": "Es frecuente el atrapamiento del nervio óptico provocando clínicamente diplopia.", "opcion_b": "Puede producirse un estallido del suelo orbitario con clínica de diplopia y enoftalmos.", "opcion_c": "Frecuentemente se produce una fractura maxilofacial tipo Le Fort-I.", "opcion_d": "Existe un riesgo muy elevado de estallido del globo ocular.", "correcta": "B", "explicacion": "La respuesta correcta es B) Puede producirse un estallido del suelo orbitario con clínica de diplopia y enoftalmos: el traumatismo directo sobre la órbita puede romper el suelo orbital, desplazando los músculos extraoculares y provocando diplopía y enoftalmos, mientras que el globo ocular suele permanecer intacto. Este mecanismo es típico de las fracturas de piso orbital y explica la combinación de signos descritos. Descartamos A, porque el nervio óptico no se atrapa en este tipo de lesión y la diplopía se origina por alteración muscular, no óptica. Descartamos C, porque las fracturas de Le Fort I son maxilofaciales y no se asocian directamente con el suelo orbital. Descartamos D, porque el riesgo de ruptura del globo ocular es bajo en un traumatismo directo aislado de la órbita.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 200, "especialidad": "Oftalmología", "tema": "Glaucoma — ángulo cerrado, tensión normal, crónico", "pregunta": "Hombre de 67 años de edad, diabético y asmático, con un glaucoma primario de ángulo abierto en ambos ojos. Presenta una presión ocular de 34 mmHg en su ojo derecho y 31 mmHg en su ojo izquierdo. ¿Cuál de los siguientes grupos farmacológicos es el más indicado como primera elección como tratamiento hipotensor?", "opcion_a": "Inhibidores de la anhidrasa carbónica.", "opcion_b": "Beta-bloqueantes.", "opcion_c": "Agonistas alfa-2.", "opcion_d": "Derivados de prostaglandinas.", "correcta": "D", "explicacion": "La respuesta correcta es D) Derivados de prostaglandinas: son los fármacos más eficaces para reducir la presión intraocular en glaucoma de ángulo abierto, actúan aumentando el flujo de salida del humor acuoso y su efecto se mantiene con una única dosis diaria, lo que favorece la adherencia. Descartamos A, porque los inhibidores de la anhidrasa carbónica son menos potentes y se reservan como terapia complementaria; Descartamos B, porque los beta bloqueantes pueden empeorar el asma del paciente y su efecto hipotensor es inferior; Descartamos C, porque los agonistas alfa-2 tienen menor eficacia y pueden producir efectos sistémicos indeseables.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 201, "especialidad": "Psiquiatría", "tema": "Psicofarmacología, efectos adversos y tratamientos biológicos", "pregunta": "Mujer de 26 años de edad con esquizofrenia que acude a la consulta de salud mental después de una hospitalización reciente por una descompensación psicótica. Tras permanecer ingresada 22 días es dada de alta la semana previa a la revisión actual. La familia refiere que la encuentran muy intranquila y con gran inquietud psicomotriz. En la exploración se evidencia que no puede permanecer sentada y está contínuamente dando vueltas por la consulta sin un propósito concreto. No se objetivan los síntomas psicóticos positivos que motivaron su ingreso, desde que en el hospital ajustaron su tratamiento con 15 mg de haloperidol al día. El diagnóstico de la situación que presenta la paciente es:", "opcion_a": "Trastorno de ansiedad generalizada.", "opcion_b": "Ansiedad secundaria a descompensación psicótica.", "opcion_c": "Acatisia.", "opcion_d": "Trastorno por déficit de atención e hiperactividad.", "correcta": "C", "explicacion": "La respuesta correcta es C) Acatisia: la paciente presenta inquietud motora intensa, incapacidad para permanecer sentada y marcha sin objetivo, hallazgos típicos de acatisia inducida por antipsicóticos, especialmente tras aumento de haloperidol. No se observan síntomas de ansiedad ni de reactivación psicótica y la sintomatología no corresponde a déficit de atención. Descartamos A, porque la inquietud no está acompañada de preocupación constante ni de síntomas cognitivos típicos de trastorno de ansiedad generalizada. Descartamos B, porque los síntomas psicóticos están controlados y la agitación es motora, no una respuesta ansiosa a la psicosis. Descartamos D, porque la hiperactividad no se asocia a déficit de atención ni a síntomas de trastorno por déficit de atención e hiperactividad.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 202, "especialidad": "Psiquiatría", "tema": "Trastorno bipolar y estabilizadores del ánimo", "pregunta": "Para el tratamiento de la manía aguda están aprobados por la FDA los siguientes antipsicóticos, EXCEPTO:", "opcion_a": "Olanzapina.", "opcion_b": "Clozapina.", "opcion_c": "Aripiprazol.", "opcion_d": "Ziprasidona.", "correcta": "B", "explicacion": "La respuesta correcta es B) Clozapina: la clozapina no está aprobada por la FDA para el tratamiento de la manía aguda, su indicación está limitada al trastorno esquizofrénico resistente y a episodios de manía refractaria bajo estricta vigilancia. Descartamos A, porque la olanzapina cuenta con indicación aprobada para la manía aguda. Descartamos C, porque el aripiprazol está autorizado para el manejo de episodios maníacos. Descartamos D, porque la ziprasidona también tiene aprobación para la manía aguda.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 203, "especialidad": "Psiquiatría", "tema": "Esquizofrenia y otros trastornos psicóticos", "pregunta": "Mujer de 55 años, casada y con dos hijos de 25 y 20 años de edad. Acude a la consulta de salud mental por problemas en el entorno familiar. La paciente refiere encontrarse mal, triste y preocupada por \"los disgustos que me da el marido\". Lo ha visto abrazado a otra mujer y afirma que \"él está en su contra y que la engaña porque se preocupa demasiado por sus hijos\". Tanto el marido como los hijos desmienten esa información dada por la paciente. Sin antecedentes médicos no psiquiátricos a destacar, presenta una exploración psicopatológica de lucidez con buen nivel de conciencia y de orientación en las 3 esferas. Presenta hipotimia discreta de meses de evolución. Alteración del contenido del pensamiento en forma de ideas delirantes de corte celotípico y de perjuicio con fenómenos autorreferenciales. No existe alteración de la esfera sensoperceptiva. No presenta ideación autolítica. Mantiene un adecuado ritmo cognitivo y conserva los ritmos biológicos de sueño y apetito. ¿Cuál es el diagnóstico que se ajusta más al cuadro clínico que presenta la paciente?", "opcion_a": "Esquizofrenia paranoide.", "opcion_b": "Trastorno depresivo mayor con características psicóticas.", "opcion_c": "Trastorno paranoide la de personalidad.", "opcion_d": "Trastorno delirante.", "correcta": "D", "explicacion": "La respuesta correcta es D) Trastorno delirante: la paciente muestra ideas delirantes de tipo celotípico y de persecución con buen nivel de conciencia, sin alteración sensoperceptiva ni síntomas negativos prominentes, y la duración es de varios meses, lo que encaja con trastorno delirante. Descartamos A, porque la esquizofrenia paranoide requiere al menos otro síntoma positivo como alucinaciones o deterioro funcional significativo, que no se observa. Descartamos B, porque aunque hay hipotimia, no se cumplen los criterios de depresión mayor ni hay síntomas psicóticos congruentes con el estado de ánimo. Descartamos C, porque el trastorno de personalidad paranoide es un patrón estable y no se presenta con ideas delirantes fijas y aisladas como en este caso.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 204, "especialidad": "Psiquiatría", "tema": "Trastornos de ansiedad", "pregunta": "¿Cuál es la orientación diagnóstica ante un hombre de 35 años sin antecedentes médicos que acude a consulta explicando temores insuperables a entrar en lugares concurridos tras haber experimentado hace un mes, al entrar en un centro comercial, un episodio agudo de ansiedad con síntomas somáticos (taquicardia, sudores, disnea...)?", "opcion_a": "Trastorno por estrés anticipatorio.", "opcion_b": "Fobia de impulsión evitativa.", "opcion_c": "Trastorno obsesivo.", "opcion_d": "Trastorno por angustia con agorafobia.", "correcta": "D", "explicacion": "La respuesta correcta es D) Trastorno por angustia con agorafobia: el paciente presenta un episodio de ansiedad intensa con síntomas somáticos que se desencadenó en un lugar público y ahora evita esos entornos por temor a un nuevo ataque, lo que corresponde a un trastorno de pánico con agorafobia. Descartamos A, porque la denominación no corresponde a una entidad diagnóstica reconocida y no explica la evitación de lugares concurridos tras un ataque. Descartamos B, porque la fobia de impulsión evitativa no se ajusta a la presencia de ataques de pánico y la evitación está motivada por el miedo a los síntomas, no a la impulsión. Descartamos C, porque no existen obsesiones ni compulsiones que caractericen un trastorno obsesivo.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 205, "especialidad": "Psiquiatría", "tema": "Trastornos de ansiedad", "pregunta": "Una estudiante de Medicina de 22 años, con antecedentes familiares en el mismo sentido de su malestar, consulta por temor, desde la infancia, a la observación de escenas que contengan sangre o daño físico, lo cual provoca desmayo con pérdida de conciencia y caída al suelo, con recuperación completa en escasos minutos. ¿Cuáles son la orientación diagnóstica y actitud terapéutica correctas?", "opcion_a": "Padece un trastorno conversivo y requiere psicoterapia analítica.", "opcion_b": "Padece una agorafobia y requiere tratamiento con inhibidores de la monoaminooxidasa.", "opcion_c": "Padece una fobia simple y requiere tratamiento cognitivo-conductual.", "opcion_d": "Padece una fobia específica y no requiere tratamiento.", "correcta": "C", "explicacion": "La respuesta correcta es C) Padece una fobia simple y requiere tratamiento cognitivo-conductual: la paciente presenta miedo intenso y evitación de estímulos sanguíneos que desencadenan síncope, lo que corresponde a una fobia específica dentro del espectro de fobias simples y el abordaje de primera línea es la terapia cognitivo-conductual con exposición gradual. Descartamos A, porque el cuadro no muestra síntomas de conversión ni conflicto inconsciente. Descartamos B, porque no hay evitación de lugares o situaciones amplias ni indicación de inhibidores de la monoaminooxidasa. Descartamos D, porque aunque sea una fobia específica, el tratamiento está indicado para evitar la discapacidad y el sufrimiento.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 206, "especialidad": "Pediatría", "tema": "Neurodesarrollo y salud mental infantil — TEA, desarrollo psicomotor", "pregunta": "Unos padres acuden a consulta preocupados por la situación de su hijo que va a repetir 4º de Educación Primaria Obligatoria (EPO). En el colegio se quejan de su comportamiento, pero no han realizado ninguna intervención. Los padres se sienten culpables porque han retrasado la petición de ayuda por los problemas de salud de la hermana. Hace 2 años la diagnostican de leucemia y han estado centrados en su tratamiento que ha evolucionado positivamente. Manifiestan que su hijo tiene problemas con los compañeros por su carácter, es muy inquieto y distraído, no acepta perder y se altera cuando no gana. Los problemas los tuvo de siempre, pero aumentan al iniciar EPO, y la profesora siempre les ha dicho que era vago pero que era capaz, quitándole importancia. ¿Cómo orientarías este caso?", "opcion_a": "Realizaría el diagnóstico de trastorno por déficit de atención e hiperactividad (TDAH) y le pondría tratamiento con metilfenidato.", "opcion_b": "Analizaría la dinámica familiar para trabajar los problemas derivados de la enfermedad en la hermana y lo que esto había supuesto en el comportamiento del niño.", "opcion_c": "Intervendría con el colegio para que aporte información del posible acoso escolar.", "opcion_d": "Tendría una entrevista con el niño y solicitaría información escolar.", "correcta": "D", "explicacion": "La respuesta correcta es D) Tendría una entrevista con el niño y solicitaría información escolar: es fundamental obtener la perspectiva del propio niño y recabar datos objetivos del entorno escolar para valorar si los problemas son de conducta, atención o adaptación y orientar la intervención. Descartamos A, porque el diagnóstico de TDAH requiere una evaluación completa y no se puede prescribir metilfenidato sin información escolar y clínica previa. Descartamos B, porque aunque la dinámica familiar es relevante, el primer paso es valorar directamente al niño y su desempeño escolar antes de intervenir en la familia. Descartamos C, porque la información sobre posible acoso escolar se obtiene a través de la entrevista y la solicitud de datos al centro, no como única intervención.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 207, "especialidad": "Psiquiatría", "tema": "Trastornos de la conducta alimentaria", "pregunta": "Mónica es una chica de veinte años que es llevada al servicio de urgencias por sus padres porque ya no saben qué hacer con ella. Desde hace unos tres años está obsesionada con su silueta y parece que todo lo juzga en base al aspecto físico, infravalorando otras cualidades personales que tiene y que todos reconocen. Desde hace unos cinco meses presenta además episodios que le hacen sentirse muy mal y que describe como incontrolables, consistentes en la ingesta de cantidades enormes de comida en muy poco tiempo. Esto le ha venido ocurriendo cada vez con más frecuencia llegando a ocurrirle entre dos y tres veces por semana los últimos 3 meses. Cuenta por ejemplo que anoche ingirió cuatro paquetes de galletas en una hora y media tras lo que, como habitualmente suele hacer, al no poder soportar el sentimiento de culpa se ha provocado el vómito, expulsando así la mayor parte de lo ingerido. En ésta paciente sería mucho más IMPROBABLE encontrar una de las siguientes características, señálela:", "opcion_a": "Acidosis metabólica con hipercloremia.", "opcion_b": "Conductas de ayuno.", "opcion_c": "Antecedentes de conductas impulsivas como consumo de alcohol o comportamientos autolesivos de baja letalidad.", "opcion_d": "Niveles de amilasa séricos elevados.", "correcta": "A", "explicacion": "La respuesta correcta es A) Acidosis metabólica con hipercloremia: en la bulimia nerviosa el vómito repetido produce pérdida de ácido clorhídrico, lo que genera una alcalosis metabólica con hipocloremia, no una acidosis con hipercloremia. Descartamos B, porque la paciente presenta episodios de ingesta masiva seguidos de purga, no ayuno prolongado típico de la anorexia. Descartamos C, porque la impulsividad y conductas autolesivas son frecuentes en los trastornos bulímicos. Descartamos D, porque la hiperamilasemia es un hallazgo típico tras episodios de vómito repetido.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 208, "especialidad": "Ética médica", "tema": "Menores, incapacidad y decisiones de terceros — donación de órganos en menores, decisiones familiares", "pregunta": "Señale la respuesta correcta sobre los ensayos clínicos con medicamentos en menores:", "opcion_a": "Son legalmente posibles y éticamente aceptables, pero el investigador debe respetar el deseo explícito del menor de negarse a participar en el ensayo, siempre que éste sea capaz de formarse una opinión.", "opcion_b": "Son legalmente posibles y éticamente aceptables y únicamente requieren la autorización de los padres o tutores legales.", "opcion_c": "Son legalmente posibles y éticamente aceptables, siempre que el niño tenga 12 años o más.", "opcion_d": "Son legalmente posibles pero no son éticos, dado que los niños no tienen capacidad para consentir con la investigación.", "correcta": "A", "explicacion": "La respuesta correcta es A) Son legalmente posibles y éticamente aceptables, pero el investigador debe respetar el deseo explícito del menor de negarse a participar en el ensayo, siempre que éste sea capaz de formarse una opinión: esta posición se sustenta en la normativa que reconoce el derecho del menor a expresar su asentimiento y a ser escuchado cuando posee la madurez suficiente; la negativa del menor debe ser respetada aun cuando cuente con la autorización de los padres. Descartamos B, porque la autorización parental no es suficiente sin considerar la voluntad del menor. Descartamos C, porque no existe una edad fija como criterio único para la participación. Descartamos D, porque la legislación permite la investigación siempre que se respeten los requisitos éticos y la capacidad de decisión del menor.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 209, "especialidad": "Bioestadística", "tema": "Ensayos clínicos y fases de investigación", "pregunta": "Un ensayo clínico no mostró diferencias significativas entre el nuevo fármaco tromboporix y placebo en la incidencia de infarto de miocardio (7% versus 5%; p = 0,68) en la población total del estudio, pero sí mostró que tromboporix reducía el riesgo de infarto en uno de los 20 subgrupos analizados, concretamente en mayores de 55 años (3% versus 8%; p = 0,048). Señale lo CIERTO:", "opcion_a": "El resultado significativo en el subgrupo descarta razonablemente un error de tipo I.", "opcion_b": "Puede ser útil para plantear nuevas hipótesis, que deberán ser comprobadas en nuevos ensayos diseñados a tal fin.", "opcion_c": "El error de tipo II puede ser el causante de la significación estadística en dicho subgrupo.", "opcion_d": "El resultado obtenido en el subgrupo es un ejemplo de la denominada paradoja de Brawnwald.", "correcta": "B", "explicacion": "La respuesta correcta es B) Puede ser útil para plantear nuevas hipótesis, que deberán ser comprobadas en nuevos ensayos diseñados a tal fin: el hallazgo significativo en un único subgrupo tras múltiples comparaciones sugiere una posible señal que requiere confirmación, pero no constituye evidencia definitiva por el riesgo de hallazgos espurios. Descartamos A, porque un resultado significativo en un subgrupo no elimina la posibilidad de un error de tipo I derivado de pruebas múltiples. Descartamos C, porque el error de tipo II se relaciona con falta de potencia y no explica la aparición de significación en un subgrupo. Descartamos D, porque no existe una paradoja conocida como la de Brawnwald en este contexto.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 210, "especialidad": "Bioestadística", "tema": "Ensayos clínicos y fases de investigación", "pregunta": "En relación con los ensayos clínicos fase III realizados en oncología, señale la respuesta verdadera:", "opcion_a": "Suele emplearse como variable principal la tasa de respuestas, pues se considera clínicamente relevante en cualquier circunstancia.", "opcion_b": "En tumores frecuentes, como por ejemplo cáncer de colon, los ensayos clínicos fase III de registro suelen ser ensayos clínicos no controlados.", "opcion_c": "Cuando se conoce la existencia de factores pronósticos importantes del tipo de cáncer en estudio, es recomendable estratificar la aleatorización para asegurar una distribución equitativa de estos factores.", "opcion_d": "Deben emplearse criterios de inclusión muy estrictos que excluyan determinados tipos de pacientes (por ejemplo pacientes de edad avanzada), pues así se generalizarán los resultados más fácilmente.", "correcta": "C", "explicacion": "La respuesta correcta es C) Cuando se conoce la existencia de factores pronósticos importantes del tipo de cáncer en estudio, es recomendable estratificar la aleatorización para asegurar una distribución equitativa de estos factores: la estratificación permite equilibrar los grupos respecto a variables que influyen en la supervivencia o la respuesta, evitando sesgos y aumentando la potencia estadística. Descartamos A, porque la tasa de respuesta no siempre refleja beneficio clínico y en fase III se prioriza la supervivencia global o libre de progresión. Descartamos B, porque los ensayos fase III de registro en tumores frecuentes son estudios controlados y aleatorizados, no ensayos no controlados. Descartamos D, porque criterios de inclusión excesivamente estrictos reducen la generalizabilidad y pueden excluir a pacientes mayores que forman parte de la práctica clínica.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 211, "especialidad": "Bioestadística", "tema": "Diseños de estudios epidemiológicos: cohortes, casos-control y transversales", "pregunta": "En el año 2000, unos investigadores suecos realizaron un estudio para conocer si el consumo de cannabis aumentaba el riesgo de esquizofrenia. Para ello identificaron a 50.087 hombres que formaron parte del reclutamiento militar obligatorio entre 1969 y 1970. Como parte del proceso de reclutamiento se les hacía una entrevista donde, de forma no anónima, indicaban el consumo de cannabis. A este grupo se les siguió desde 1970 a 1996 a través de los registros hospitalarios para conocer cuántos de ellos tenían registrado durante ese periodo un diagnóstico de esquizofrenia. Para el análisis dividieron a los sujetos en dos grupos: los que indicaron que habían consumido cannabis 2 o más veces y los que consumieron cannabis menos de 2 veces y calcularon la frecuencia de esquizofrenia en cada uno de ellos. ¿De qué tipo de estudio epidemiológico se trata?", "opcion_a": "Estudio de cohorte.", "opcion_b": "Estudio de casos y controles.", "opcion_c": "Estudio de corte transversal retrospectivo.", "opcion_d": "Ensayo clínico no aleatorizado.", "correcta": "A", "explicacion": "La respuesta correcta es A) Estudio de cohorte: los investigadores seleccionaron a los participantes antes de que se presentara la enfermedad, registraron su consumo de cannabis y los siguieron a lo largo del tiempo para observar la aparición de esquizofrenia. Este diseño permite estimar la incidencia del trastorno según la exposición. Descartamos B, porque en un estudio de casos y controles los sujetos se eligen por tener o no la enfermedad y no se sigue una cohorte. Descartamos C, porque un estudio transversal mide exposición y enfermedad simultáneamente sin seguimiento temporal. Descartamos D, porque no se asignó ninguna intervención ni se comparó un tratamiento experimental.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 212, "especialidad": "Bioestadística", "tema": "Diseños de estudios epidemiológicos: cohortes, casos-control y transversales", "pregunta": "En un estudio epidemiológico de cohortes, ¿qué entendemos por pacientes expuestos?", "opcion_a": "Pacientes que tienen el factor de riesgo de la enfermedad o problema de salud que queremos estudiar.", "opcion_b": "Pacientes que aceptan participar en el estudio tras otorgar su consentimiento informado.", "opcion_c": "Sujetos que no desarrollan la enfermedad o problema de salud en estudio durante el seguimiento.", "opcion_d": "Pacientes que tienen la enfermedad o problema de salud que queremos estudiar.", "correcta": "A", "explicacion": "La respuesta correcta es A) Pacientes que tienen el factor de riesgo de la enfermedad o problema de salud que queremos estudiar: en un estudio de cohortes se parte de grupos definidos por la presencia o ausencia del factor de exposición y se sigue su evolución para observar la aparición de la enfermedad; por tanto los expuestos son aquellos que poseen el factor de riesgo bajo estudio. Descartamos B, porque la aceptación del consentimiento no define la exposición al factor de riesgo. Descartamos C, porque describe a los no casos o a los que no desarrollan la enfermedad, no a los expuestos. Descartamos D, porque los pacientes con la enfermedad ya son los casos y no forman parte del grupo de exposición inicial.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 213, "especialidad": "Bioestadística", "tema": "Diseños de estudios epidemiológicos: cohortes, casos-control y transversales", "pregunta": "El servicio de dermatología de un hospital ha registrado durante los últimos veinte años todos los casos diagnosticados de necrolisis epidérmica tóxica en el centro. Se encuentra que un 20% de estos pacientes habían estado expuestos a carbamazepina en las 6 semanas previas al diagnóstico, mientras que un 10% habían estado expuestos a fenitoína. ¿A cuál de los siguientes corresponde el diseño de este estudio?", "opcion_a": "Un estudio ecológico.", "opcion_b": "Un estudio de casos y controles.", "opcion_c": "Un estudio de prevalencia.", "opcion_d": "Un estudio descriptivo.", "correcta": "D", "explicacion": "La respuesta correcta es D) Un estudio descriptivo: el registro describe la frecuencia de exposición a fármacos entre los pacientes con necrolisis epidérmica tóxica sin comparar con un grupo sin la enfermedad, por lo que se limita a describir características de los casos. Descartamos A, porque un estudio ecológico analiza datos a nivel poblacional y no casos individuales. Descartamos B, porque un estudio de casos y controles requiere un grupo de control sin la enfermedad para comparar exposiciones. Descartamos C, porque un estudio de prevalencia se centra en la proporción de enfermedad en una población en un momento dado, no en la descripción de exposiciones en casos ya diagnosticados.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 214, "especialidad": "Bioestadística", "tema": "Diseños de estudios epidemiológicos: cohortes, casos-control y transversales", "pregunta": "Se está evaluando la supervivencia de los pacientes infectados por el virus de inmunodeficiencia humana (VIH) en función del momento de adquisición de la infección. ¿Cuál de las siguientes pruebas es la más adecuada para el objetivo propuesto?", "opcion_a": "Prueba t de Student.", "opcion_b": "Cálculo de la regresión lineal.", "opcion_c": "Estimador de Kaplan-Meier.", "opcion_d": "Cálculo de la regresión logística.", "correcta": "C", "explicacion": "La respuesta correcta es C) Estimador de Kaplan-Meier: permite estimar la función de supervivencia y comparar curvas según el momento de adquisición de la infección, manejando censura de datos. Es la herramienta estándar en estudios de tiempo hasta evento. Descartamos A, porque la prueba t compara medias de variables continuas y no tiempos de supervivencia. Descartamos B, porque la regresión lineal asume una relación lineal entre variables y no trata censura. Descartamos D, porque la regresión logística modela probabilidades de un evento binario y no el tiempo de ocurrencia.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 215, "especialidad": "Bioestadística", "tema": null, "pregunta": "¿Con cuáles de las siguientes medidas podemos reducir la amplitud de un intervalo de confianza?", "opcion_a": "Aumentando el tamaño muestral o disminuyendo el grado de confianza.", "opcion_b": "Disminuyendo el tamaño muestral o disminuyendo el grado de confianza.", "opcion_c": "Aumentando el tamaño muestral o disminuyendo la potencia estadística.", "opcion_d": "Aumentando el tamaño muestral o aumentando el grado de confianza.", "correcta": "A", "explicacion": "La respuesta correcta es A) Aumentando el tamaño muestral o disminuyendo el grado de confianza: al incrementar n disminuye el error estándar y al reducir el nivel de confianza se reduce el valor crítico, lo que estrecha el intervalo. Descartamos B, porque disminuir el tamaño muestral aumentaría la amplitud del intervalo aunque el grado de confianza sea menor. Descartamos C, porque la potencia estadística no afecta directamente al ancho del intervalo de confianza. Descartamos D, porque aumentar el grado de confianza implica un valor crítico mayor y ensancha el intervalo.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 216, "especialidad": "Bioestadística", "tema": "Evaluación económica en salud", "pregunta": "Respecto a los análisis de sensibilidad en evaluaciones farmacoeconómicas, señale la respuesta FALSA:", "opcion_a": "Es un análisis de la incertidumbre.", "opcion_b": "Pueden ser multivariantes.", "opcion_c": "El análisis de sensibilidad de extremos es univariante.", "opcion_d": "La simulación de Monte Carlo es un tipo de análisis de sensibilidad probabilístico.", "correcta": "C", "explicacion": "La respuesta correcta es C) El análisis de sensibilidad de extremos es univariante: en la práctica este tipo de análisis evalúa simultáneamente los valores más favorables y menos favorables de varios parámetros, por lo que es multivariante. Por tanto, no se limita a variar un solo parámetro. Descartamos A, porque el análisis de sensibilidad sirve precisamente para explorar la incertidumbre de los parámetros del modelo. Descartamos B, porque existen análisis de sensibilidad multivariantes que varían varios parámetros a la vez. Descartamos D, porque la simulación de Monte Carlo incorpora distribuciones de probabilidad para los parámetros y constituye un análisis de sensibilidad probabilístico.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 217, "especialidad": "Bioestadística", "tema": "Medición de la carga de enfermedad y salud poblacional", "pregunta": "La calidad de vida relacionada con la salud (CVRS) se evalúa mediante:", "opcion_a": "Cuestionarios estandarizados con propiedades métricas demostradas.", "opcion_b": "Radiografía simple de tórax y analítica global de sangre y orina.", "opcion_c": "Conjunto mínimo básico de datos (CMBD).", "opcion_d": "Pruebas de cribaje de alta sensibilidad y especificidad.", "correcta": "A", "explicacion": "La respuesta correcta es A) Cuestionarios estandarizados con propiedades métricas demostradas: estos instrumentos permiten medir la percepción subjetiva de salud y bienestar mediante ítems validados que garantizan fiabilidad y validez, y son la herramienta recomendada por organismos internacionales para la evaluación de la CVRS. Además, su estandarización facilita la comparación entre poblaciones y la monitorización a lo largo del tiempo. Descartamos B, porque la radiografía y los análisis de laboratorio no capturan la dimensión subjetiva de la calidad de vida. Descartamos C, porque el Conjunto mínimo básico de datos recoge información clínica básica pero no incluye ítems específicos de CVRS. Descartamos D, porque las pruebas de cribado se enfocan en la detección de enfermedad y no en la valoración global del estado de salud percibido.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 218, "especialidad": "Miscelánea", "tema": null, "pregunta": "¿Cuáles son las características del sistema sanitario español?", "opcion_a": "Financiación pública, cobertura universal, asistencia sanitaria integral, equidad basada en la accesibilidad y descentralización territorial.", "opcion_b": "Financiación pública, cobertura universal, asistencia sanitaria integral, eficacia y centralización territorial.", "opcion_c": "Financiación mixta (pública y privada), gestión mixta (pública y privada) y centralización territorial.", "opcion_d": "Financiación por cuotas de la seguridad social, gestión mixta (pública y privada) y descentralización territorial.", "correcta": "A", "explicacion": "La respuesta correcta es A) Financiación pública, cobertura universal, asistencia sanitaria integral, equidad basada en la accesibilidad y descentralización territorial: el Sistema Nacional de Salud se financia con fondos públicos, garantiza la atención a toda la población sin exclusiones, ofrece una cobertura completa de servicios y procura la igualdad de acceso mediante la organización descentralizada en las comunidades autónomas. Estos principios están recogidos en la Ley General de Sanidad y constituyen la base del modelo español. Descartamos B, porque incluye eficacia y centralización territorial, conceptos que no describen la estructura real del sistema. Descartamos C, porque menciona financiación mixta y gestión mixta, lo cual no corresponde al modelo mayoritariamente público. Descartamos D, porque habla de financiación por cuotas de la seguridad social y gestión mixta, que no refleja la financiación pública general ni la descentralización territorial.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 219, "especialidad": "Bioestadística", "tema": null, "pregunta": "Cochrane, una organización independiente cuyo fin es aportar la mejor evidencia disponible, acostumbra a fundamentar sus recomendaciones en revisiones sistemáticas. ¿De qué cree que se trata esta metodología?", "opcion_a": "De un estudio con distribución al azar de los participantes entre el grupo de intervención y el grupo control.", "opcion_b": "De una técnica estadística que permite combinar los hallazgos de varios estudios independientes entre sí.", "opcion_c": "De una búsqueda estructurada a partir de una pregunta bien delimitada y de un protocolo explícito.", "opcion_d": "De una técnica de consenso científico válida para grupos de colaboración independientes.", "correcta": "C", "explicacion": "La respuesta correcta es C) De una búsqueda estructurada a partir de una pregunta bien delimitada y de un protocolo explícito: las revisiones sistemáticas de Cochrane se basan en una pregunta clara, criterios de inclusión y exclusión predefinidos y una búsqueda exhaustiva en bases de datos para identificar todos los estudios relevantes. Este enfoque garantiza la transparencia y la reproducibilidad de los hallazgos. Descartamos A, porque no se trata de un ensayo clínico aleatorizado sino de una metodología de síntesis de evidencia. Descartamos B, porque aunque la combinación de resultados es parte del proceso, la característica esencial es la búsqueda estructurada y el protocolo. Descartamos D, porque no es simplemente un consenso de expertos, sino una revisión sistemática con método reproducible.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 220, "especialidad": "Pediatría", "tema": "Nutrición, lactancia y cuidados del lactante sano", "pregunta": "¿Cuál es el lugar anatómico recomendado para la administración de una vacuna por vía intramuscular en lactantes de menos de 12 meses de edad?", "opcion_a": "Recto anterior del abdomen.", "opcion_b": "Deltoides.", "opcion_c": "Cara anterolateral externa del muslo (músculo vasto externo).", "opcion_d": "Región dorso-glútea (cuadrante superior externo del glúteo mayor).", "correcta": "C", "explicacion": "La respuesta correcta es C) Cara anterolateral externa del muslo (músculo vasto externo): es el sitio recomendado para inyección intramuscular en lactantes menores de 12 meses porque el músculo vasto externo está bien desarrollado, es superficial y aleja la aguja de estructuras neurovasculares importantes. Además, permite una absorción adecuada del fármaco y reduce el riesgo de complicaciones. Descartamos A, porque la zona del recto anterior del abdomen no es un sitio recomendado para inyección intramuscular en lactantes, al no proporcionar un músculo adecuado y presentar mayor riesgo de complicaciones. Descartamos B, porque el deltoides en lactantes no tiene suficiente masa muscular y aumenta el riesgo de lesión de estructuras subyacentes. Descartamos D, porque la región dorso-glútea en lactantes presenta riesgo de lesión del nervio ciático y la masa muscular no es suficiente para una inyección segura.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 221, "especialidad": "Pediatría", "tema": "Enfermedades exantemáticas e infecciones pediátricas clásicas", "pregunta": "¿Cuál de las siguientes vacunas está recomendada para su administración a los 12 meses con una dosis de refuerzo a los 3-4 años?", "opcion_a": "Hepatitis B.", "opcion_b": "Triple vírica.", "opcion_c": "Varicela.", "opcion_d": "Vacuna frente al neumococo.", "correcta": "B", "explicacion": "La respuesta correcta es B) Triple vírica: en el calendario vacunal infantil español, la vacuna triple vírica (sarampión, rubeola y parotiditis) se administra con una primera dosis a los 12 meses y una segunda dosis a los 3-4 años. Descartamos A, porque la vacuna de la hepatitis B forma parte de la vacuna hexavalente y se administra en el primer año de vida, sin dosis a los 12 meses ni refuerzo a los 3-4 años. Descartamos C, porque la primera dosis de la vacuna de la varicela se programa a los 15 meses, no a los 12, aunque la segunda dosis también se pone a los 3-4 años. Descartamos D, porque la vacuna antineumocócica conjugada se administra a los 2, 4 y 11 meses, sin refuerzo a los 3-4 años.", "explicacion_calidad": "revisada", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 222, "especialidad": "Bioestadística", "tema": "Pruebas diagnósticas: sensibilidad, especificidad y valores predictivos", "pregunta": "¿Cuál de las siguientes características tiene MENOS importancia en un programa de cribado (o detección precoz) poblacional?", "opcion_a": "Que la prueba diagnóstica para la detección precoz sea muy específica.", "opcion_b": "Que la identificación precoz del trastorno permita aplicar intervenciones que mejoren su pronóstico.", "opcion_c": "Que el proceso de detección precoz sea económicamente rentable.", "opcion_d": "Que el programa se aplique a un trastorno común con una gran carga de morbilidad.", "correcta": "A", "explicacion": "La respuesta correcta es A) Que la prueba diagnóstica para la detección precoz sea muy específica: en un programa de cribado la prioridad es una alta sensibilidad para no perder casos, mientras que la especificidad puede ser menor pues los falsos positivos se pueden confirmar con pruebas posteriores; por ello la especificidad tiene menor peso que otros criterios. Descartamos B, porque la detección precoz debe permitir intervenciones que realmente mejoren el pronóstico del trastorno. Descartamos C, porque la rentabilidad económica es esencial para que el programa sea sostenible. Descartamos D, porque un programa de cribado debe centrarse en trastornos comunes y con gran carga de morbilidad.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 223, "especialidad": "Infecciosas", "tema": "Enfermedades importadas, zoonosis y fiebres de origen desconocido — histoplasmosis, leptospirosis, viajes", "pregunta": "Mujer boliviana de 35 años de edad, embarazada de 3 meses, que lleva viviendo 10 años en España con su pareja, que es español y no ha viajado nunca a Latinoamérica. La mujer tiene otros dos hijos con su pareja, nacidos en España y un hermano que vive en Bolivia y otro en España. Durante el embarazo le han diagnosticado infección por Trypanosoma cruzi. ¿Cuál de las siguientes actuaciones a realizar sobre la enfermedad es INCORRECTA?", "opcion_a": "Recomendar que sus hijos se hagan la serología de T. cruzi por el riesgo de transmisión transplacentaria.", "opcion_b": "Informar a la paciente del riesgo de transmisión de T. cruzi y de la actitud que se va a tomar durante el embarazo, parto y postparto.", "opcion_c": "Recomendar que su marido se haga la serología de T. cruzi por el riesgo de haberle transmitido la enfermedad por vía sexual.", "opcion_d": "Recomendar que sus hermanos se hagan la serología de T. cruzi por el riesgo de transmisión vectorial.", "correcta": "C", "explicacion": "La respuesta correcta es C) Recomendar que su marido se haga la serología de T. cruzi por el riesgo de haberle transmitido la enfermedad por vía sexual: la transmisión sexual de T. cruzi es extremadamente rara y no está reconocida como una vía significativa de contagio, por lo que no se justifica solicitar la serología al cónyuge. Descartamos A, porque la transmisión transplacentaria puede afectar a los hijos y la serología es indicada para detectar infección previa. Descartamos B, porque es fundamental informar a la paciente sobre los riesgos de transmisión congénita y las medidas a seguir durante el embarazo, el parto y el postparto. Descartamos D, porque los hermanos pueden haber contraído la infección por exposición al vector y la serología es recomendada para identificar casos asintomáticos.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 224, "especialidad": "Bioestadística", "tema": "Diseños de estudios epidemiológicos: cohortes, casos-control y transversales", "pregunta": "¿Cuál de las siguientes características es atribuible a los estudios de casos y controles?", "opcion_a": "Permiten conocer el riesgo asociado con la exposición a varios factores.", "opcion_b": "Se incluye un grupo expuesto a un factor y otro grupo no expuesto.", "opcion_c": "Son muy eficientes cuando la prevalencia de exposición al factor es muy baja.", "opcion_d": "Son estudios aleatorizados.", "correcta": "A", "explicacion": "La respuesta correcta es A) Permiten conocer el riesgo asociado con la exposición a varios factores: los estudios de casos y controles son retrospectivos y permiten estimar la asociación entre la enfermedad y múltiples exposiciones mediante el cálculo de odds ratios, lo que brinda información sobre el riesgo relativo de varios factores. Al comparar la frecuencia de exposición entre casos y controles, se pueden identificar varios factores de riesgo simultáneamente. Descartamos B, porque en los estudios de casos y controles no se seleccionan grupos expuestos y no expuestos, sino casos con enfermedad y controles sin ella. Descartamos C, porque la eficiencia de los casos y controles no depende de la prevalencia de exposición, sino de la rareza de la enfermedad. Descartamos D, porque no son ensayos aleatorizados, sino estudios observacionales.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 225, "especialidad": "Bioestadística", "tema": "Diseños de estudios epidemiológicos: cohortes, casos-control y transversales", "pregunta": "Cuando se elabora el protocolo de un proyecto de investigación, ¿cuál de los siguientes aspectos debe acometerse en primer lugar?", "opcion_a": "Definir los objetivos.", "opcion_b": "Justificar el problema.", "opcion_c": "Establecer la población de referencia.", "opcion_d": "Definir la hipótesis.", "correcta": "B", "explicacion": "La respuesta correcta es B) Justificar el problema: antes de cualquier otro elemento del protocolo es imprescindible argumentar la relevancia del tema y la necesidad de investigarlo, pues esto fundamenta la financiación y la aceptación ética. Además, la justificación orienta la formulación de objetivos, hipótesis y la selección de la población. Descartamos A, porque los objetivos se establecen una vez se ha demostrado la pertinencia del problema. Descartamos C, porque la población de referencia se define después de haber planteado la cuestión de investigación y sus objetivos. Descartamos D, porque la hipótesis se formula con base en la justificación del problema y los objetivos definidos.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 226, "especialidad": "Cirugía", "tema": "Infecciones quirúrgicas y manejo de heridas", "pregunta": "Un hombre de 35 años acude a urgencias con dolor perianal intenso y fiebre de 38°C de dos días de evolución. En la exploración presenta una masa dolorosa en fosa isquio-rectal izquierda. ¿Cuál es la actitud más adecuada?", "opcion_a": "Antibióticos de amplio espectro y controlar evolución.", "opcion_b": "Realizar ecoendoscopia y PAAF ecoguiada.", "opcion_c": "Drenaje bajo anestesia regional.", "opcion_d": "Realizar una TC y así valorar la vía de abordaje para su correcto tratamiento.", "correcta": "C", "explicacion": "La respuesta correcta es C) Drenaje bajo anestesia regional: en presencia de una masa dolorosa en la fosa isquiorrectal y fiebre, se sospecha un absceso perianal que requiere drenaje quirúrgico inmediato para evitar complicaciones; la anestesia regional permite un manejo eficaz y menos doloroso. Descartamos A, porque los antibióticos solos no evacúan el contenido purulento y no resuelven la fuente de infección; Descartamos B, porque la ecoendoscopia y la PAAF no son necesarias cuando el diagnóstico clínico es evidente y retrasan el tratamiento definitivo; Descartamos D, porque la TC no aporta información adicional que justifique su uso antes del drenaje y retrasa la intervención.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 227, "especialidad": "Cardiología", "tema": "Cardiopatía isquémica", "pregunta": "En prevención secundaria, tras un infarto agudo de miocardio, ¿cuál de las siguientes medidas NO ha demostrado efecto beneficioso?", "opcion_a": "Ejercicio físico.", "opcion_b": "Antagonistas del calcio.", "opcion_c": "Ácido acetilsalicílico.", "opcion_d": "Betabloqueantes.", "correcta": "B", "explicacion": "La respuesta correcta es B) Antagonistas del calcio: no hay evidencia robusta de que los bloqueadores de los canales de calcio reduzcan la mortalidad ni los eventos cardiovasculares en la fase de prevención secundaria tras un infarto, y los ensayos clínicos no han demostrado un beneficio adicional frente a otras terapias estándar. Por ello, su uso rutinario no está recomendado en esta situación. Descartamos A, porque el ejercicio físico estructurado ha demostrado reducir la mortalidad y la reincidencia de eventos isquémicos. Descartamos C, porque el ácido acetilsalicílico es la base de la terapia antitrombótica y ha mostrado disminuir la mortalidad y los nuevos infartos. Descartamos D, porque los betabloqueantes mejoran la supervivencia y reducen la reinfusión de isquemia tras el infarto.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 228, "especialidad": "Bioestadística", "tema": "Ensayos clínicos y fases de investigación", "pregunta": "En el diseño de los ensayos clínicos, la asignación aleatoria permite reducir el riesgo de las siguientes causas de sesgos, EXCEPTO una:", "opcion_a": "Expectativas en torno a los tratamientos estudiados.", "opcion_b": "Cambios en los estándares de tratamiento a lo largo del tiempo.", "opcion_c": "Diferencias en la práctica clínica entre centros participantes.", "opcion_d": "Variabilidad de los factores pronósticos desconocidos entre individuos.", "correcta": "B", "explicacion": "La respuesta correcta es B) Cambios en los estándares de tratamiento a lo largo del tiempo: la asignación aleatoria reparte al azar a los pacientes entre los grupos de comparación, por lo que equilibra las características de los participantes y evita que alguien decida quién recibe cada tratamiento. Lo que no puede controlar es que, durante un ensayo largo, cambien los tratamientos estándar o las pautas de manejo, algo que afecta a la interpretación y a la aplicabilidad de los resultados y que debe abordarse en el diseño, no con el azar. Descartamos A, porque la asignación aleatoria con ocultación de la secuencia impide que las expectativas del investigador sobre los tratamientos influyan en a qué grupo va cada paciente. Descartamos C, porque la aleatorización, sobre todo si se estratifica por centro, reparte a los pacientes de cada centro entre los grupos y neutraliza las diferencias de práctica clínica entre centros. Descartamos D, porque equilibrar entre los grupos tanto los factores pronósticos conocidos como los desconocidos es precisamente la principal ventaja de la aleatorización.", "explicacion_calidad": "revisada", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 229, "especialidad": "Infecciosas", "tema": "Infecciones de transmisión sexual y VIH — sífilis, VIH, infecciones congénitas/perinatales relacionadas", "pregunta": "¿Cuál de las siguientes entidades NO es una enfermedad de transmisión sexual producida por Chlamydia trachomatis?", "opcion_a": "Perihepatitis.", "opcion_b": "Uretritis.", "opcion_c": "Chancroide.", "opcion_d": "Linfogranuloma venéreo.", "correcta": "C", "explicacion": "La respuesta correcta es C) Chancroide: la enfermedad es causada por Haemophilus ducreyi y no por Chlamydia trachomatis, por lo que no pertenece al grupo de ETS por este agente. Descartamos A, porque la perihepatitis de Fitz Hugh Curtis es una complicación típica de la infección pélvica por C. trachomatis. Descartamos B, porque la uretritis no gonocica es una manifestación clínica frecuente de C. trachomatis. Descartamos D, porque el linfogranuloma venéreo es una infección causada por C. trachomatis.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 230, "especialidad": "Respiratorio", "tema": "Enfermedad pulmonar intersticial y ocupacional", "pregunta": "Mujer de 50 años, no fumadora que presenta desde hace tres años disnea progresiva y tos no productiva. Auscultación con crepitantes finos basales. Pruebas funcionales respiratorias: FVC 89%, FEV1 65%, FEV1/FVC 60%, TLC 130%, RV 170%, RV/TLC 150%, DLCOc 56%. En TC imágenes quísticas diseminadas. ¿Cuál de estos diagnósticos le parece el más probable?", "opcion_a": "EPOC.", "opcion_b": "Linfangioleiomiomatosis.", "opcion_c": "Fibrosis pulmonar idiopática.", "opcion_d": "Histiocitosis X.", "correcta": "B", "explicacion": "La respuesta correcta es B) Linfangioleiomiomatosis: la combinación de disnea progresiva, tos seca, crepitantes finos, una función pulmonar con disminución moderada del FEV1 y relación FEV1/FVC reducida, hiperinsuflación marcada (TLC y RV muy elevados) y una DLCO reducida, junto con la presencia de quistes pulmonares difusos en la TC, es típica de esta enfermedad rara que afecta a mujeres jóvenes no fumadoras. Descartamos A, porque el EPOC se asocia a tabaquismo y a una obstrucción espiratoria predominante sin quistes extensos. Descartamos C, porque la fibrosis pulmonar idiopática muestra patrón restrictivo con disminución de TLC y ausencia de quistes. Descartamos D, porque la histiocitosis X presenta nódulos y cavidades, no quistes difusos y suele acompañarse de infiltrados sistémicos.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 231, "especialidad": "Ética médica", "tema": "Toma de decisiones al final de la vida — limitación del esfuerzo terapéutico, futilidad, sedación paliativa, retirada de soporte vital", "pregunta": "En relación a los cuidados paliativos indique la respuesta correcta:", "opcion_a": "Comienzan cuando termina el tratamiento activo y se considera que ya no hay nada más que hacer.", "opcion_b": "Finalizan con la muerte del paciente.", "opcion_c": "Se aplican desde las fases tempranas de la enfermedad.", "opcion_d": "Interfieren en el curso de la enfermedad.", "correcta": "-", "explicacion": null, "explicacion_calidad": null, "imagen_path": null, "anulada": true, "motivo_anulacion": "Anulada en la plantilla oficial del Ministerio de Sanidad (sin respuesta correcta).", "requiere_revision": false, "motivo_revision": null}, {"numero": 232, "especialidad": "Reumatología", "tema": "Espondiloartropatías", "pregunta": "¿Qué prueba complementaria tiene una MENOR relevancia en el diagnóstico de espondiloartritis axial?", "opcion_a": "Resonancia magnética de sacroiliacas.", "opcion_b": "HLA-B27.", "opcion_c": "Radiografía de sacroiliacas.", "opcion_d": "Velocidad de sedimentación globular.", "correcta": "D", "explicacion": "La respuesta correcta es D) Velocidad de sedimentación globular: aunque la VSG puede estar elevada en procesos inflamatorios, no es específica ni esencial para confirmar la espondiloartritis axial, pues su alteración se produce en múltiples patologías y puede ser normal en pacientes con enfermedad activa. Descartamos A, porque la resonancia magnética de sacroiliacas permite detectar inflamación activa y erosiones tempranas, siendo fundamental para el diagnóstico precoz. Descartamos B, porque la presencia del HLA-B27, aunque no diagnóstica por sí sola, constituye un marcador genético de gran valor en el contexto clínico. Descartamos C, porque la radiografía de sacroiliacas sigue siendo la prueba estructural de referencia para identificar cambios crónicos característicos.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 233, "especialidad": "Ginecología", "tema": "Patología uterina benigna — miomas, sangrado uterino anormal", "pregunta": "Mujer de 45 años. Dos gestaciones previas con partos normales (G2PN2). Sangrado menstrual abundante desde hace aproximadamente 1 año. En ecografía se observa un mioma subseroso de 2 cm que ha permanecido estable desde hace varios años. Se realiza biopsia endometrial que resulta normal. La paciente presenta hemoglobina 10 g/dL a pesar de ferroterapia oral y la cantidad de flujo menstrual no ha disminuido a pesar de tratamiento con ácido tranexámico y ácido mefenámico. ¿Cuál de los siguientes es el tratamiento de primera elección en esta paciente?", "opcion_a": "Histerectomía total conservando anejos.", "opcion_b": "Anticonceptivos combinados orales.", "opcion_c": "Ablación endometrial.", "opcion_d": "DIU de levonorgestrel.", "correcta": "D", "explicacion": "La respuesta correcta es D) DIU de levonorgestrel: el dispositivo libera levonorgestrel de forma local, disminuye el flujo menstrual y es eficaz en presencia de mioma subseroso pequeño, evitando una cirugía innecesaria. Además, preserva el útero y está recomendado como primera línea para la menorragia cuando existen opciones conservadoras. Descartamos A, porque la histerectomía total es un tratamiento definitivo y excesivo para una menorragia causada por un mioma subseroso pequeño. Descartamos B, porque los anticonceptivos combinados pueden reducir el sangrado pero son menos eficaces que el DIU de levonorgestrel en este contexto. Descartamos C, porque la ablación endometrial, aunque no está contraindicada, tiene menor efectividad en presencia de miomas y el DIU de levonorgestrel es preferido como primera opción.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 234, "especialidad": "Nefrología", "tema": "Glomerulonefritis y enfermedades glomerulares", "pregunta": "¿Cuál de las siguientes glomerulopatías es la causa más frecuente de síndrome nefrótico en el anciano?", "opcion_a": "Glomerulonefritis membranosa.", "opcion_b": "Glomeruloesclerosis segmentaria focal.", "opcion_c": "Nefropatía diabética.", "opcion_d": "Amiloidosis renal.", "correcta": "A", "explicacion": "La respuesta correcta es A) Glomerulonefritis membranosa: es la glomerulopatía más frecuente que produce síndrome nefrótico en pacientes mayores, ya que su incidencia aumenta con la edad y se presenta típicamente con proteinuria masiva. Descartamos B, porque la glomeruloesclerosis segmentaria focal es más típica de adultos jóvenes y no constituye la causa principal en el anciano. Descartamos C, porque la nefropatía diabética, aunque frecuente, se asocia a diabetes y no es la causa más frecuente de síndrome nefrótico idiopático en el anciano. Descartamos D, porque la amiloidosis renal es una entidad poco frecuente y no representa la causa principal de síndrome nefrótico en esta población.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}, {"numero": 235, "especialidad": "Neurología", "tema": "Esclerosis múltiple y enfermedades desmielinizantes", "pregunta": "¿Cuál de los siguientes supuestos clínicos es más probable que se corresponda con una esclerosis múltiple?", "opcion_a": "Mujer de 36 años que nota descargas eléctricas desde la región cervical a las nalgas al doblar el cuello, con hallazgo exploratorio de piramidalismo en ambas piernas y hemihipoestesia con nivel D1.", "opcion_b": "Mujer de 22 años con crisis tónico-clónicas generalizadas de reciente comienzo, examen neurológico normal y esclerosis temporal mesial en RM craneal.", "opcion_c": "Hombre de 42 años con parestesias subagudas ascendentes por ambas piernas y brazos, paraparesia simétrica y arreflexia universal.", "opcion_d": "Hombre de 54 años con deterioro cognitivo de curso rápidamente progresivo en el que la RM craneal demostró lesiones hiperintensas periventriculares múltiples y lagunas subcorticales.", "correcta": "A", "explicacion": "La respuesta correcta es A) Mujer de 36 años que nota descargas eléctricas desde la región cervical a las nalgas al doblar el cuello, con hallazgo exploratorio de piramidalismo en ambas piernas y hemihipoestesia con nivel D1: la presencia del signo de Lhermitte y la evidencia de compromiso piramidal bilateral indican una lesión desmielinizante del tronco encefálico y de la médula cervical. Además, la distribución sensitiva con nivel D1 sugiere diseminación en el espacio, característica de la esclerosis múltiple. Descartamos B, porque la clínica se corresponde con crisis epilépticas y una lesión mesial temporal que no es típica de esclerosis múltiple. Descartamos C, porque el cuadro ascendente, simétrico y la arreflexia universal apuntan a una polirradiculoneuritis inflamatoria aguda, como el síndrome de Guillain‑Barré. Descartamos D, porque el deterioro cognitivo rápido y las lesiones periventriculares aisladas son más sugestivas de una demencia subaguda o de una leucoencefalopatía, no del patrón clínico de esclerosis múltiple.", "explicacion_calidad": "orientativa", "imagen_path": null, "anulada": false, "motivo_anulacion": null, "requiere_revision": false, "motivo_revision": null}]$J$::jsonb) AS r(numero int,especialidad text,tema text,pregunta text,opcion_a text,opcion_b text,opcion_c text,opcion_d text,correcta text,explicacion text,explicacion_calidad text,imagen_path text,anulada boolean,motivo_anulacion text,requiere_revision boolean,motivo_revision text)
WHERE NOT EXISTS (SELECT 1 FROM preguntas p WHERE p."año"=2017 AND p.numero=r.numero);
